E["npc:braenna-flintcrag"] = {t="npc",n="Braenna Flintcrag",z="darnassus",s="Braenna Flintcrag is a dwarven priest trainer stationed within the Hall of Mysteries in Ironforge's Mystic Ward. She instructs devout followers of the Holy Light, guiding dwarven acolytes as they develop their spiritual disciplines and healing arts. She also assists traveling priests returning to the mountain city after their duties across Azeroth.",h="Braenna Flintcrag is a dwarven priest trainer stationed within the Hall of Mysteries in Ironforge's Mystic...",sec={{t="A Guide in the Hall of Mysteries",b="Residing within the quiet alcoves of the Hall of Mysteries in Ironforge's Mystic Ward, Braenna Flintcrag serves the Alliance as a dedicated priest trainer. While Ironforge is renowned for its roaring forges and martial warriors, devout dwarves like Braenna tend to the spiritual welfare of Khaz Modan. She mentors novices answering the call of the Holy Light, teaching the dual disciplines of restorative mending and defensive warding required to survive in an increasingly dangerous world.",sp=0}},faq={{q="Who is Braenna Flintcrag?",a="Braenna Flintcrag is a dwarven priest trainer situated in the Hall of Mysteries within Ironforge's Mystic Ward. She educates priests in new holy prayers, spells, and spiritual disciplines.",al={"braenna flintcrag","who is braenna","priest trainer braenna"}},{q="Where can I find Braenna Flintcrag?",a="You can find her inside the Hall of Mysteries, a large sanctuary dedicated to the arcane and divine arts located in the Mystic Ward of Ironforge.",al={"where is braenna","braenna flintcrag location","find braenna flintcrag"}},{q="What services does she provide to travelers?",a="She provides training and rank progression for priests of the Alliance. She also serves as a point of contact for priests directed back to Ironforge through quests like Returning Home.",al={"braenna services","what does braenna do","can braenna train me"}},{q="Is she related to anyone else in Khaz Modan?",a="She shares the Flintcrag surname with Thulman Flintcrag, suggesting she belongs to a notable dwarven lineage within Khaz Modan.",al={"flintcrag family","thulman flintcrag relative","braenna flintcrag relatives"}}},ang={["class:Priest"]="For dwarven and Alliance priests, Braenna is a reliable mentor in Ironforge to learn essential spells, master the Light, and report back after travels afar.",["race:Dwarf"]="Braenna represents the deep-seated spiritual devotion found among the dwarves of Ironforge, balancing martial grit with devout service to the Holy Light."},kw={"braenna flintcrag","hall of mysteries","holy light","ironforge","mystic ward","priest trainer","returning home"},rel={"subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","topic:dwarf","quest:5628"},src={"Braenna Flintcrag"}}
E["npc:brother-joshua"] = {t="npc",n="Brother Joshua",z="darnassus",s="Brother Joshua is a human priest of the Church of the Holy Light stationed within the grand Cathedral of Light in Stormwind. Dedicated to guiding the faithful, he trains novice priests in channeling the Holy Light to mend wounds and bolster their allies. His quiet service anchors the day-to-day spiritual instruction carried out in the heart of the kingdom.",h="Brother Joshua is a human priest of the Church of the Holy Light stationed within the grand Cathedral of...",sec={{t="A Mentor in the Cathedral",b="Within the serene halls of the Cathedral of Light, Brother Joshua stands near the main altar, ready to instruct newly called servants of the faith. As a priest trainer for the Church of the Holy Light, Joshua provides instruction on the foundational disciplines of healing, protective wards, and the spiritual focus required to commune with the Light. For young human priests starting their service to the Alliance, he represents one of their first guides into deeper communion with the divine.",sp=0}},faq={{q="Who is Brother Joshua?",a="Brother Joshua is a human priest and trainer within the Church of the Holy Light. He is stationed inside Stormwind's Cathedral of Light, where he instructs aspiring priests in their spells, rituals, and sacred duties.",al={"who is brother joshua","brother joshua role","joshua priest"}},{q="Where can I find Brother Joshua?",a="He can be found standing toward the back of the Cathedral of Light in the Cathedral Square of Stormwind City, near the high altar.",al={"brother joshua location","where is brother joshua","where is joshua"}},{q="What services does he offer?",a="Brother Joshua offers priestly instruction, helping priests learn new ranks of divine and restorative spells, as well as allowing them to reset their spiritual talents.",al={"what does joshua do","brother joshua training","can joshua train me"}}},ang={["class:Priest"]="Brother Joshua serves as a primary mentor in Stormwind, guiding your study of the Holy Light and helping you unlock new prayers and disciplines as you advance.",["faction:Alliance"]="Based in the Cathedral of Light, Joshua represents the enduring spiritual resilience of the Church of the Holy Light in the heart of the Alliance."},kw={"brother joshua","cathedral of light","holy light","human priest","priest trainer","stormwind"},rel={"subzone:cathedral-of-light","topic:church-of-the-holy-light","topic:light","topic:stormwind-kingdom","quest:5628"},src={"Brother Joshua"}}
E["npc:chief-archaeologist-greywhisker"] = {t="npc",n="Chief Archaeologist Greywhisker",z="darnassus",s="Chief Archaeologist Greywhisker is an emissary of the dwarven Explorers' League stationed in Darnassus outside the Temple of the Moon. Sent from Ironforge across the sea to northern Kalimdor, he seeks to uncover ancient history and coordinates dwarven field research throughout the region. Currently, he is preoccupied with gathering field reports and tracking lost colleagues operating in Darkshore.",h="Chief Archaeologist Greywhisker is an emissary of the dwarven Explorers' League stationed in Darnassus...",sec={{t="A Dwarven Scholar in Darnassus",b="While it is unusual to find an Ironforge dwarf nestled high in the boughs of Teldrassil, Chief Archaeologist Greywhisker represents the far-reaching ambitions of the Explorers' League. Having traded the lecture halls and museum vaults of Ironforge for fieldwork in Kalimdor, he can be found standing outside the Temple of the Moon in Darnassus, conferring with local night elf scholars such as Tarelvir. Greywhisker's academic lectures back in the Eastern Kingdoms famously touched upon ancient lore and primordial entities like the Wild God Agamaggan, and he is eager to see what ancient secrets the night elves' ancestral lands might hold.",sp=0},{t="Eyes on Darkshore",b="Greywhisker's primary role in Kalimdor is to oversee dwarven excavations and keep tabs on expeditions scouring ancient ruins along the coast. Unfortunately for the chief archaeologist, field research in unexplored lands comes with distinct perils. He relies on passing travelers to establish communication with prospectors stationed across the sea in Darkshore, anxiously awaiting news from dig sites and hoping his colleagues haven't succumbed to the dangers lurking among ancient ruins.",sp=0}},faq={{q="Who is Chief Archaeologist Greywhisker?",a="He is a prominent dwarven scholar and representative of the Explorers' League hailing from Ironforge. Stationed outside the Temple of the Moon in Darnassus, he coordinates League research in northern Kalimdor and liaises with night elf scholars.",al={"who is greywhisker","greywhisker lore","chief archaeologist"}},{q="What is an Ironforge dwarf doing in Darnassus?",a="The Explorers' League has dispatched researchers across Azeroth to uncover forgotten history and ancient artifacts. Greywhisker was sent across the sea to establish scholarly contacts in the night elf capital and oversee dwarven expeditions exploring the ancient coastlines of Kalimdor.",al={"why is a dwarf in darnassus","dwarf temple of the moon"}},{q="What is his connection to Agamaggan?",a="Back in Ironforge, Greywhisker was well-known for his scholarly lectures on ancient history. Among the subjects he discussed was the giant boar Wild God, Agamaggan, whose legend inspired younger dwarven prospectors like Lonebrow to study ancient beast folklore.",al={"greywhisker agamaggan","agamaggan lectures"}},{q="Who is Greywhisker talking to outside the temple?",a="Greywhisker stands in Darnassus speaking with Tarelvir, a night elf scholar outside the Temple of the Moon, trading thoughts and coordinating historical research between their peoples.",al={"greywhisker tarelvir","who is with greywhisker"}},{q="What trouble is he dealing with in Darkshore?",a="Greywhisker has deployed fellow dwarven field researchers to Darkshore to excavate ancient ruins, but keeping in touch with isolated expeditions has proven difficult. He frequently seeks couriers to check in on absent-minded prospectors and recover their research journals.",al={"greywhisker darkshore","darkshore prospectors"}},{q="Which faction does Greywhisker belong to?",a="Greywhisker belongs to the Explorers' League, an Ironforge archaeological organization devoted to discovering dwarven origins and ancient history, fully aligned with the Alliance.",al={"greywhisker faction","explorers league darnassus"}}},ang={["race:Dwarf"]="Finding one of Ironforge's premier scholars outside the Temple of the Moon is a comforting reminder of your people's boundless thirst for uncovering ancient history, even in the far corners of Kalimdor.",["race:NightElf"]="Greywhisker represents the newfound alliance between your people and the Eastern Kingdoms, respectfully conferring with scholars outside Elune's temple about the continent's past.",["faction:Alliance"]="He serves as a crucial scholarly and logistical bridge connecting Ironforge's Explorers' League to expeditions stationed across northern Kalimdor."},kw={"agamaggan","chief archaeologist","darkshore","darnassus","explorers' league","greywhisker","ironforge","tarelvir","temple of the moon"},rel={"topic:explorers-league","zone:darnassus","subzone:temple-of-the-moon","zone:darkshore","zone:ironforge","quest:730","quest:729","topic:agamaggan"},src={"Chief Archaeologist Greywhisker"}}
E["npc:elanaria"] = {t="npc",n="Elanaria",z="darnassus",s="Elanaria is a night elf warrior trainer and coordinator stationed on the Warrior's Terrace in Darnassus. She directs developing fighters across Kalimdor, testing their mettle against dangerous threats such as the satyr Vorlus Vilehoof and spiritual entities like the Shade of Elura. Her guidance serves as a crucial bridge for Alliance soldiers honing their martial prowess in the night elven capital.",h="Elanaria is a night elf warrior trainer and coordinator stationed on the Warrior's Terrace in Darnassus.",sec={{t="A Sentinel of the Terrace",b="Standing proudly on the Warrior's Terrace within the boughs of Darnassus, Elanaria serves as an instructor and point of contact for martial champions. In an era where the night elves have formally aligned with the Grand Alliance, her role extends beyond mentoring local Sentinels to preparing warriors of all backgrounds for the harsh challenges facing their lands.",sp=0},{t="Trials of Iron and Spirit",b="Elanaria does not offer easy praise; she expects discipline, resilience, and proven strength. She assigns seasoned adventurers to strike down formidable adversaries plaguing Ashenvale and Darkshore, including the corrupt satyr Vorlus Vilehoof and troubled spirits like the Shade of Elura. She also liaises with skilled craftsmen like Smith Mathiel to ensure that deserving warriors are properly armed for war.",sp=0}},faq={{q="Who is Elanaria?",a="Elanaria is a night elf located on the Warrior's Terrace in Darnassus. She serves as a martial quest giver who tasks rising warriors with combat trials throughout northern Kalimdor.",al={"elanaria darnassus","who is elanaria","elanaria npc"}},{q="Where can I find Elanaria?",a="She is located on the Warrior's Terrace, the elevated northern district of Darnassus dedicated to the city's military training grounds and defenses.",al={"elanaria location","where is elanaria","elanaria spot"}},{q="What quests does Elanaria offer?",a="Elanaria is a key figure in intermediate warrior progression, offering assignments such as hunting down the satyr Vorlus Vilehoof, confronting the Shade of Elura, and coordinating with local armorers like Smith Mathiel.",al={"elanaria quests","quests from elanaria","elanaria warrior quest"}},{q="Why does Elanaria send fighters against Vorlus Vilehoof?",a="Vorlus Vilehoof is a dangerous satyr whose demonic corruption threatens the northern wilds. Elanaria tasks capable warriors with slaying him to both safeguard the forests and prove their battlefield prowess.",al={"elanaria vorlus","vorlus vilehoof quest","why kill vorlus vilehoof"}},{q="Who is Smith Mathiel?",a="Smith Mathiel is a master armorer stationed in Darnassus. Elanaria directs warriors to Mathiel so they may craft or receive specialized martial equipment suitable for frontline combat.",al={"mathiel connection","smith mathiel warrior","elanaria and mathiel"}},{q="Does Elanaria interact with non-night elves?",a="Yes. As part of the Alliance, Elanaria assists all eligible Alliance warriors who arrive on the Warrior's Terrace seeking guidance and specialized training.",al={"can humans talk to elanaria","alliance warrior elanaria"}}},ang={["class:Warrior"]="Elanaria is an essential contact on the Warrior's Terrace, assigning level-appropriate martial trials that reward sturdy equipment and refine tactical combat skills.",["race:NightElf"]="Representing the martial traditions of Darnassus, Elanaria works to purge corrupted entities like satyrs and restless shades from the ancestral lands of the kaldorei.",["faction:Alliance"]="From the capital of Teldrassil, Elanaria helps maintain military readiness and arms soldiers who defend Alliance interests across northern Kalimdor."},kw={"darnassus","elanaria","shade of elura","smith mathiel","teldrassil","vorlus vilehoof","warrior trainer","warrior's terrace"},rel={"subzone:warrior-s-terrace","zone:darnassus","quest:1683","quest:1686","quest:1692","quest:1703","quest:940","topic:night-elf"},src={"Elanaria"}}
E["npc:jannok-breezesong"] = {t="npc",n="Jannok Breezesong",z="darnassus",s="Jannok Breezesong is a night elf rogue trainer stationed in the village of Dolanaar on Teldrassil. He offers instruction in stealth, cunning, and bladecraft to young kaldorei rogues venturing out into the boughs of the World Tree.",h="Jannok Breezesong is a night elf rogue trainer stationed in the village of Dolanaar on Teldrassil.",sec={{t="A Guide in the Shadows",b="Found lounging beneath the boughs of Dolanaar, Jannok Breezesong serves as the primary instructor for novice night elf rogues. Unlike the formal sentinels or cloistered druids of Teldrassil, Jannok guides those who operate quietly on the fringes of society, teaching them how to stalk the shadows, strike from behind, and survive unseen amidst the boughs. Once a rogue has advanced beyond initial lessons in Dolanaar, Jannok directs them onward to more experienced masters in the capital city of Darnassus.",sp=0}},faq={{q="Who is Jannok Breezesong?",a="Jannok Breezesong is a night elf rogue trainer residing in Dolanaar on Teldrassil. He teaches foundational rogue abilities and techniques to young kaldorei.",al={"who is jannok","jannok breezesong role","dolanaar rogue trainer"}},{q="Where does Jannok send advancing rogues?",a="Once a rogue has completed their early training in Dolanaar, Jannok directs them to journey to Darnassus to seek further instruction under Erion Shadewhisper, a senior rogue trainer located in the city's Cenarion Enclave.",al={"jannok quest","erion shadewhisper quest","dolanaar rogue next step"}},{q="Where can I find Jannok in Dolanaar?",a="Jannok is located in Dolanaar, the central settlement of Teldrassil outside of Shadowglen, positioned among the town's trainer pavilions.",al={"jannok location","where is jannok","find jannok breezesong"}}},ang={["class:Rogue"]="For young night elf rogues starting out on Teldrassil, Jannok is your key mentor in Dolanaar before you head to the capital.",["race:NightElf"]="While kaldorei culture often emphasizes sentinels and druidism, trainers like Jannok prepare those who prefer stealth, poisons, and daggers."},kw={"breezesong","dolanaar","erion shadewhisper","jannok","night elf","rogue trainer","teldrassil"},rel={"subzone:dolanaar","quest:2259","quest:940","topic:night-elf"},src={"Jannok Breezesong"}}
E["npc:lelanai"] = {t="npc",n="Lelanai",z="darnassus",s="Lelanai is a night elf mount handler residing in the Cenarion Enclave of Darnassus. She provides the fierce saber mounts of the night elves to worthy riders, offering both standard nightsabers and swift war beasts to her kin and trusted allies of Darnassus.",h="Lelanai is a night elf mount handler residing in the Cenarion Enclave of Darnassus.",sec={{t="Breeder of the Cenarion Enclave",b="Stationed beside riding instructor Jartsam among the towering trees of the Cenarion Enclave, Lelanai attends to some of the finest big cats bred in Kalimdor. Night elves have long formed profound bonds with the fierce predators of northern forests, training nightsabers and frostsabers to carry sentinels and scouts across rugged terrain with predator grace. Lelanai serves as the primary provider of these revered mounts in the capital.",sp=0},{t="Bonds Beyond Kinship",b="While saber mounts are freely offered to any night elf of appropriate skill, outsiders face a much stricter threshold. Given the sacred nature of the cats and the natural aloofness of the kaldorei, Lelanai will not entrust a beast to non-night elf adventurers unless they have earned the highest degree of respect and renown with the city of Darnassus.",sp=0}},faq={{q="Where can I find Lelanai?",a="Lelanai is located in the Cenarion Enclave in Darnassus, standing just beside the tiger riding trainer, Jartsam.",al={"lelanai location","where is lelanai","lelanai map"}},{q="What does Lelanai sell?",a="She sells reins for various breeds of frostsaber, dawnsaber, and nightsaber mounts, including swift armored variations for veteran riders.",al={"lelanai wares","what mounts does she have","night elf mounts"}},{q="Can non-night elves buy mounts from Lelanai?",a="Yes, but only if they have proven exceptional loyalty by reaching exalted reputation with Darnassus. Otherwise, she will refuse to sell her beasts to outsiders.",al={"can humans buy sabers","can dwarfs ride nightsabers","reputation required for sabers"}},{q="Can Horde players interact with Lelanai?",a="No. Lelanai is loyal to the Darnassus faction of the Alliance. Horde members will be treated as hostile invaders by her and the nearby enclave guards.",al={"can horde buy sabers","is lelanai friendly to horde"}}},ang={["race:NightElf"]="For night elves, visiting Lelanai is an essential rite of passage when acquiring their traditional feline steeds.",["faction:Alliance"]="Alliance heroes who earn exalted status with Darnassus can seek out Lelanai to ride the iconic sabers into battle alongside their kaldorei allies."},kw={"cenarion enclave","darnassus","dawnsaber","frostsaber","jartsam","lelanai","mount vendor","nightsaber"},rel={"zone:darnassus","subzone:cenarion-enclave","topic:night-elf","quest:7672","quest:7671"},src={"Lelanai"}}
E["npc:lieutenant-beitha"] = {t="npc",n="Lieutenant Beitha",z="darnassus",s="Lieutenant Beitha is an orc officer of the Argent Dawn stationed within Darnassus. Despite the natural tension between orcs and night elves, she serves the Dawn's neutral mandate by coordinating local defenders against the encroaching Scourge.",h="Lieutenant Beitha is an orc officer of the Argent Dawn stationed within Darnassus.",sec={{t="An Unlikely Presence in Darnassus",b="Orcs are rarely tolerated on the boughs of Teldrassil, but the Argent Dawn answers to a higher calling than the faction wars of Kalimdor. As a lieutenant in the Dawn, Beitha puts aside political allegiance to confront the shared menace of the undead. Stationed in Darnassus during Scourge activity, she directs volunteers and fledgling protectors to scout and combat the encroaching threat beyond the city's gates.",sp=0}},faq={{q="Why is an orc allowed inside Darnassus?",a="Lieutenant Beitha represents the Argent Dawn, a strictly neutral coalition dedicated entirely to fighting the Scourge. Because the Dawn accepts members of all races and focuses on saving Azeroth from the undead, night elf sentinels permit her presence for joint defense.",al={"orc in darnassus","why is beitha in darnassus","hostile orc darnassus"}},{q="What does Lieutenant Beitha do?",a="She acts as a liaison for the Argent Dawn, tasking adventurers with investigating and repelling Scourge incursions threatening the lands surrounding Darnassus.",al={"beitha role","beitha purpose","what does beitha offer"}},{q="What threat is she responding to?",a="She is responding to the Scourge invasion, marshaling local allies to ensure the undead do not establish a foothold on the island or taint the World Tree.",al={"scourge in teldrassil","who is she fighting"}}},ang={["race:NightElf"]="Seeing an orc walking unmolested through the capital is jarring for many night elves, serving as a stark reminder of how dire the Scourge menace truly is.",["race:Orc"]="Beitha exemplifies those rare orcs who have dedicated their lives entirely to the Argent Dawn's crusade, looking past ancient grudges to strike at the undead."},kw={"argent dawn","beitha","darnassus","lieutenant beitha","orc","scourge","scourge invasion","teldrassil"},rel={"topic:argent-dawn","zone:darnassus","topic:scourge","quest:9262"},src={"Lieutenant Beitha"}}
E["npc:malfurion-stormrage"] = {t="npc",n="Malfurion Stormrage",z="darnassus",s="Malfurion Stormrage is the first mortal druid and the revered leader of the night elves alongside High Priestess Tyrande Whisperwind. Renowned for defeating the Burning Legion in both the War of the Ancients and the Third War, he is venerated as the Shan'do, or honored teacher. Currently, he lies trapped in a comatose slumber within the Emerald Dream, leaving the kaldorei without his waking guidance.",h="Malfurion Stormrage is the first mortal druid and the revered leader of the night elves alongside High...",sec={{t="The First Druid",b="Ten thousand years ago, before the Great Sundering shattered ancient Kalimdor, Malfurion studied under the demigod Cenarius. While Queen Azshara and her Highborne caste delved dangerously into the arcane energies of the Well of Eternity, Malfurion turned toward the primal forces of nature, becoming Azeroth's first mortal druid. His suspicions regarding the Highborne proved tragically correct when Azshara's reckless sorcery pierced the veil and summoned Sargeras and the Burning Legion into Azeroth, igniting the catastrophic War of the Ancients.",sp=0},{t="Savior of Kalimdor",b="Alongside Cenarius, Tyrande Whisperwind, and his twin brother Illidan, Malfurion spearheaded the resistance that halted the demon onslaught and closed the portal over the Well of Eternity. Following the world's shattering, Malfurion committed the druids to the Emerald Dream to rebuild and protect Azeroth's living tapestry. Ten millennia later, Tyrande awakened him from his long barrow sleep to confront Archimonde during the Third War, where he rallied the forest spirits at Mount Hyjal to shatter the Burning Legion once more.",sp=0},{t="Lost to the Dream",b="Following the Third War, Malfurion returned to his slumber within the Moonglade to commune with the Emerald Dream and replenish his spent power. However, his spirit has failed to return to his physical body, plunging him into an unnatural, comatose state. In Darnassus, Archdruid Fandral Staghelm has assumed the temporal duties of leadership among the Cenarion Circle, while Tyrande and the sisterhood watch anxiously for signs of their great Shan'do's waking.",sp=0}},faq={{q="Where is Malfurion Stormrage right now?",a="Malfurion is physically asleep in the barrow dens of Moonglade, while his consciousness remains trapped deep within the spirit realm of the Emerald Dream. He cannot be visited as an active NPC in Darnassus, as his body lies comatose and inaccessible to most adventurers.",al={"where is malfurion","where to find malfurion","malfurion location","is malfurion in game"}},{q="Why is Malfurion asleep?",a="Druids regularly hibernate within the Emerald Dream to commune with nature, sustain the world's flora and fauna, and restore their spiritual strength. Following the immense magical strain of defeating Archimonde at Mount Hyjal, Malfurion entered the Dream to recover, but an unnatural malaise has severed his spirit from his body.",al={"why is malfurion sleeping","why is he comatose","what happened to malfurion"}},{q="Who rules the night elves while Malfurion sleeps?",a="High Priestess Tyrande Whisperwind rules the kaldorei nation from the Temple of the Moon in Darnassus, leading the Sentinels and the Sisterhood of Elune. Meanwhile, the Cenarion Circle and druidic affairs are overseen by Archdruid Fandral Staghelm.",al={"who leads night elves","who is the night elf leader","night elf ruler"}},{q="What does 'Shan'do' mean?",a="In Darnassian, 'Shan'do' translates to 'honored teacher.' It is a title of supreme reverence reserved for master druids, most notably Malfurion Stormrage, who first brought druidism to mortal races under the tutelage of Cenarius.",al={"shando meaning","what is shando","shan'do"}},{q="Who is Malfurion's brother?",a="Malfurion's twin brother is Illidan Stormrage. Despite their shared youth in Suramar, Illidan's obsession with arcane magic and reckless pursuit of demonic power caused a bitter rift between them during the War of the Ancients, leading Malfurion to imprison him for millennia.",al={"malfurion brother","who is illidan to malfurion","stormrage brothers"}},{q="What did Malfurion do at the Battle of Mount Hyjal?",a="During the climax of the Third War, Malfurion blew the Horn of Cenarius at the World Tree Nordrassil, calling forth thousands of ancestral forest spirits (wisps). These spirits swarmed the demon lord Archimonde and detonated, destroying the demon and immolating the World Tree to save Kalimdor.",al={"malfurion hyjal","battle of mount hyjal malfurion","how did malfurion defeat archimonde"}}},ang={["class:Druid"]="Every druid traces their teachings back to Malfurion, who learned directly from Cenarius. His absence in the Emerald Dream casts a heavy shadow over the Cenarion Circle.",["race:NightElf"]="Malfurion is revered as the ancient protector and savior of your people, though his continued slumber leaves governance entirely to Tyrande and Archdruid Fandral Staghelm.",["class:Priest"]="Malfurion is the beloved partner of High Priestess Tyrande Whisperwind, uniting the spiritual devotion of Elune with the sacred guardianship of nature."},kw={"archdruid","cenarius","emerald dream","furion","hyjal","illidan","malfurion","shan'do","stormrage","tyrande"},rel={"npc:tyrande-whisperwind","topic:cenarius","topic:emerald-dream","topic:shan-do","topic:druid","topic:war-of-the-ancients","topic:third-war","topic:burning-legion"},src={"Malfurion Stormrage"}}
E["npc:mathrengyl-bearwalker"] = {t="npc",n="Mathrengyl Bearwalker",z="darnassus",s="Mathrengyl Bearwalker is a master druid trainer and respected elder of the Cenarion Circle residing in Darnassus's Cenarion Enclave. Having once served as Archdruid Fandral Staghelm's direct assistant, he guides young Alliance druids through their spiritual trials, shapeshifting rites, and duties across Kalimdor.",h="Mathrengyl Bearwalker is a master druid trainer and respected elder of the Cenarion Circle residing in...",sec={{t="Mentor of the Cenarion Enclave",b="Perched within the verdant reaches of the Cenarion Enclave in Darnassus, Mathrengyl Bearwalker stands as one of the most venerable and balanced druids on Teldrassil. He serves as a primary guide for fledgling Alliance druids, overseeing their communion with Moonglade and testing their readiness to master primal animal forms. Having undergone the intense, bewildering communion with the Great Bear Spirit in his own youth, Mathrengyl understands the weight of these rites, personally charging initiates to prove their spirit against the sacred moonkin Lunaclaw before inducting them into the path of the Druid of the Claw.",sp=0},{t="Service to the Archdruid",b="Mathrengyl has long operated as Fandral Staghelm's second, managing day-to-day circle affairs and handling recruitment for the Archdruid's ambitious endeavors. When Fandral demanded vast quantities of morrowgrain, Mathrengyl organized its collection from returning adventurers, despite privately confiding a quiet unease regarding the strange plant's unnatural essence. He also coordinates Alliance responses to summons from Moonglade, navigating the delicate politics of the Cenarion Circle while Fandral turns his gaze toward southern Kalimdor and the Plaguelands.",sp=0},{t="A Broader Perspective",b="While Staghelm is infamous for his fierce pride and disdain for other races, Mathrengyl often displays a more contemplative, open mind. When relics arrived in Darnassus from the fallen druid Mulgris Deepriver—who perished fighting the Scourge in the Western Plaguelands—Mathrengyl was deeply moved to discover the investigator was a tauren. Reflecting on the Cenarion Circle's shared mission, he quietly mused that the tauren may not have drifted nearly as far from the teachings of Cenarius as the Archdruid insists.",sp=0}},faq={{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a veteran night elf druid trainer stationed in the Cenarion Enclave in Darnassus. Revered as one of Teldrassil's most balanced sages, he instructs initiates in shapeshifting, poison cleansing, and duties on behalf of the Cenarion Circle.",al={"who is mathrengyl","mathrengyl role","bearwalker"}},{q="What is his relationship with Fandral Staghelm?",a="Mathrengyl served as Archdruid Fandral Staghelm's direct assistant and second. While obediently managing Fandral's requests—including gathering morrowgrain and delegating missions—Mathrengyl harbors subtle doubts regarding some of Fandral's harsh viewpoints and eccentric projects.",al={"fandral assistant","staghelm and mathrengyl"}},{q="What forms does Mathrengyl help druids learn?",a="Mathrengyl instructs young druids after their spiritual pilgrimages to Moonglade, overseeing their communion with Lunaclaw to earn Bear Form, as well as concluding their trials in Darkshore and Silverpine to master Aquatic Form.",al={"bear form quest darnassus","aquatic form quest darnassus","druid forms mathrengyl"}},{q="Why is Mathrengyl gathering morrowgrain?",a="He assists Archdruid Fandral Staghelm with ongoing botanical research on Teldrassil by collecting morrowgrain cultivated by adventurers. Even so, Mathrengyl has admitted to feeling deeply uneasy whenever he is in the plant's presence.",al={"morrowgrain quest","why morrowgrain darnassus"}},{q="How does Mathrengyl feel about tauren druids?",a="Unlike Fandral Staghelm, who views tauren druids with open skepticism, Mathrengyl is more thoughtful. After reviewing the sacrifice of a tauren druid fighting the Scourge in the Western Plaguelands, he admitted the tauren might walk closer to the teachings of Cenarius than Fandral allows.",al={"tauren druids","mathrengyl tauren"}},{q="What does he do with the Nightmare Shard?",a="When adventurers bring a corrupted Nightmare Shard to Falla Sagewind, she sends them on to Mathrengyl, who inspects it with great alarm, sensing the creeping corruption threatening the Emerald Dream.",al={"nightmare shard mathrengyl","in nightmares quest"}}},ang={["class:Druid"]="For Alliance druids, Mathrengyl is an essential mentor who bridges Darnassus with Moonglade, unlocking the secrets of Bear Form, Aquatic Form, and herbal cures for deadly poisons.",["faction:Alliance"]="Mathrengyl represents the steady, traditional leadership of the Cenarion Circle in Darnassus, offering a temperate contrast to Fandral Staghelm's aggressive posturing.",["race:NightElf"]="A paragon of Kaldorei druidism, Mathrengyl embodies devotion to nature and balance in the aftermath of the Third War and the growth of Teldrassil."},kw={"aquatic form","bear form","bearwalker","cenarion circle","cenarion enclave","darnassus","druid of the claw","druid trainer","fandral staghelm","mathrengyl bearwalker","morrowgrain","teldrassil"},rel={"npc:fandral-staghelm","subzone:cenarion-enclave","zone:darnassus","npc:dendrite-starblaze","quest:6001","quest:31","quest:3369","topic:cenarion-circle"},src={"Mathrengyl Bearwalker"}}
E["npc:mydrannul"] = {t="npc",n="Mydrannul",z="darnassus",s="Mydrannul is a night elf general goods vendor stationed at the Warrior's Terrace in Darnassus. He serves the capital's sentinels, soldiers, and visitors by keeping basic supplies, munitions, and provisions readily available.",h="Mydrannul is a night elf general goods vendor stationed at the Warrior's Terrace in Darnassus.",sec={{t="Supplies of the Warrior's Terrace",b="Located among the military pavilions and training grounds of the Warrior's Terrace, Mydrannul provides essential gear to Darnassus's defenders and traveling adventurers alike. His wares include the practical everyday items needed for life in the field: ammunition for archers and gunners, throwing blades, flint, pouches, and simple rations. By tending his stall in the city's martial district, he ensures that the sentinels and trainees preparing for duty on Teldrassil do not want for basic sundries.",sp=0}},faq={{q="Where can Mydrannul be found?",a="Mydrannul is located within the Warrior's Terrace, the southeastern martial district of Darnassus situated on the crown of Teldrassil.",al={"mydrannul location","where is mydrannul","mydrannul map"}},{q="What goods does Mydrannul sell?",a="He serves as a general goods vendor, stocking containers, simple rations, drink, and camp craft tools like flint and tinder, alongside throwing weapons and munitions like arrows and bullets.",al={"mydrannul wares","what does mydrannul sell","mydrannul vendor items"}},{q="Does Mydrannul offer any quests?",a="No. Mydrannul is a general goods vendor rather than a quest giver; adventurers visit him for supplies and provisions.",al={"mydrannul quest","quests from mydrannul"}}},ang={["race:NightElf"]="For night elves training in Darnassus, Mydrannul provides essential everyday equipment and arrows to keep Sentinels properly provisioned.",["faction:Alliance"]="Visiting Alliance travelers arriving on Teldrassil can rely on vendors like Mydrannul on the Warrior's Terrace for basic packs, ammunition, and field rations."},kw={"ammunition","darnassus","general goods","mydrannul","teldrassil","vendor","warrior's terrace"},rel={"zone:darnassus","subzone:warrior-s-terrace","quest:6344","topic:night-elf"},src={"Mydrannul"}}
E["npc:nara-meideros"] = {t="npc",n="Nara Meideros",z="darnassus",s="Nara Meideros is a night elf priestess stationed within the tranquil greenery of the Park in Stormwind City. Serving as a mentor to acolytes, she represents the teachings of Elune amidst the human capital.",h="Nara Meideros is a night elf priestess stationed within the tranquil greenery of the Park in Stormwind City.",sec={{t="A Priestess in Stormwind",b="While most priestesses of Elune remain in Kalimdor under the boughs of Teldrassil, Nara Meideros resides far across the Great Sea in Stormwind City. Found within the Park—a haven nurtured by visiting night elf druids and priests—she guides young spiritual seekers in the ways of divine devotion. Alongside human practitioners of the Holy Light in Cathedral Square, Nara offers night elves visiting or living in the Eastern Kingdoms a familiar connection to the grace of the Moon Goddess.",sp=0}},faq={{q="Where can I find Nara Meideros?",a="Nara Meideros is located in the Park district of Stormwind City, surrounded by moonwells and towering trees that remind night elf travelers of home.",al={"nara meideros location","where is nara meideros","park priest trainer"}},{q="What role does Nara Meideros serve?",a="She is a priest trainer who assists novitiates and growing priests, and she directs human priests to the Cathedral of Light to learn devotional spells such as Desperate Prayer.",al={"what does nara do","nara meideros purpose","who is nara meideros"}},{q="Why is a night elf priestess residing in Stormwind?",a="As ties between the night elves of Darnassus and the Grand Alliance strengthen, night elf emissaries, druids, and priests maintain an active presence in the Park to aid their kin and represent their spiritual traditions.",al={"why is she in stormwind","night elf in stormwind"}}},ang={["class:Priest"]="For night elf priests traversing the Eastern Kingdoms, Nara provides guidance and instruction in vital racial devotions without requiring a journey back to Kalimdor.",["race:NightElf"]="Far from the forests of Ashenvale and Teldrassil, Nara Meideros and the Park offer a comforting sliver of home within the bustling stone walls of the human capital."},kw={"elune","nara meideros","night elf priest","priest trainer","stormwind","the park"},rel={"subzone:park","zone:stormwind","quest:5634","quest:5628","topic:night-elf","topic:stormwind-kingdom"},src={"Nara Meideros"}}
E["npc:priestess-a-moora"] = {t="npc",n="Priestess A'moora",z="darnassus",s="Priestess A'moora is a devout night elf servant of the Moon Goddess residing within the Temple of the Moon in Darnassus. Working closely under the guidance of High Priestess Tyrande Whisperwind's priesthood, she attends to rituals of spiritual purification and communion with Elune. Travelers exploring Teldrassil are often directed to her when matters involve sacred offerings and the mystical wildlife of the boughs.",h="Priestess A'moora is a devout night elf servant of the Moon Goddess residing within the Temple of the Moon in...",sec={{t="A Servant of Elune",b="Within the serene marble halls of the Temple of the Moon, Priestess A'moora spends her days in contemplation and service. As an ordained priestess of Elune, she assists in tending the spiritual needs of Darnassus and preserving the delicate rituals passed down through millennia. While much of the Sisterhood oversees military defenses or diplomacy, A'moora focuses on traditional devotions and sacred matters concerning the natural spirits of Teldrassil.",sp=0},{t="Tears of the Moon",b="A'moora is tied to the sad fate of Lady Sathrah, a great spider once beloved of Elune whose silvery dew was kept in the temple for its healing powers. When Sathrah descended into madness, A'moora sent young adventurers to the northern borders of Teldrassil near Wellspring Lake to end her suffering and bring back her silvery spinnerets. Offered at the temple's fountain, the spinnerets become a sacrifice to Elune so that Sathrah might be reborn at peace.",sp=0}},faq={{q="Where can I find Priestess A'moora?",a="Priestess A'moora is located inside the Temple of the Moon in Darnassus, the capital city resting in the canopy of Teldrassil. She stands among the priestesses serving the altar of Elune.",al={"a'moora location","where is priestess amoora","amoora darnassus"}},{q="What is Priestess A'moora's role in Darnassus?",a="She is a member of the Sisterhood of Elune who oversees specific religious ceremonies and sacred offerings. She acts as a quest giver and guide for travelers seeking to perform ancient rites of cleansing and sacrifice on Teldrassil.",al={"what does amoora do","priestess amoora purpose"}},{q="What quests does Priestess A'moora offer?",a="She gives the Tears of the Moon quest chain, sending adventurers to slay the maddened spider Lady Sathrah near Wellspring Lake and then offer her silvery spinnerets as a sacrifice at the temple's fountain.",al={"amoora quests","priestess amoora questline"}},{q="How is Priestess A'moora related to the Temple of the Moon?",a="She is an active attendant in the Temple of the Moon, the spiritual heart of night elf culture ruled by High Priestess Tyrande Whisperwind. A'moora facilitates the spiritual instruction and ritual duties conducted under the temple's roof.",al={"is amoora a temple priestess","sisterhood of elune amoora"}},{q="Who is Sathrah, and why does A'moora speak of her?",a="Lady Sathrah is a great spider once beloved of Elune, who dwells along Teldrassil's northern borders near Wellspring Lake. She has descended into madness, so A'moora asks adventurers to end her suffering and offer her spinnerets to Elune so she may be reborn at peace.",al={"sathrah sacrifice","who is sathrah"}},{q="Does A'moora belong to the Alliance?",a="Yes. As a night elf priestess stationed within the capital city of Darnassus, she is fully aligned with the Alliance and will not offer assistance or quests to members of the Horde.",al={"is amoora alliance","can horde talk to amoora"}}},ang={["race:NightElf"]="For night elves, Priestess A'moora represents the timeless traditions of Elune worship, anchoring the young boughs of Teldrassil to the ancient spiritual heritage of their people.",["class:Priest"]="Priests walking the halls of the Temple of the Moon can see in A'moora an example of dedicated devotion, bridging the gap between temple ritual and the natural world outside the city gates.",["faction:Alliance"]="Priestess A'moora assists Alliance travelers exploring the holy heart of Darnassus, introducing them to the Sisterhood of Elune's sacred customs."},kw={"a'moora","darnassus","elune","priestess","sathrah","tears of the moon","teldrassil","temple of the moon"},rel={"subzone:temple-of-the-moon","quest:2518","quest:2519","quest:2520","zone:darnassus","subzone:oracle-glade","quest:940","topic:night-elf"},src={"Priestess A'moora"}}
E["npc:priestess-alathea"] = {t="npc",n="Priestess Alathea",z="darnassus",s="Priestess Alathea is a night elf priest trainer residing within the tranquil halls of the Temple of the Moon in Darnassus. Devoted to the Moon Goddess, she guides novitiates in the sacred arts and racial blessings bestowed by Elune. Her teachings help night elf practitioners attune their minds to defensive prayers and celestial magic.",h="Priestess Alathea is a night elf priest trainer residing within the tranquil halls of the Temple of the Moon...",sec={{t="Devotion in the Temple of the Moon",b="Standing within the soaring silver heights of Darnassus's grandest sanctuary, Priestess Alathea serves the Sisterhood of Elune as an instructor and spiritual guide. As night elf initiates progress beyond the quiet boughs of Shadowglen, they are directed to the Temple of the Moon to deepen their covenant with the Goddess. Alathea stands among the priestesses ready to impart sacred knowledge to those who dedicate their lives to healing, warding, and divine light.",sp=0},{t="Blessings of the White Lady",b="Unlike priests of the Holy Light who draw strength strictly from human and dwarven traditions, kaldorei priests draw directly upon the grace of Elune. Alathea plays a key role in testing and granting blessings tailored to night elves, such as Stars of Elune and Elune's Grace. Through her guidance, acolytes learn how to weave starlight into shields of swiftness and defensive power to survive the growing perils facing Kalimdor.",sp=0}},faq={{q="Who is Priestess Alathea?",a="Priestess Alathea is a kaldorei priest trainer stationed inside the Temple of the Moon in Darnassus, responsible for training budding priests and guiding night elf acolytes through their sacred trials.",al={"who is alathea","alathea darnassus","alathea priest trainer"}},{q="What abilities does she teach?",a="She offers standard priest spell training as well as specific trials for night elf racials, including Starshards and Elune's Grace, which channel the direct power and protection of the Moon Goddess.",al={"alathea abilities","alathea spells","priest spells darnassus"}},{q="Where can I find Priestess Alathea?",a="She resides on the ground floor of the Temple of the Moon in the southern reaches of Darnassus, surrounded by the sanctuary's luminous waters and fellow priestesses.",al={"where is alathea","alathea location"}},{q="Why do night elf priests visit her specifically?",a="As kaldorei priests advance in their training, novice instructors across Teldrassil send them to Alathea to undertake spiritual rites—such as Stars of Elune and Elune's Grace—marking their transition into mature servants of the goddess.",al={"priest quests alathea","stars of elune quest"}},{q="Does she train races other than night elves?",a="Yes. While human and dwarven priests belong to the Church of the Holy Light, any Alliance priest visiting Darnassus can learn general spells from her, though she only administers kaldorei-specific racial trials to night elves.",al={"can humans train with alathea","alathea dwarf priest"}},{q="How does her faith differ from human and dwarven priests?",a="While the priests of Stormwind and Ironforge invoke the ambient and philosophical Holy Light, Alathea and her sisters revere Elune as a living deity, wielding starlight and moonlit wards alongside curative magic.",al={"elune vs holy light","night elf priest lore"}}},ang={["class:Priest"]="Priestess Alathea is a vital contact for Alliance priests visiting Darnassus, offering rank advancements and guiding kaldorei acolytes to their unique celestial powers.",["race:NightElf"]="As a priestess in the heart of Darnassus, Alathea represents the living spiritual traditions of the Sisterhood of Elune that have protected the kaldorei for millennia.",["faction:Alliance"]="Alathea opens the Temple of the Moon's teachings to all traveling members of the Alliance who study the clerical arts."},kw={"alathea","darnassus","elune","elune's grace","priest trainer","priestess alathea","stars of elune","temple of the moon"},rel={"subzone:temple-of-the-moon","quest:2519","quest:5627","quest:5672","topic:elune","zone:darnassus","topic:night-elf","quest:940"},src={"Priestess Alathea"}}
E["npc:renzik-the-shiv"] = {t="npc",n="Renzik \"The Shiv\"",z="darnassus",s="Renzik \"The Shiv\" is a goblin operative and the trusted second-in-command of SI:7, stationed inside their headquarters in Stormwind City's Old Town. Despite his rough origins as an enforcer in Undermine, he serves Spymaster Mathias Shaw faithfully, directing new rogue recruits and handling covert operations where typical Alliance agents cannot tread.",h="Renzik \"The Shiv\" is a goblin operative and the trusted second-in-command of SI:7, stationed inside their...",sec={{t="From Undermine Enforcer to Alliance Spy",b="Born in the subterranean goblin metropolis of Undermine beneath Kezan, Renzik grew up on ruthless streets after his parents were murdered. Relying on an improvised shiv and sharp instincts, he eventually rose to become the chief enforcer for Trade Prince Mozzy Gloxscorn of the Krackslagger Cartel. Known as Mozzy's \"Bloody Fist,\" Renzik broke heads and settled cartel scores, yet he grew disillusioned with the cruelty of cartel rule. A fateful clash in Undermine with Stormwind spymaster Mathias Shaw revealed another way forward. Shaw offered him an escape and an invite to Stormwind, which Renzik eventually accepted.",sp=0},{t="Right Hand of Mathias Shaw",b="Now based inside the secretive SI:7 fortress in Old Town, Renzik serves as Mathias Shaw's second-in-command. Because most intelligence agents are humans, dwarves, or gnomes who immediately stand out in Kalimdor, Renzik's goblin heritage makes him an indispensable asset for infiltrating Orgrimmar and other Horde-held territories. Rogue mentors across the Alliance—from the Hidden Circle in Ironforge to shadow operatives in Darnassus—send their most promising agents to Renzik. Rather than sending them straight to slaughter, Renzik forwards them to field instructors like Lucius in Redridge to hone their survival craft.",sp=0}},faq={{q="Why is a goblin working for Stormwind's SI:7?",a="Renzik grew disgusted by the cutthroat greed of the Undermine cartels after a run-in with Spymaster Mathias Shaw. Shaw offered him a coin and an open door in Stormwind. Renzik values the genuine respect and steady pay he earns among SI:7, taking pride in being respected rather than merely feared.",al={"why is renzik alliance","goblin in stormwind","why is there a goblin in si7"}},{q="Why is he called 'The Shiv'?",a="He earned the title during his rough youth in Undermine, both for carrying an improvised blade for protection and for his natural ability to improvise lethal solutions out of tight spots.",al={"why the shiv","renzik nickname","renzik the shiv meaning"}},{q="What does Renzik do for player rogues?",a="When Alliance rogues prove their competence, their trainers send them to Renzik in Stormwind. He acts as their intake handler for SI:7, dispatching recruits to specialized trainers like Lucius in the Redridge Mountains to ensure they have the fieldcraft to stay alive.",al={"renzik rogue quest","what does renzik give","talk to renzik the shiv"}},{q="Where does Renzik usually operate?",a="He is stationed inside the SI:7 headquarters in Old Town, Stormwind City. In the broader scope of intelligence work, his goblin identity allows him to blend in and run espionage operations in places standard Alliance agents cannot go, such as Orgrimmar.",al={"renzik location","where to find renzik","where is renzik"}},{q="What was his past in Kezan?",a="Before coming to Stormwind, Renzik was the right hand and head enforcer of Trade Prince Mozzy Gloxscorn in the Krackslagger Cartel. He was known across Undermine for brutal efficiency, though he secretly harbored sympathy for the city's street orphans.",al={"renzik backstory","renzik undermind","renzik krackslagger"}},{q="Does Renzik maintain ties outside Stormwind?",a="Yes. Within the Alliance intelligence network, he coordinates with rogue contacts including the dwarven Hidden Circle in Ironforge and night elf operatives based in Darnassus, integrating shadow networks across both continents.",al={"renzik network","renzik connections","renzik allies"}}},ang={["class:Rogue"]="For an Alliance rogue, Renzik is your bridge from street-level knifework into the high-stakes intelligence network of SI:7, weeding out the reckless before sending you to Lucius in Redridge.",["faction:Alliance"]="Though a goblin, Renzik is one of Stormwind's most capable intelligence officers, managing operations in hostile territories where human spies would be caught on sight.",["race:Human"]="Standing beside Spymaster Shaw in Old Town, Renzik is a rare goblin fixture in the kingdom's military elite, proving that loyalty and competence outweigh race in the shadow wars."},kw={"goblin","lucius","mathias shaw","old town","renzik","rogue","si:7","stormwind","the shiv","undermine"},rel={"npc:mathias-shaw","quest:2300","quest:2260","subzone:old-town","zone:stormwind","npc:lucius","topic:goblin","topic:alliance"},src={"Renzik \"The Shiv\""}}
E["npc:sister-aquinne"] = {t="npc",n="Sister Aquinne",z="darnassus",s="Sister Aquinne is an acolyte of Elune residing within the serene Temple Gardens of Darnassus. Hailing from the village of Dolanaar, she is studying under the Priesthood of Elune at the Temple of the Moon.",h="Sister Aquinne is an acolyte of Elune residing within the serene Temple Gardens of Darnassus.",sec={{t="Acolyte in Darnassus",b="Sister Aquinne moved from her home village of Dolanaar to the night elf capital to dedicate herself to the Priesthood of Elune. Stationed in the tranquil Temple Gardens beneath the shadow of the Temple of the Moon, she continues her studies under the guidance of the High Priestess and elder sisters. Her dedication brings great pride to the friends and folk she left behind in Dolanaar, who occasionally send tokens and practical gifts to remind the young novice of home while she pursues her sacred calling.",sp=0}},faq={{q="Where can Sister Aquinne be found?",a="Sister Aquinne stands in the Temple Gardens of Darnassus, situated just outside the magnificent Temple of the Moon.",al={"aquinne location","where is sister aquinne","sister aquinne coords"}},{q="What is Sister Aquinne's background?",a="She grew up in the nearby woodland settlement of Dolanaar alongside childhood friends like Astaia. She left her quiet rural life to travel to the capital and train as a priestess of Elune.",al={"aquinne lore","who is sister aquinne","aquinne backstory"}},{q="Why do people in Dolanaar send her gifts?",a="Her old friends in Dolanaar are proud of her acceptance into the Temple of the Moon. They occasionally entrust travelers with gifts, such as recipe books and keepsakes, to ensure she feels supported during her rigorous studies.",al={"dolanaar to aquinne","reminders of home quest","aquinne cookbook"}},{q="What is her connection to Astaia?",a="Astaia is Aquinne's childhood friend from Dolanaar. The two shared many memories growing up together, including boat trips where Aquinne once misplaced a treasured moon pendant.",al={"astaia and aquinne","sister aquinne friend"}}},ang={["class:Priest"]="Fellow servants of the Light and Elune can appreciate Aquinne's devotion as she undertakes the foundational training required of all acolytes serving the Temple of the Moon.",["race:NightElf"]="For night elf adventurers journeying from the boughs of Dolanaar into Darnassus, Sister Aquinne serves as a familiar link between small village life and the grandeur of the temple priesthood."},kw={"aquinne","astaia","darnassus","dolanaar","sister aquinne","temple gardens","temple of the moon"},rel={"subzone:temple-gardens","subzone:temple-of-the-moon","zone:darnassus","subzone:dolanaar","quest:2519","topic:night-elf","quest:940"},src={"Sister Aquinne"}}
E["npc:syurna"] = {t="npc",n="Syurna",z="darnassus",s="Syurna is a night elf rogue trainer found nestled among the foliage of the Cenarion Enclave in Darnassus. She mentors aspiring scouts, spies, and covert operatives of the Kaldorei, guiding newly trained rogues on missions that test their stealth and cunning.",h="Syurna is a night elf rogue trainer found nestled among the foliage of the Cenarion Enclave in Darnassus.",sec={{t="A Scout Among the Grove",b="While Darnassus celebrates the overt martial might of the Sentinels and the spiritual wisdom of the Sisterhood of Elune, the Kaldorei have always relied on shadows and stealth. Located in the Cenarion Enclave, Syurna acts as a trainer and mentor for those who walk an unseen path. She instructs rogues in the fine arts of evasion, lockpicking, and lethal strikes, ensuring that Darnassus possesses sharp eyes and silent blades to defend Teldrassil.",sp=0},{t="Tests of Cunning",b="Syurna does not merely offer theoretical advice from the safety of the enclave; she tests the readiness of young operatives. Through tasks such as directing promising initiates into deeper fieldwork, she tests whether an operative has the instincts necessary to survive outside the boughs of the World Tree and serve the Alliance in perilous frontier lands.",sp=0}},faq={{q="Who is Syurna?",a="Syurna is a night elf rogue trainer stationed within the Cenarion Enclave in Darnassus. She offers combat training, abilities, and guidance to rogue adventurers serving the Alliance.",al={"syurna darnassus","who is syurna","night elf rogue trainer"}},{q="Where exactly can I find Syurna in Darnassus?",a="She is located in the Cenarion Enclave on the western side of Darnassus, positioned among the trees and pavilions alongside other shadow-inclined mentors.",al={"where is syurna","syurna location","darnassus rogue trainer location"}},{q="Why is a rogue trainer in the Cenarion Enclave?",a="Though the Cenarion Enclave is primarily associated with druidism and nature, night elf scouts and covert pathfinders often train quietly along its wooded edges, removed from the public pageantry of the Temple of Elune or the Warrior's Terrace.",al={"why is rogue trainer in enclave","cenarion enclave rogue"}},{q="What quests does Syurna offer?",a="Syurna is involved in early rogue progression, directing novice operatives who have proven themselves in Shadowglen to hone their talents in the wider world, including through quests like Destiny Calls.",al={"syurna quests","destiny calls quest"}}},ang={["class:Rogue"]="For night elf rogues, Syurna is one of your principal instructors in Darnassus, teaching you core techniques of stealth, poison, and martial precision as you grow in experience.",["race:NightElf"]="Syurna embodies the quiet, predatory tradition of Kaldorei scouts who protect their woodland sanctuaries from the shadows rather than open battle."},kw={"cenarion enclave","darnassus","destiny calls","kaldorei","rogue trainer","syurna","teldrassil"},rel={"zone:darnassus","subzone:cenarion-enclave","topic:night-elf","quest:2242","quest:940"},src={"Syurna"}}
E["quest:1038"] = {t="quest",n="Velinde's Effects",z="darnassus",s="Velinde's Effects is an Alliance investigation in Darnassus uncovering the fate of Sentinel Velinde Starsong. Directed by Thyn'tel Bladeweaver, adventurers retrieve Velinde's personal journal from a chest in the Sentinels' quarters to learn why the revered priestess vanished.",h="Velinde's Effects is an Alliance investigation in Darnassus uncovering the fate of Sentinel Velinde Starsong.",sec={{t="A Trusted Sentinel",b="Priestess Velinde Starsong earned immense trust among the night elves through her long, devoted service. When she quietly disappeared from her duties, the Sentinels assumed she departed for personal reasons and anticipated her return. Only when outsiders uncover clues linked to the Tome of Mel'Thandris does Sentinel leadership permit an inquiry into her private possessions.",sp=0},{t="The Chest in the Bunkhouse",b="Stationed on the Warrior's Terrace of Darnassus, Thyn'tel Bladeweaver provides the key to Velinde's locked trunk stored inside the Sentinels' bunkhouse in the Tradesmen's Terrace. Within the chest lies Velinde's personal journal, detailing her assignments and inner thoughts. Rather than reassuring the Sentinels, the journal hints at dire, secretive affairs that prompted her solitary journey away from Teldrassil.",sp=1}},faq={{q="Who is Velinde Starsong?",a="Velinde Starsong is an esteemed night elf priestess and Sentinel commander. She commanded deep respect among her peers for her dedicated service before abruptly vanishing on an unexplained mission.",al={"velinde starsong lore","who is velinde","velinde backstory"}},{q="Where is Velinde's chest located?",a="The chest is kept in the Sentinels' bunkhouse on the upper floor of a building in Darnassus's Tradesmen's Terrace, accessible by crossing the elevated bridge from the neighboring mail armor shop.",al={"velinde chest location","where is velindes effects","sentinel bunkhouse darnassus"}},{q="Why didn't the Sentinels search for her earlier?",a="Because of Velinde's pristine reputation, her commanders believed she had legitimate, private reasons for departing and assumed she would return whenever her business concluded.",al={"why did sentinels ignore velinde","why wasn't velinde reported missing"}},{q="What is discovered inside the journal?",a="Her journal reveals that her absence was far more troubling than a routine leave of absence, prompting Thyn'tel Bladeweaver to immediately seek outside help to trace her travel route.",al={"velindes journal contents","what did velinde write"}},{q="How was Velinde connected to the Tome of Mel'Thandris?",a="The ancient elven text contained references to her past inquiries and activities, serving as the initial catalyst that drew researchers and adventurers to investigate her whereabouts.",al={"tome of melthandris velinde","why the tome of mel'thandris"}},{q="Where does the investigation lead after finding her effects?",a="The journal's clues direct investigators toward the Barrens, tracing Velinde's footsteps south toward Kalimdor's transit hubs and ports.",al={"where to go after velindes effects","velindes effects next quest"},sp=1}},ang={["race:NightElf"]="Velinde Starsong represents the quiet sacrifices made by the Sisterhood of Elune and the Sentinels, making her sudden disappearance deeply unsettling to her kin in Darnassus.",["faction:Alliance"]="Investigating high-ranking night elf officers highlights the lingering threats across Kalimdor that the fledgling Alliance leadership in Darnassus struggles to contain.",["class:Priest"]="Velinde was a revered priestess whose reliance on sacred duties gives fellow devotees of Elune an urgent reason to trace what led her astray."},kw={"bladeweaver","bunkhouse","darnassus","journal","mel'thandris","sentinels","starsong","thyn'tel","tradesmen's terrace","velinde"},rel={"zone:darnassus","npc:thyn-tel-bladeweaver","quest:1039","topic:sentinels"},m={start="Thyn'tel Bladeweaver",level="30",faction="Alliance",id=1038},src={"Velinde's Effects"}}
E["quest:1039"] = {t="quest",n="The Barrens Port",z="darnassus",s="The Barrens Port is an Alliance quest given by Thyn'tel Bladeweaver in Darnassus as part of the investigation into the disappearance of Velinde Starsong. Believing Velinde took a ship across the Great Sea to the Eastern Kingdoms, the Sentinels direct you across dangerous Horde territory to the goblin-run harbor of Ratchet to consult Wharfmaster Dizzywig's ledgers.",h="The Barrens Port is an Alliance quest given by Thyn'tel Bladeweaver in Darnassus as part of the investigation...",sec={{t="Tracking the Priestess",b="Following the inspection of Velinde Starsong's personal effects, the Sentinels discovered clues suggesting she sought passage across the sea toward the Eastern Kingdoms. Ratchet serves as the only operational maritime harbor in the Barrens, making it the solitary conduit through which a traveler from northern Kalimdor could arrange transport south or east without sailing directly out of night elf territory. Thyn'tel Bladeweaver sends you southward to search the harbor master's shipping ledgers for any sign of Velinde's name.",sp=0},{t="A Dangerous Crossing",b="Traveling to Ratchet requires an Alliance operative to brave the heart of Horde-controlled lands. South of Ashenvale, the Mor'shan Rampart and the arid savannas of the Barrens crawl with orcish outriders and Tauren patrols. The town of Ratchet itself, governed by the neutral Steamwheedle Cartel, provides safe harbor under goblin law, where trade supersedes faction rivalries and Wharfmaster Dizzywig keeps careful track of every passenger and cargo crate crossing the docks.",sp=0}},faq={{q="Why do the Sentinels send me into the Barrens?",a="Ratchet is the primary neutral trading port in central Kalimdor. Since Velinde Starsong vanished and sought passage toward the Eastern Kingdoms, the night elves deduce that she likely booked safe travel abroad aboard a goblin trading vessel rather than navigating official military channels.",al={"why go to ratchet","why the barrens port"}},{q="Who is Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig is the goblin official overseeing maritime departures and cargo registries at the docks in Ratchet. Working on behalf of the Steamwheedle Cartel, he keeps exhaustive ledgers detailing every vessel, passenger, and shipment that sails in and out of the harbor.",al={"who is dizzywig","ratchet wharfmaster"}},{q="Why would an Alliance member be safe in Ratchet?",a="Ratchet is operated by the neutral Steamwheedle Cartel rather than the Horde. The goblins prioritize commerce and profit above faction disputes, meaning their bruisers enforce peace and allow Alliance travelers to conduct business unmolested so long as they avoid drawing weapons inside the settlement.",al={"is ratchet safe for alliance","will guards attack me in ratchet"}},{q="What happens after finding Wharfmaster Dizzywig?",a="Once Dizzywig checks his manifests, he confirms Velinde's departure aboard a vessel Bound for the Eastern Kingdoms, directing you onward toward Booty Bay in Stranglethorn Vale to pick up her trail on the other side of the Great Sea.",al={"what next after barrens port","velinde quest continuation"},sp=1},{q="How does an Alliance traveler reach Ratchet safely?",a="Alliance travelers typically journey south from Ashenvale past Silverwing Grove, skirting the heavily guarded Mor'shan Rampart by cutting through the hills just east of the main road. Once in the Barrens, sticking to the paths toward the eastern coast leads directly to the docks of Ratchet.",al={"safest way to ratchet alliance","how to get to ratchet alliance"}},{q="Who is Velinde Starsong?",a="Velinde Starsong was a night elf priestess and Sentinel Melyria Frostshadow's predecessor in Ashenvale, charged with holding back the demonic presence in Felwood. Her efforts slowly faltered until she simply disappeared, and her trail now seems to lead across the sea.",al={"who is velinde","velinde starsong lore"}}},ang={["race:NightElf"]="Velinde Starsong is an esteemed Sentinel whose loss weighs heavily on the leadership in Darnassus; retracing her desperate journey reflects the grave consequences of her experiments with the Scythe of Elune.",["faction:Alliance"]="Navigating the heart of Kalimdor exposes Alliance scouts to heavy Horde patrols in the Barrens, requiring caution before reaching the neutral sanctuary of the goblin docks."},kw={"ashenvale","ratchet","scythe of elune","steamwheedle cartel","the barrens","thyn'tel bladeweaver","velinde starsong","wharfmaster dizzywig"},rel={"quest:1038","quest:1040","subzone:ratchet","npc:thyn-tel-bladeweaver","zone:barrens","zone:ashenvale","subzone:mor-shan-rampart","topic:goblin"},m={start="Thyn'tel Bladeweaver",["end"]="Wharfmaster Dizzywig",level="30",faction="Alliance",id=1039},src={"The Barrens Port"}}
E["quest:1582"] = {t="quest",n="Moonglow Vest",z="darnassus",s="Moonglow Vest is a trade training task offered by the night elf leatherworker Lotherias in Darnassus. Overwhelmed by the constant needs of young adventurers heading into the wilds of Kalimdor, he trades the knowledge of a specialized night elven tunic pattern in exchange for bulk shipments of embossed leather gear.",h="Moonglow Vest is a trade training task offered by the night elf leatherworker Lotherias in Darnassus.",sec={{t="Equipping the Kaldorei",b="In the sheltered boughs of Darnassus, tradesmen work tirelessly to outfit the swelling ranks of sentinels and aspiring wilderness scouts. As young night elves and allied wanderers venture forth beyond Teldrassil into a volatile Kalimdor, reliable armor is in fierce demand. Master leatherworkers like Lotherias bear the burden of keeping these frontiers supplied with sturdy hides.",sp=0},{t="Mastering the Craft",b="To ensure his apprentices possess both endurance and technical precision, Lotherias requires proof of their handiwork through multiple matched garments: embossed gloves, boots, and cloaks. Meeting this quota earns his trust, prompting him to impart the distinct night elven pattern for the Moonglow Vest—a garment favored for balancing supple protection with agile mobility.",sp=0}},faq={{q="Who is Lotherias?",a="Lotherias is a skilled night elf leatherworking trainer stationed in Darnassus. He oversees craft instruction for Alliance artisans and provides advanced designs to leatherworkers who prove their dedication.",al={"lotherias darnassus","who gives moonglow vest"}},{q="Why does Lotherias need so many leather items?",a="Darnassus is bustling with newly trained adventurers preparing to journey out into the world. Craftsmen are struggling to keep up with the continuous demand for field gear, prompting Lotherias to outsource standard embossed garments to capable apprentices.",al={"why need so many boots","why craft embossed leather"}},{q="What is the Moonglow Vest?",a="The Moonglow Vest is an advanced piece of crafted leather armor. Its pattern is taught as a reward by Lotherias once you demonstrate your ability to manufacture high-quality embossed goods in volume.",al={"moonglow vest recipe","what do i get"}},{q="What materials are required to complete this task?",a="You must provide one pair of Embossed Leather Gloves, five pairs of Embossed Leather Boots, and five Embossed Leather Cloaks. All pieces must be crafted and delivered directly to Lotherias.",al={"what do i need","moonglow vest items"}},{q="Can Horde leatherworkers learn this pattern here?",a="No. Lotherias resides within Darnassus and strictly trains Alliance craftspeople. Horde artisans must seek out their own respective trainers across Kalimdor and the Eastern Kingdoms to expand their trade.",al={"can horde do this","is moonglow vest alliance only"}},{q="Does this quest require a specific trade skill level?",a="Yes, an artisan must achieve a leatherworking proficiency of at least 70 before Lotherias considers them skilled enough to take on the order and learn the vest pattern.",al={"leatherworking level needed","when can i get moonglow vest"}}},ang={["race:NightElf"]="The Moonglow Vest represents the elegant craftsmanship typical of Teldrassil's artisans, providing scouts and sentinels with agile protection under the forest canopy.",["faction:Alliance"]="Outfitting fresh recruits in Darnassus helps maintain the Alliance's fragile hold across northern Kalimdor amidst growing wild and hostile threats."},kw={"crafting","darnassus","embossed leather","kaldorei","leatherworking","lotherias","moonglow vest","teldrassil"},rel={"zone:darnassus"},m={start="Lotherias",faction="Alliance",id=1582},src={"Moonglow Vest (quest)"}}
E["quest:1683"] = {t="quest",n="Vorlus Vilehoof",z="darnassus",s="Vorlus Vilehoof is a rite of passage for young night elf warriors training in Darnassus. Under instruction from the warrior trainer Elanaria, candidates must hunt down a vile satyr who has defiled a hidden moonwell near the Ban'ethil Barrow Den.",h="Vorlus Vilehoof is a rite of passage for young night elf warriors training in Darnassus.",sec={{t="A Test of Resolve",b="Before Elanaria will impart advanced martial techniques to young night elf warriors, she demands proof of their dedication and discipline. Words alone mean nothing in the defense of Kalimdor; a true guardian must be willing to confront corruption face-to-face and cleanse the sacred boughs of Teldrassil from taint.",sp=0},{t="Defiling the Sacred Waters",b="The target of this trial is Vorlus Vilehoof, a satyr who has infiltrated a secluded moonwell nestled in the mountains southeast of Ban'ethil Barrow Den. The satyrs, ancient betrayers twisted by demonic influence, harbor an enduring hatred for sacred Kaldorei relics. Vorlus has taken to bathing in the moonwell, fouling its blessed waters with his presence and mocking the grace of Elune.",sp=0},{t="Claiming the Horn",b="Finding Vorlus requires tracking a concealed mountain trail guarded by hostile Gnarlpine furbolgs. Once cornered at the tainted spring, the satyr must be slain in martial combat. Taking Vorlus's horn back to the Warrior's Terrace in Darnassus proves the beast's demise, restoring sanctity to the secluded glade and opening the path to specialized martial weapons.",sp=1}},faq={{q="Who is Vorlus Vilehoof?",a="Vorlus Vilehoof is a corrupted satyr dwelling on Teldrassil. He discovered a secluded moonwell southeast of the Ban'ethil Barrow Den and began bathing in it, actively defiling its consecrated waters.",al={"vorlus vilehoof lore","who is vorlus","vorlus the satyr"}},{q="Why does Elanaria send warriors after Vorlus?",a="Elanaria uses the hunt as a proving trial for promising warriors. Defeating a dangerous, corrupt fiend like Vorlus demonstrates the focus, courage, and resolve required before she will teach advanced martial skills or guide them in forging specialized weaponry.",al={"why kill vorlus","elanaria quest reason","purpose of vorlus vilehoof quest"}},{q="Where is the hidden moonwell located?",a="The moonwell sits hidden in the ridges southeast of Ban'ethil Barrow Den. Reaching it requires finding a subtle mountain path lined with torches, located just behind an encampment of Gnarlpine furbolgs east of the barrows.",al={"vorlus location","how to find vorlus","hidden moonwell path"}},{q="What is a moonwell, and why does his presence matter?",a="Moonwells are sacred basins filled with blessed waters that channel the light of Elune and sustain nature's vitality. For a demonic satyr like Vorlus to wallow in one is considered a direct desecration of Kaldorei faith and a dangerous vector of corruption on Teldrassil.",al={"why are moonwells important","moonwell desecration","night elf moonwells"}},{q="What comes after defeating Vorlus Vilehoof?",a="Returning Vorlus's severed horn satisfies Elanaria, confirming the warrior's readiness. She will then direct the warrior onward to pursue the legendary Weapons of Elunite, beginning with uncovering the Shade of Elura.",al={"next quest after vorlus","what happens next","shade of elura quest"},sp=1},{q="Are there other satyrs on Teldrassil?",a="Yes. Despite Teldrassil being relatively young, satyrs lurk in places like Shadowthread Keep and scattered corrupt hollows, constantly seeking to infect the World Tree with demonic taint.",al={"satyrs on teldrassil","teldrassil satyr threat"}}},ang={["class:Warrior"]="Hunting Vorlus Vilehoof serves as your initiation into advanced martial training, demonstrating that your blade serves the protection of Kaldorei lands and the sanctity of the goddess.",["race:NightElf"]="Moonwells represent the purity of Elune and the lifeblood of Kaldorei spirituality; tolerating a satyr bathing in their waters is an intolerable insult to all night elves.",["faction:Alliance"]="Securing Teldrassil's interior from lurking demonic remnants ensures that Darnassus remains a steadfast redoubt for the Alliance in Northern Kalimdor."},kw={"ban'ethil","darnassus","elanaria","horn of vorlus","moonwell","satyr","teldrassil","vorlus vilehoof","warrior quest"},rel={"npc:elanaria","quest:1686","quest:1693","topic:satyr","subzone:ban-ethil-barrow-den","zone:darnassus","quest:940"},m={start="Elanaria",level="10",faction="Alliance",id=1683},src={"Vorlus Vilehoof (quest)"}}
E["quest:1686"] = {t="quest",n="The Shade of Elura",z="darnassus",s="\"The Shade of Elura\" is an early rite of passage for young night elf warriors, directed by the warrior trainer Elanaria in Darnassus. It tasks the warrior with diving into the waters off Auberdine to lay a tormented sea captain's ghost to rest and salvage crates of rare Elunite ore. Securing these materials provides the foundation for crafting a custom martial weapon.",h="\"The Shade of Elura\" is an early rite of passage for young night elf warriors, directed by the warrior...",sec={{t="A Captain's Eternal Guard",b="Long ago, a vessel bearing a shipment of rare Elunite ore foundered upon the jagged coastal rocks near the Auberdine lighthouse. In despair and unyielding loyalty to her duty, the ship's captain, Elura, laid a curse upon her own soul. Bound to the wreckage beneath the waves, her shade lingers on the seabed to defend her lost cargo from any who dare disturb it.",sp=0},{t="Weapons of Elunite",b="For night elf warriors coming into their own, claiming their first true crafted weapon requires both martial skill and respect for fallen kin. Trainer Elanaria sends aspiring fighters into the cold surf of Darkshore not merely to salvage metal, but to defeat the Shade of Elura and recover her medallion. Putting Elura to rest frees the cursed captain from her vigil and yields the raw ore needed for Smith Mathiel's forge.",sp=0}},faq={{q="Who is the Shade of Elura?",a="Elura was the captain of an elven ship that wrecked on the treacherous shallows near the Auberdine lighthouse. Rather than abandoning her duty, she cursed herself in life or death to vigilantly guard her vessel's sunken cargo of Elunite ore for all time.",al={"shade of elura lore","who is elura","captain elura"}},{q="Why does Elanaria send warriors after Elura?",a="Elanaria seeks to both put Elura's tormented spirit to peace and recover the sunken Elunite ore. Defeating the captain and claiming her medallion proves a young warrior's prowess while securing the raw materials required to forge a superior weapon.",al={"why do we kill elura","elanaria quest purpose"}},{q="Where did the wreck happen?",a="The wreck lies submerged off the coast of Auberdine in Darkshore, near the lighthouse and just south of the main harbor docks, scattered along the ocean bed.",al={"where is the shipwreck","elura ship location"}},{q="What is Elunite ore used for?",a="Elunite is a rare ore valued by night elven smiths. In this trial, the salvaged crates are brought to the blacksmith Smith Mathiel in Darnassus to forge a personalized martial weapon for promising warriors.",al={"what is elunite","elunite ore purpose"}},{q="Does defeating the shade harm Elura permanently?",a="Defeating her shade breaks the self-inflicted curse binding her spirit to the sea floor. As Elanaria notes, besting her in combat brings the captain much-deserved peace after centuries of cold, spectral vigil.",al={"did elura die","is elura saved"}},{q="Who crafts the weapon once the ore is collected?",a="Once Elanaria receives the ore and medallion, she directs the warrior to Smith Mathiel in the Warrior's Terrace of Darnassus, who works the metal into an exceptional weapon.",al={"who makes the elunite weapon","next quest after elura"}}},ang={["class:Warrior"]="This quest represents a defining step in a night elf warrior's career, testing aquatic grit and martial discipline to earn a forged weapon of Elunite.",["race:NightElf"]="Putting Elura's shade to rest honors a fellow kaldorei whose boundless sense of duty trapped her beneath the waves for generations.",["profession:Blacksmithing"]="The salvage of sunken Elunite highlights the unique metallurgical traditions of the night elves, who craft potent armaments from blessed materials."},kw={"auberdine","darkshore","darnassus","elanaria","elunite ore","elura","shade of elura","smith mathiel","weapons of elunite"},rel={"quest:1692","quest:1693","npc:elanaria","subzone:auberdine","zone:darkshore","zone:darnassus"},m={start="Elanaria",level="10",faction="Alliance",id=1686},src={"The Shade of Elura"}}
E["quest:1692"] = {t="quest",n="Smith Mathiel",z="darnassus",s="Smith Mathiel is a pivotal warrior quest in Darnassus marking the transition from raw materials to forged arms. Having secured sacred elunite ore from a shipwreck off Auberdine, an aspiring warrior delivers the ore to the master blacksmith Mathiel. He agrees to work the blessed metal into a weapon fit for defending the Kaldorei.",h="Smith Mathiel is a pivotal warrior quest in Darnassus marking the transition from raw materials to forged...",sec={{t="A Sacred Delivery",b="After recovering elunite ore from the haunted shipwreck off Auberdine and securing it with the aid of the warrior trainer Elanaria, young night elf warriors are sent across the Warrior's Terrace of Darnassus. Elanaria carefully packs the ore into a sturdy case, instructing the novice to seek out Mathiel, one of the premier smiths in the capital, to fashion a weapon worthy of their martial calling.",sp=0},{t="The Blessing of Elunite",b="Mathiel views his forge work not merely as manual labor, but as a devotional craft. Elunite is no ordinary ore—it carries the sacred blessing of the Moon Goddess, Elune. When presented with the case, Mathiel readily takes on the task, considering it a profound honor to shape such holy metal into arms meant to defend the young boughs of Teldrassil.",sp=0}},faq={{q="Who is Smith Mathiel?",a="Mathiel is a skilled night elf blacksmith stationed in the Warrior's Terrace of Darnassus. He crafts specialty armaments and takes on custom forging for the defenders of Darnassus.",al={"who is mathiel","blacksmith mathiel","where is mathiel"}},{q="What is special about elunite ore?",a="Elunite is a rare metal revered by the night elves because it is blessed by Elune herself. Smiths like Mathiel treat crafting with it as a high honor, utilizing its sacred properties to fashion potent weapons.",al={"what is elunite","is elunite magical","elunite lore"}},{q="Who sends you to Mathiel?",a="Elanaria, a prominent warrior trainer residing in the Warrior's Terrace of Darnassus, packs your recovered ore and directs you to seek Mathiel just across the terrace.",al={"who gives smith mathiel quest","quest giver smith mathiel"}},{q="Is this quest only available to warriors?",a="Yes. This quest is part of the level 10 warrior class questline designed to equip young warriors with their first specialized martial weaponry.",al={"warrior only","can other classes do smith mathiel"}},{q="Where in Darnassus can Mathiel be found?",a="Mathiel works in the Warrior's Terrace in Darnassus, located just south across the structure from Elanaria.",al={"mathiel location","find mathiel"}},{q="What happens after you deliver the ore to Mathiel?",a="Mathiel begins hammering the elunite ore into shape, immediately offering the follow-up quest where you choose which elunite-forged weapon best suits your fighting style.",al={"what comes after smith mathiel","next quest after smith mathiel"}}},ang={["class:Warrior"]="For young Kaldorei warriors, bringing elunite to Mathiel is a rite of passage, exchanging simple training blades for custom weapons blessed by the Moon Goddess.",["race:NightElf"]="Working elunite ore bridges night elf craftsmanship with holy devotion to Elune, demonstrating that martial strength and divine faith go hand in hand.",["profession:Blacksmithing"]="Mathiel's reverence for elunite highlights how Kaldorei smiths integrate sacred blessings into their forgecraft rather than relying solely on brute heat and hammer."},kw={"craftsmen's terrace","darnassus","elanaria","elunite","mathiel","smith","warrior"},rel={"quest:1693","quest:1686","npc:elanaria","topic:elune","quest:1703"},m={start="Elanaria",["end"]="Mathiel",level="10",faction="Alliance",id=1692},src={"Smith Mathiel"}}
E["quest:1693"] = {t="quest",n="Weapons of Elunite",z="darnassus",s="Weapons of Elunite is the culmination of an early rite of passage for night elf warriors in Darnassus. After recovering raw ore blessed by Elune, the warrior brings the material to the skilled smith Mathiel to be forged into arms fit for a defender of Kalimdor.",h="Weapons of Elunite is the culmination of an early rite of passage for night elf warriors in Darnassus.",sec={{t="A Sacred Forge",b="Night elf warriors carry a sacred duty to defend Teldrassil and the kaldorei people. Rather than relying on mundane steel alone, those who show promise are sent to gather elunite, a mineral imbued with the grace of the Moon Goddess. Fashioning such weapons requires an artisan who understands both metalcraft and the reverence owed to Elune's gifts.",sp=0},{t="Mathiel's Craft",b="Based in the capital city of Darnassus, Smith Mathiel takes great pride in shaping the blessed ore into arms of war. For Mathiel, working with elunite is not simply routine metallurgy but an honor. Upon receiving the ore, he crafts a selection of implements tailored to the warrior's style, rewarding their service with arms blessed by their goddess.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest marks the completion of the early warrior trial based in Darnassus. After securing rare elunite ore, the warrior delivers it to Smith Mathiel, who crafts reliable weapons imbued with the essence of Elune to aid in their journey across Kalimdor.",al={"weapons of elunite quest","why do this quest","warrior level 10 darnassus"}},{q="Who is Mathiel?",a="Mathiel is a skilled night elf armorsmith and weaponsmith residing in Darnassus. He possesses the specialized knowledge needed to forge elunite ore into finely balanced armaments for the city's burgeoning defenders.",al={"smith mathiel","who is mathiel","darnassus smith"}},{q="What is elunite?",a="Elunite is a rare mineral sacred to the night elves, believed to be infused with the luminescence and favor of the Moon Goddess, Elune. Because of its divine nature, artisans consider shaping it into weapons a solemn honor.",al={"what is elunite ore","elunite lore"}},{q="Who can undertake this quest?",a="This quest is reserved strictly for Alliance warriors training around Darnassus who have completed the preliminary tasks to locate and gather elunite for Smith Mathiel.",al={"who gets weapons of elunite","is this warrior only"}},{q="Where does this quest take place?",a="The quest is turned in directly to Smith Mathiel within the night elven capital of Darnassus, located high in the boughs of the World Tree, Teldrassil.",al={"weapons of elunite location","where is mathiel"}},{q="Why does Mathiel thank the adventurer?",a="Mathiel considers working with elunite both a sacred honor and a personal pleasure. Shaping an ore tied to Elune is a privilege few smiths receive, making the warrior's delivery a boon for the craftsman as well.",al={"why is mathiel honored","mathiel dialogue"}}},ang={["class:Warrior"]="This quest represents an essential early rite of martial service for young kaldorei warriors, rewarding their dedication with dependable, Elune-blessed weaponry.",["race:NightElf"]="The forging of elunite reflects how night elf society weaves reverence for the Moon Goddess directly into the practical craft of war and defense.",["profession:Blacksmithing"]="Smith Mathiel's craft demonstrates the delicate balance between conventional metalworking and the treatment of divine materials like elunite."},kw={"darnassus","elune","elunite","kaldorei","mathiel","teldrassil","warrior","weaponsmith"},rel={"quest:1692","zone:darnassus","quest:1703"},m={start="Mathiel",level="10",faction="Alliance",id=1693},src={"Weapons of Elunite"}}
E["quest:1703"] = {t="quest",n="Mathiel",z="darnassus",s="This quest sends an adventurer carrying Furen Longbeard's crafting notes across the seas to Darnassus. The recipient is Mathiel, an artisan smith residing on the Warrior's Terrace eager to study dwarven innovations in mail forging. It represents a vital exchange of martial metallurgy between Ironforge and the kaldorei.",h="This quest sends an adventurer carrying Furen Longbeard's crafting notes across the seas to Darnassus.",sec={{t="A Courier Across the Sea",b="After mastering the difficult process of forging fire-hardened armor, the veteran dwarven smith Furen Longbeard resolves to share his breakthroughs with fellow Alliance craftsmen. Instead of hoarding his newfound metallurgy, Furen copies down detailed technical diagrams and sends his tested adventurer across continents to find Mathiel, an accomplished smith dwelling high in Teldrassil.",sp=0},{t="Kaldorei Steel and Dwarven Craft",b="Mathiel works his forge on the tree-canopied Warrior's Terrace in Darnassus, catering to the Sentinels and fighters who defend the night elven capital. Receiving Furen's notes marks a bridge between disparate crafting traditions: the rugged, subterranean subterranean smelting of the Khaz Modan dwarves and the graceful, nature-attuned armorsmithing of the kaldorei.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a night elf blacksmith stationed on the Warrior's Terrace in Darnassus. He crafts equipment for defenders of the capital and maintains collegial correspondence with fellow master smiths across the Alliance.",al={"mathiel lore","who is mathiel darnassus"}},{q="Why does Furen send you to Darnassus?",a="Furen Longbeard wants his research on forging fire-hardened armor to benefit other Alliance craftsmen. Because Mathiel is a trusted colleague capable of appreciating and utilizing advanced metallurgical techniques, Furen entrusts you with carrying his personal crafting notes to him.",al={"why send notes to mathiel","furen notes reason"}},{q="Where can I find Mathiel in Darnassus?",a="Mathiel can be found at the forge on the Warrior's Terrace, located in the eastern district of Darnassus by the main gate, where warriors and sentinels train.",al={"mathiel location","where is mathiel"}},{q="What happens after giving Mathiel the notes?",a="Impressed by Furen's discoveries, Mathiel decides to build upon the dwarven techniques, sending the warrior on further trials into Kalimdor's wilderness to gather exotic components like sunscorched shells.",al={"next quest after mathiel","mathiel followup"},sp=1},{q="What kind of notes are being delivered?",a="The notes contain detailed metallurgical observations and forging techniques Furen learned while experimenting with scorched spider fangs, chimaera horns, and phlogiston to produce reinforced mail.",al={"furen notes contents","what are furen's notes"}},{q="Is this quest restricted to warriors?",a="Yes, this courier errand is part of the dedicated trial and progression for Alliance warriors developing their martial prowess and armorcraft.",al={"warrior quest mathiel","can other classes do mathiel"}}},ang={["class:Warrior"]="Carrying these notes marks your journey from the fiery smithies of the Eastern Kingdoms to the proving grounds of Darnassus, expanding your personal armory.",["race:Dwarf"]="Sharing Furen's metalworking breakthrough with the night elves highlights the pride dwarves take in their unmatched mastery of the forge.",["race:NightElf"]="Mathiel represents the kaldorei willingness to study subterranean dwarven smithing and blend it with traditional night elven armorsmithing.",["profession:Blacksmithing"]="The delivery illustrates the vital collaboration between master smiths, as blueprints and thermal tempering techniques pass between distant anvils."},kw={"blacksmith","darnassus","fire hardened mail","furen longbeard","furen's notes","mathiel","teldrassil","warrior's terrace"},rel={"quest:1701","quest:1710","npc:furen-longbeard","subzone:warrior-s-terrace","zone:darnassus","quest:1692"},m={start="Furen Longbeard",["end"]="Mathiel",level="28",faction="Alliance",id=1703},src={"Mathiel (quest)"}}
E["quest:1710"] = {t="quest",n="Sunscorched Shells",z="darnassus",s="In Darnassus, the armorer Mathiel collaborates with the dwarven smith Furen Longbeard to refine a new mailcrafting technique. He tasks warriors with traveling to Thousand Needles to gather durable wyvern eggshells from the heights of Highperch.",h="In Darnassus, the armorer Mathiel collaborates with the dwarven smith Furen Longbeard to refine a new...",sec={{t="A Cross-Faction Crafting Alliance",b="Mathiel works out of the Warrior's Terrace in Darnassus, but his trade takes him far beyond traditional night elven techniques. He maintains correspondence with Furen Longbeard, an accomplished dwarven armorer in Stormwind. Inspired by Furen's metallurgy and armor-smithing discoveries, Mathiel seeks to forge a suit of mail reinforced by natural components capable of withstanding extreme strain. To test this hybrid theory, he requires exotic materials that cannot be found anywhere near Teldrassil.",sp=0},{t="The Perils of Highperch",b="The key to Mathiel's experiment lies far to the south across the sea, in the canyon gorges of Thousand Needles. There, high above the salt flats and red stone mesas, Highperch wyverns nest beneath the blazing Kalimdor sun. Their eggshells harden through constant exposure to blistering heat and altitude. Mathiel intends to pulverize these sun-baked fragments and render them into a resilient lacquer, coating the links of chainmail to create flexible yet exceptionally durable armor.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a night elf armorer residing on the Warrior's Terrace in Darnassus. He works closely with dwarven methods, collaborating with Furen Longbeard to develop advanced mail armor for proven warriors.",al={"mathiel","who gives sunscorched shells","mathiel darnassus"}},{q="Why does Mathiel need wyvern shells?",a="The shells from Highperch wyverns are baked and hardened by the harsh sun of Thousand Needles. Mathiel crushes and renders them into a specialized lacquer to coat mail armor links, granting them superior durability.",al={"why wyvern shells","sunscorched shell purpose","what are shells for"}},{q="Where is Highperch located?",a="Highperch is a steep mesa located in western Thousand Needles, near the Feralas border. Wyverns construct their nests across the cliffs and plateau.",al={"highperch location","where is highperch","how to find highperch"}},{q="How does Furen Longbeard relate to this quest?",a="Furen Longbeard is a master dwarven armorer stationed in Stormwind. Mathiel considers Furen a respected colleague and uses Furen's armor-crafting discoveries to inspire his own work in Darnassus.",al={"furen longbeard connection","who is furen"}},{q="Why is an elf in Darnassus asking for materials from Thousand Needles?",a="The specific chemical resilience Mathiel requires is unique to wyvern eggs exposed to the relentless, dry heat of the southern canyon mesas, which cannot be replicated in the misty boughs of Teldrassil.",al={"why thousand needles","darnassus to thousand needles"}},{q="What happens after bringing the shells to Mathiel?",a="Once Mathiel receives twenty sunscorched shells, he begins immediately rendering the lacquer and forging a bespoke suit of mail armor as a reward for your field efforts.",al={"what next mathiel","after sunscorched shells","mathiel follow up"}}},ang={["class:Warrior"]="Mathiel's experiment is aimed at forging resilient mail armor, making this an essential rite of passage for Alliance warriors looking to upgrade their combat gear.",["profession:Blacksmithing"]="The quest demonstrates an unusual smithing technique: rendering beast components into protective lacquers to treat metal chain links.",["faction:Alliance"]="The collaboration highlights the technical exchange between night elf craftsmen in Darnassus and dwarven armorers in Stormwind."},kw={"eggshells","furen longbeard","highperch","lacquer","mail armor","mathiel","thousand needles","wyvern"},rel={"quest:1703","quest:1711","npc:furen-longbeard","subzone:highperch","zone:thousandneedles","zone:darnassus"},m={start="Mathiel",level="30",faction="Alliance",id=1710},src={"Sunscorched Shells"}}
E["quest:1711"] = {t="quest",n="Mathiel's Armor",z="darnassus",s="\"Mathiel's Armor\" marks the completion of an armorsmithing effort undertaken by Mathiel in the Warrior's Terrace of Darnassus. By combining his own night elven craftsmanship with innovative dwarven metalworking methods devised by Furen Longbeard, Mathiel reforges exotic materials into protective battle gear. The quest represents a fruitful blending of allied traditions in service of Alliance warriors.",h="\"Mathiel's Armor\" marks the completion of an armorsmithing effort undertaken by Mathiel in the Warrior's...",sec={{t="A Blend of Crafts",b="Night elven armorers traditionally favor methods honed over millennia, relying on harmony with nature, supple leathers, or delicately worked metals. However, the exchange between the night elves and the Eastern Kingdoms has prompted master smiths like Mathiel to experiment. By incorporating newly devised techniques from the Ironforge armorer Furen Longbeard, Mathiel manages to meld dwarven metallurgy with elven artistry.",sp=0},{t="Exotic Components",b="Forging this resilient armor required sunscorched eggshells gathered from the Highperch wyvern nests of Thousand Needles. By rendering these sun-hardened shells into lacquer and applying Furen's heat-treatment formulas, Mathiel successfully created a resilient breastplate designed to withstand brutal frontline combat.",sp=0}},faq={{q="Who is Mathiel?",a="Mathiel is a skilled night elf armorsmith stationed in the Warrior's Terrace within Darnassus. He works closely with fellow craftsmen across the Alliance, testing new concepts developed by allies such as Furen Longbeard.",al={"mathiel","who is mathiel","darnassus armorer"}},{q="Who is Furen Longbeard?",a="Furen Longbeard is a master dwarven armorsmith residing in Stormwind City. Known for inventing innovative techniques to temper and forge specialized armor plates, he regularly shares instructions and designs with allied smiths throughout the Alliance.",al={"furen","furen longbeard"}},{q="What materials were used to forge the armor?",a="The armor is forged using sunscorched eggshells gathered below the Highperch wyvern nests in Thousand Needles, which Mathiel reinforces and shapes using Furen Longbeard's specific smithing procedures.",al={"armor materials","what is mathiel's armor made of"}},{q="Why is an elf using dwarven techniques?",a="Alliance smiths frequently share knowledge to equip their fighters against escalating threats. While night elf smithing is renowned for finesse and durability, dwarven innovations provide exceptional hardening methods that Mathiel gladly incorporated.",al={"why dwarven smithing","night elf dwarf collaboration"}},{q="Where does this quest take place?",a="The quest begins and completes at the forge located in the Warrior's Terrace of Darnassus on the island of Teldrassil.",al={"mathiel location","where is mathiel"}},{q="What is the previous quest in this chain?",a="This quest immediately follows 'Sunscorched Shells', wherein an adventurer must travel to the far reaches of Kalimdor to acquire tough chitinous shells suitable for Mathiel's craft.",al={"previous quest","mathiels armor prereq"}}},ang={["class:Warrior"]="For Alliance warriors, this quest chain produces sturdy breastplate armor forged through the combined metallurgical wisdom of both Darnassus and Ironforge.",["profession:Blacksmithing"]="The project serves as a shining example of inter-factional crafting, proving that rigid dwarven tempering can harmonize with elegant night elven forge craft.",["faction:Alliance"]="Mathiel and Furen's collaboration illustrates the practical military benefits of the Alliance, uniting distant peoples through shared trade and mutual defense."},kw={"craftsmen's terrace","darnassus","furen longbeard","mathiel","mathiel's armor","sunscorched shells","warrior armor"},rel={"quest:1710","quest:1703"},m={start="Mathiel",level="30",faction="Alliance",id=1711},src={"Mathiel's Armor"}}
E["quest:2242"] = {t="quest",n="Destiny Calls",z="darnassus",s="Destiny Calls is a discreet investigation assigned by Syurna to uncover the source of corruption seeping through Teldrassil's boughs. It tasks an operative with slipping past or confronting a hostile satyr named Sethir the Ancient near the Oracle Glade to recover his journal.",h="Destiny Calls is a discreet investigation assigned by Syurna to uncover the source of corruption seeping...",sec={{t="A Silent Reconnaissance",b="The night elf leadership in Darnassus has watched Teldrassil's growing malady with quiet anxiety. Rather than sending armed patrols that end up dead, the rogue trainer Syurna seeks someone capable of subtle work. Sethir the Ancient, a satyr roosting out on a remote bough near the Oracle Glade, has repelled every attempt at force and diplomatic overture alike. Uncovering what he knows requires slipping into his lair and seizing his personal possessions.",sp=0},{t="A Looming Shadow from Darkshore",b="The recovered pages of Sethir's journal yield grim revelations. The insidious taint threatening the newborn World Tree is directly linked to the ancient rot and corruption consuming the forests and waterways across the misty sea in Darkshore. Rather than an isolated illness of the soil, the affliction points to a wider, deliberate malice threatening the kaldorei heartland.",sp=1}},faq={{q="Who is Sethir the Ancient?",a="Sethir the Ancient is an elusive satyr hiding out on a bough along the northern outskirts of Teldrassil's Oracle Glade. Hostile and cunning, he has thwarted both martial assaults and peaceful inquiries sent to discover what he knows of the island's corruption.",al={"sethir","who is sethir","satyr in oracle glade"}},{q="Why does Syurna want Sethir's journal?",a="Syurna believes Sethir holds crucial insights into the unnatural sickness spreading through Teldrassil. His personal journal contains notes detailing the satyr's activities and the nature of the dark taint.",al={"why sethir journal","syurna objective","what is in the journal"}},{q="What does the journal reveal upon completion?",a="The journal confirms that the sickness seizing Teldrassil's boughs is connected to the deeper, demonic blight gripping the ancient forests and coastlines of Darkshore across the channel.",al={"journal lore","what did sethir find","darkshore connection"},sp=1},{q="Where is this quest received?",a="The task is given by Syurna, the rogue trainer stationed within the shadows of Darnassus, after completing an initial assessment of your competence.",al={"where do i get destiny calls","destiny calls questgiver","who gives destiny calls"}},{q="Where should adventurers go after completing this mission?",a="Syurna notes that you have done all you can for Teldrassil on this matter, pointing young defenders toward Darkshore, where the true root of the mainland's corruption awaits.",al={"what comes next","next step after destiny calls","after sethir"},sp=1},{q="Why is a rogue trainer handling forest corruption instead of druids?",a="Conventional methods—both martial forces and druidic diplomacy—failed against Sethir with lethal consequences. Syurna turns to covert reconnaissance and infiltration when overt efforts meet bloody dead ends.",al={"why rogue quest","why syurna","why not cenarion circle"}}},ang={["class:Rogue"]="Given by Darnassus's own stealth trainers, this mission tests an infiltrator's ability to pilfer sensitive intelligence directly from under a dangerous satyr's nose.",["race:NightElf"]="For kaldorei defenders, learning that the ancient curse of Darkshore has crossed the sea into Teldrassil signals an alarming threat to their sacred refuge.",["faction:Alliance"]="The discovery links local woodland unrest on Teldrassil to broader continental corruption, setting the stage for Alliance forces traveling to northern Kalimdor."},kw={"darkshore","darnassus","destiny calls","journal","oracle glade","satyr","sethir the ancient","syurna","teldrassil"},rel={"npc:syurna","subzone:oracle-glade","zone:darkshore","topic:satyr","quest:940","quest:397"},m={start="Syurna",level="10",faction="Alliance",id=2242},src={"Destiny Calls"}}
E["quest:2259"] = {t="quest",n="Erion Shadewhisper",z="darnassus",s="Erion Shadewhisper is a straightforward summons sending emerging Alliance rogues into Darnassus. Delivered by Jannok Breezesong, the message directs travelers to the Cenarion Enclave where Erion awaits to push their efforts beyond local borders.",h="Erion Shadewhisper is a straightforward summons sending emerging Alliance rogues into Darnassus.",sec={{t="A Summons to the Enclave",b="When a rogue makes a name for themselves in the surrounding lands of Teldrassil, Jannok Breezesong steps in to ensure their talents do not go to waste. Relieving any anxious thoughts about being sent to the exacting trainer Syurna, Jannok instead directs the agent straight into the heart of Darnassus. There, deep within the verdant boughs of the Cenarion Enclave, Erion Shadewhisper oversees matters that require a quieter, more subtle touch.",sp=0},{t="Eyes on the Horizon",b="Reaching Erion marks an important turning point for any rogue operating in night elf territory. His greeting makes it clear that the sheltering forests of Teldrassil can no longer contain an agent's responsibilities. Erion's role is to direct capable hands outward into a wider, more dangerous world, acting as a springboard toward assignments across the sea.",sp=0}},faq={{q="Who sends you to find Erion Shadewhisper?",a="Jannok Breezesong issues the summons, telling you to head into Darnassus immediately to speak with Erion Shadewhisper at the Cenarion Enclave.",al={"quest giver","who starts erion shadewhisper","jannok breezesong quest"}},{q="Where is Erion Shadewhisper located?",a="Erion Shadewhisper is located in the Cenarion Enclave in Darnassus, found nestled among the trees on the enclave's upper tiers.",al={"erion location","where is erion","where to find erion shadewhisper"}},{q="Why does Jannok mention Syurna?",a="Syurna is a prominent rogue trainer in Darnassus known for her sternness and demanding training. Jannok makes a lighthearted quip reassuring you that you are not in trouble or being hauled in for her rigorous lessons.",al={"who is syurna","why not syurna","jannok syurna line"}},{q="What happens after reporting to Erion?",a="Upon completing your report, Erion gives you his next task in the quest Erion's Behest, sending you out of Teldrassil to broaden your operational reach in Kalimdor.",al={"what next","erion follow up","quest after erion shadewhisper"}},{q="What kind of work does Erion oversee?",a="Erion coordinates operations and directs fledgling rogues within Darnassus, acting as a handler who connects local agents to broader missions across the Alliance network.",al={"is erion a rogue trainer","erion shadewhisper role","what does erion do"}},{q="Why is a rogue handler stationed in the Cenarion Enclave?",a="While the Cenarion Enclave is primarily known for druids and nature worship, its sprawling, shadowed trees provide ample seclusion for stealthier operatives to gather and conduct business away from the Temple of the Moon.",al={"cenarion enclave rogue","why druid area for rogue"}}},ang={["class:Rogue"]="This breadcrumb quest signifies your transition out of novice work on Teldrassil, pointing you directly to Erion Shadewhisper for missions that demand finesse beyond the starting forests.",["race:NightElf"]="For night elf shadow-stalkers, reporting to Erion in Darnassus is an essential rite of passage, transitioning from local warding to wider continental duties.",["faction:Alliance"]="The quest directs Alliance operatives in northern Kalimdor to coordinate with Darnassus handlers before venturing out into contested territory."},kw={"cenarion enclave","darnassus","erion shadewhisper","erion's behest","jannok breezesong","rogue breadcrumb","syurna"},rel={"quest:2260","npc:jannok-breezesong","subzone:cenarion-enclave","zone:darnassus","npc:syurna"},m={start="Jannok Breezesong",["end"]="Erion Shadewhisper",level="16",faction="Alliance",id=2259},src={"Erion Shadewhisper (quest)"}}
E["quest:2260"] = {t="quest",n="Erion's Behest",z="darnassus",s="Erion's Behest is a summons dispatched to promising night elf rogues operating out of Darnassus. Recognizing their budding stealthcraft, the rogue mentor Erion Shadewhisper sends them across the sea to Stormwind City to report directly to Stormwind Intelligence.",h="Erion's Behest is a summons dispatched to promising night elf rogues operating out of Darnassus.",sec={{t="A Summons Across the Sea",b="Night elf rogues operating in the shadow of Teldrassil typically hone their skills under the quiet watch of mentors like Erion Shadewhisper. However, when an operative demonstrates exceptional talent, word travels well beyond the boughs of the World Tree. Through Erion, Stormwind Intelligence—better known as SI:7—extends a direct invitation to travel across the Great Sea to the human capital.",sp=0},{t="Entering the Service of SI:7",b="The journey is arduous, taking the operative from Kalimdor's northern reaches through the docks of Darkshore or the Wetlands and into the bustling streets of Stormwind City. Once in the capital, the operative must slip into Old Town and report to SI:7 headquarters. There, Renzik \"The Shiv\" awaits to assess the newcomer, opening the door to advanced espionage, poison mastery, and covert operations on behalf of the Alliance.",sp=0}},faq={{q="Who sends me on this mission?",a="Erion Shadewhisper, the rogue trainer in Darnassus, gives you this assignment after your early deeds catch the attention of intelligence networks across the sea.",al={"quest giver","erion shadewhisper","who gave me this"}},{q="Why is Stormwind Intelligence contacting a night elf?",a="Though the night elves have their own stealth traditions, the Alliance relies heavily on SI:7 to coordinate covert intelligence and sabotage. Stormwind Intelligence regularly seeks out capable rogues of any Alliance race to bolster their operational ranks.",al={"why si:7","why stormwind","why do humans care"}},{q="Where do I find Renzik 'The Shiv'?",a="Renzik 'The Shiv' is stationed inside the SI:7 headquarters, located tucked away within the Old Town district of Stormwind City.",al={"renzik location","where is the shiv","find renzik"}},{q="Is this quest only for rogues?",a="Yes. This is an Alliance rogue class quest intended to guide Kalimdor-based operatives to the central hub of Alliance intelligence training in Stormwind.",al={"rogue only","can other classes do this","is this rogue quest"}},{q="What happens after meeting Renzik?",a="Reporting to Renzik integrates you into SI:7's training operations in the Eastern Kingdoms, setting you up for specialized training and covert assignments throughout the human lands.",al={"next quest","what do i get","after renzik"}},{q="How does a night elf get to Stormwind City at this stage?",a="A traveler must take a boat from Auberdine in Darkshore across the sea to Menethil Harbor in the Wetlands, make the dangerous trek through Loch Modan and Dun Morogh to Ironforge, and ride the Deeprun Tram into Stormwind City.",al={"how to get to stormwind","travel to stormwind","path to stormwind"}}},ang={["class:Rogue"]="This summons marks your graduation from local Kalimdor scuffles into the broader realm of continental espionage and lethal training under SI:7.",["race:NightElf"]="Leaving the shelter of Darnassus and Teldrassil to serve human intelligence networks in the stone alleys of Stormwind is often a stark culture shock for Kaldorei prowlers.",["faction:Alliance"]="SI:7 centralizes covert operations for the Alliance, ensuring talented scouts from every member race can be deployed where the crown needs them most."},kw={"darnassus","erion shadewhisper","erion's behest","old town","renzik the shiv","rogue","si:7","stormwind"},rel={"npc:renzik-the-shiv","quest:2259","quest:2300","subzone:old-town","zone:stormwind","topic:stormwind-kingdom"},m={start="Erion Shadewhisper",["end"]="Renzik \"The Shiv\"",level="16",faction="Alliance",id=2260},src={"Erion's Behest"}}
E["quest:2518"] = {t="quest",n="Tears of the Moon",z="darnassus",s="Tears of the Moon is a solemn task assigned by Priestess A'moora in the Temple of the Moon. Once cherished by the goddess Elune, the great spider Lady Sathrah has fallen into madness, forcing the Sisterhood of Elune to seek her merciful end and retrieve her sacred spinnerets.",h="Tears of the Moon is a solemn task assigned by Priestess A'moora in the Temple of the Moon.",sec={{t="A Beloved Creature's Fall",b="Within the serene confines of Darnassus's Temple of the Moon, Priestess A'moora laments the tragic fate of Lady Sathrah. In earlier days, Sathrah was celebrated as a blessed creature of Elune. She wove delicate silver webs beneath the night sky, catching the evening mist that gathered upon Teldrassil's boughs. The shimmering dew her webs collected possessed miraculous healing properties, carefully gathered and preserved by the Sisterhood of Elune for their sacred ministrations.",sp=0},{t="Mercy for Sathrah",b="Like much of the wildlife across the young World Tree, Lady Sathrah has recently fallen prey to an overwhelming madness. Her corruption threatens not only travelers but her own unhatched broods along the northern reaches near Wellspring Lake. Unable to cleanse her while she roams violent and frantic, the Sisterhood resolved that ending her suffering was the only compassionate path remaining. By retrieving her silvery spinnerets, the priestesses intend to dedicate her remains upon Elune's altar, praying that the Moon Goddess will grant her peace and a pure rebirth.",sp=1}},faq={{q="Who is Lady Sathrah?",a="Lady Sathrah is a majestic, ancient spider native to Teldrassil. Traditionally revered as beloved of Elune, she was known for weaving silvery webs that trapped night mist rich in natural healing potency.",al={"lady sathrah lore","who is lady sathrah","sathrah backstory","sathrah spider"}},{q="Why does Lady Sathrah have to be killed?",a="She succumbed to a creeping madness that has infected Teldrassil's wildlife. Because she became violently unhinged and a danger to both her offspring and others, the priestesses decided slaying her was an act of mercy.",al={"why kill sathrah","can sathrah be saved","why is sathrah aggressive"}},{q="Where is Lady Sathrah found?",a="Lady Sathrah makes her lair in the northern wilderness of Teldrassil, near the shores of Wellspring Lake.",al={"lady sathrah location","where is sathrah","find sathrah"}},{q="What were Lady Sathrah's webs used for?",a="Her webs caught the evening mist, forming a potent silvery dew known for profound healing powers, which the Sisterhood of Elune kept in the Temple of the Moon.",al={"tears of the moon meaning","sathrah webs use","silvery dew lore"}},{q="Who gives the quest Tears of the Moon?",a="Priestess A'moora, an attendant serving within the Temple of the Moon in Darnassus, gives the quest to trusted Alliance adventurers.",al={"who gives tears of the moon","tears of the moon quest giver","priestess amoora"}},{q="What will the priestesses do with Sathrah's spinnerets?",a="They are offered to Elune at the temple altar as a consecration, asking the goddess to accept Sathrah's spirit, bless her, and allow her to be reborn in peaceful tranquility.",al={"what happens to the spinnerets","spinnerets purpose","sacrifice to elune"}}},ang={["race:NightElf"]="For the Kaldorei, putting down Sathrah is a painful reminder that the corruption touching Teldrassil's wilds spares neither the humble beast nor the sacred companions of Elune.",["class:Priest"]="Priests serving the Sisterhood of Elune understand that mercy sometimes requires a sorrowful strike, culminating in a ritual offering to return a corrupted soul to the Goddess's embrace.",["class:Druid"]="Druids view Sathrah's sudden ferocity and torment as another troubling symptom of Teldrassil's imbalance, making the restoration of her spirit an ecological necessity."},kw={"darnassus","elune","lady sathrah","priestess a'moora","silvery spinnerets","tears of the moon","teldrassil","temple of the moon","wellspring lake"},rel={"npc:priestess-a-moora","subzone:temple-of-the-moon","quest:2520","quest:2519","subzone:wellspring-lake","topic:elune","zone:darnassus","quest:940"},m={start="Priestess A'moora",level="12",faction="Alliance",id=2518},src={"Tears of the Moon (Classic)"}}
E["quest:2519"] = {t="quest",n="The Temple of the Moon",z="darnassus",s="The Temple of the Moon is an introductory quest in Darnassus where Sister Aquinne directs adventurers to seek out Priestess A'moora. The Sisterhood of Elune requires aid for a suffering ancient creature dwelling within the boughs of Teldrassil. It serves as the opening call to a solemn ritual of mercy.",h="The Temple of the Moon is an introductory quest in Darnassus where Sister Aquinne directs adventurers to seek...",sec={{t="A Plea in the Gardens",b="While walking among the waters and shaded groves of the Temple Gardens, travelers meet Sister Aquinne, a devoted servant of Elune. Sensing capable hands, she reaches out on behalf of her order. A venerable forest creature is suffering, and the Sisters cannot attend to the matter alone.",sp=0},{t="Into the Moon Temple",b="Sister Aquinne directs candidates toward the grand Temple of the Moon just to the southeast. There, Priestess A'moora coordinates the rituals and practical duties required to address Teldrassil's troubled wildlife, preparing sympathetic allies to carry out a sorrowful task of mercy.",sp=0}},faq={{q="Who starts the quest The Temple of the Moon?",a="Sister Aquinne initiates the quest. She can be found standing outside in the Temple Gardens district of Darnassus.",al={"quest giver temple of the moon","where to get temple of the moon quest","who gives the temple of the moon"}},{q="Where is Priestess A'moora located?",a="Priestess A'moora is located inside the grand Temple of the Moon, situated just southeast of the Temple Gardens in Darnassus.",al={"where is priestess amoora","find amoora","priestess a'moora location"}},{q="What is the creature in need of help?",a="The creature in question is Sathrah, a revered spider of Teldrassil whose plight leads into a ritual of mercy overseen by the priesthood.",al={"what creature needs help","who is the forest creature","what is this quest chain about"}},{q="Is this quest mandatory to continue the chain?",a="No. The Temple of the Moon serves as an optional breadcrumb quest. You can speak directly with Priestess A'moora inside the temple to undertake the ritual tasks without visiting Sister Aquinne first.",al={"is temple of the moon required","can i skip temple of the moon","temple of the moon breadcrumb"}},{q="What quest follows after this one?",a="Priestess A'moora offers the quest Tears of the Moon, directing you to gather sacred materials needed to cleanse and lay Sathrah to rest.",al={"next quest after temple of the moon","temple of the moon follow up","what comes next"}},{q="Why is the Sisterhood of Elune asking outsiders for help?",a="The corruption lingering within Teldrassil's flora and fauna stretches the Sisterhood thin, compelling priestesses to recruit competent travelers who respect nature and the Goddess.",al={"why ask outsiders","why does the priesthood need help","sister aquinne motive"}}},ang={["race:NightElf"]="For night elves, answering Sister Aquinne is an extension of their duty to protect the sacred ecosystem of Teldrassil and uphold the guidance of Elune's priesthood.",["class:Priest"]="Priests walking the grounds of Darnassus are naturally drawn to the work of the Sisterhood, assisting fellow servants of the divine in rites of healing and mercy.",["class:Druid"]="Druids hold deep concern for any great creature of the wild in distress, making the call from the Temple Gardens an urgent matter of natural harmony."},kw={"darnassus","elune","priestess a'moora","sathrah","sister aquinne","sisterhood of elune","temple gardens","temple of the moon"},rel={"quest:2518","quest:2520","npc:sister-aquinne","npc:priestess-a-moora","subzone:temple-of-the-moon","subzone:temple-gardens","zone:darnassus"},m={start="Sister Aquinne",["end"]="Priestess A'moora",level="10",faction="Alliance",id=2519},src={"The Temple of the Moon (Classic)"}}
E["quest:2520"] = {t="quest",n="Sathrah's Sacrifice",z="darnassus",s="Sathrah's Sacrifice is the conclusion to a somber ritual performed within the Temple of the Moon in Darnassus. Entrusted with the remains of Lady Sathrah, players offer the fallen creature's spinnerets to Elune's sacred waters to cleanse her soul of corruption and lay her spirit to rest.",h="Sathrah's Sacrifice is the conclusion to a somber ritual performed within the Temple of the Moon in Darnassus.",sec={{t="A Cleansing in Sacred Waters",b="Following the tragic slaying of Lady Sathrah, Priestess A'moora charges initiates with a final spiritual duty. The great spider had fallen prey to the dark madness spreading across Teldrassil, warping her once-peaceful nature into mindless aggression. Rather than treating her death as a simple culling, the Priesthood of Elune seeks to redeem her fallen essence. By placing her silvery spinnerets into the central fountain of the Temple of the Moon, the consecrated waters wash away the tainting corruption, granting her release.",sp=0},{t="The Renewal of Sathrah",b="Offering the sacrifice to Elune brings immediate spiritual communion. As the spinnerets touch the moonlit pool, the ethereal form of Lady Sathrah rises from the depths, peaceful and cleansed of the affliction that drove her mad. The Sisterhood of Elune views this ritual as necessary salvation; though the loss of the great creature is deeply felt, night elven theology teaches that through this sacred purification, she can one day be reborn with an uncorrupted spirit.",sp=1}},faq={{q="Who was Lady Sathrah?",a="Lady Sathrah was a great spider inhabiting Teldrassil who succumbed to the creeping corruption afflicting the World Tree's wildlife. Driven mad by the taint, she had to be slain so her remains could be sanctified.",al={"lady sathrah","who is sathrah","what is sathrah"}},{q="Where is the sacrifice offered?",a="The sacrifice is placed into the holy fountain located at the center of the Temple of the Moon, the central sanctuary of the Sisterhood of Elune in Darnassus.",al={"where do i put the sacrifice","fountain location","temple fountain"}},{q="What happens when you place the spinnerets in the fountain?",a="Upon placing the silvery spinnerets into the blessed waters, the purified Spirit of Sathrah manifests briefly in the pool, walking freely and peacefully to signal Elune's acceptance.",al={"what happens at the fountain","spirit of sathrah fountain"},sp=1},{q="Why did Lady Sathrah have to die?",a="The corruption poisoning her mind was too deep to heal while living. Priestess A'moora and the Sisterhood believed the only way to save her soul was to end her suffering and cleanse her remains in Elune's holy waters.",al={"why kill sathrah","could sathrah be saved","sathrah madness"}},{q="Who gives the quest Sathrah's Sacrifice?",a="The quest is provided and concluded by Priestess A'moora, who serves within the Temple of the Moon in Darnassus overlooking the central chamber.",al={"quest giver","where to turn in","amoora location"}},{q="What belief underpins this ritual for the night elves?",a="The night elves believe that souls purified by the Mother Moon can be reborn into the natural world with their spirits cleansed and renewed, free from the lingering stain of corruption.",al={"night elf reincarnation","elune purification","rebirth lore"}}},ang={["race:NightElf"]="For night elves, this rite reflects their solemn duty to the flora and fauna of Kalimdor: even when creatures must be slain, their spirits are honored and cleansed through Elune's grace.",["class:Priest"]="Priests walking the Temple of the Moon see firsthand how Elune's holy light and sacred waters can mend spirits severed by madness and corruption.",["class:Druid"]="Druids who mourn the sickness plaguing Teldrassil find solace in knowing that fallen beasts can be restored to the natural cycle through purification."},kw={"a'moora","darnassus","elune","fountain","lady sathrah","purification","sathrah","spinnerets","teldrassil","temple of the moon"},rel={"quest:2518","quest:2519","subzone:temple-of-the-moon","npc:priestess-a-moora","topic:elune"},m={start="Priestess A'moora",level="12",faction="Alliance",id=2520},src={"Sathrah's Sacrifice (quest)"}}
E["quest:27"] = {t="quest",n="A Lesson to Learn",z="darnassus",s="\"A Lesson to Learn\" is an early rite of passage for Alliance druids training in Darnassus. Offered by Mathrengyl Bearwalker, it directs initiates to travel to the sacred haven of Moonglade to begin mastering their aquatic aspect.",h="\"A Lesson to Learn\" is an early rite of passage for Alliance druids training in Darnassus.",sec={{t="The Call of the Wild",b="Mathrengyl Bearwalker watches over young night elf druids practicing their craft within the boughs of Darnassus. Once an initiate demonstrates a steadfast bond with nature and the will to shoulder greater responsibility, Mathrengyl bids them prepare for their next major discipline: the mastery of the waters. The gifts bestowed by Cenarius demand rigorous focus, and the ability to traverse depths without drowning requires direct communion with the elders of the Cenarion Circle.",sp=0},{t="Journey to Nighthaven",b="To proceed, the initiate must depart Darnassus and journey to Moonglade, the ancient sanctuary tucked beneath Mount Hyjal. Within the tranquil settlement of Nighthaven, Dendrite Starblaze awaits. Serving as an elder mentor of the Circle, Starblaze evaluates whether young shapeshifters are ready to take on the trials required to unlock the aquatic form, warning them that mastery over water demands both physical resilience and mental resolve.",sp=0}},faq={{q="Who sends me on this quest?",a="Mathrengyl Bearwalker, the druid trainer residing in the Cenarion Enclave within Darnassus, gives this quest once you have grown sufficiently in your early druidic arts.",al={"quest giver","who gives a lesson to learn","who starts this"}},{q="What is the purpose of this quest?",a="It serves as the opening step for druids seeking to earn their aquatic form. It summons the initiate to Moonglade to receive instruction and trials from elder Dendrite Starblaze.",al={"why do this quest","aquatic form intro","what do i get"}},{q="Where is Dendrite Starblaze located?",a="Dendrite Starblaze resides in the village of Nighthaven, nestled along the northern shores of Lake Elune'ara in Moonglade.",al={"dendrite location","where is dendrite starblaze","find dendrite"}},{q="How do druids reach Moonglade for this quest?",a="Druids possess a spiritual attunement that allows them to teleport directly to the sacred grove of Moonglade using their Teleport: Moonglade ability, bypassing conventional overland routes.",al={"how to get to moonglade","getting to nighthaven"}},{q="What comes after speaking to Dendrite Starblaze?",a="Upon completing your audience with Dendrite Starblaze, he immediately tasks you with the Trial of the Lake to test your endurance and clarity beneath the water.",al={"next quest","what's next","after a lesson to learn"}}},ang={["class:Druid"]="This quest marks an important milestone in a druid's training, opening the path to communing with Cenarius's gifts beneath the waves.",["race:NightElf"]="For the kaldorei of Darnassus, answering the call of the Cenarion Circle in Moonglade is a revered tradition that connects them to their ancient teachers."},kw={"a lesson to learn","aquatic form","darnassus","dendrite starblaze","druid quest","mathrengyl bearwalker","moonglade","nighthaven"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:nighthaven","quest:5921","quest:31","topic:cenarion-circle","topic:cenarius","topic:druid"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="16",faction="Alliance",id=27},src={"A Lesson to Learn (Alliance)"}}
E["quest:3370"] = {t="quest",n="In Nightmares",z="darnassus",s="Following the discovery of a strange glowing shard, Falla Sagewind recognizes that the artifact contains the pure essence of the Emerald Dream tainted by dark visions. She dispatches an adventurer to Darnassus to deliver the disturbing relic directly to the elder druids of the Cenarion Circle.",h="Following the discovery of a strange glowing shard, Falla Sagewind recognizes that the artifact contains the...",sec={{t="A Troubling Revelation",b="The glowing shard recovered from the depths of Wailing Caverns proves far more dangerous than simple crystal. Upon inspecting it, Falla Sagewind identifies it as an embodiment of the Emerald Dream's purest essence. Yet rather than reflecting the verdant perfection of Azeroth's primal blueprint, the stone twists with unsettling, fearful visions. Shaken by what she sees, Falla refuses to delve deeper herself and insists the shard must be safely transferred to senior leadership within the Cenarion Circle.",sp=0},{t="Whispers in the Cenarion Enclave",b="In Darnassus, the relic is presented to Mathrengyl Bearwalker, an experienced druid within the Cenarion Enclave. Greeted initially with calm curiosity, Mathrengyl is visibly unsettled the moment he gazes into the shard's core. Realizing that the corruption plaguing the Barrens connects directly to disturbances deep within the Emerald Dream itself, he quickly hushes further discussion. The elder druid warns that such terrifying anomalies are not matters for common ears, quietly taking custody of the Nightmare Shard to study the encroaching shadow.",sp=1}},faq={{q="What is the Nightmare Shard?",a="The Nightmare Shard is a crystallized piece of the Emerald Dream's essence, originally recovered as a mysterious glowing shard. Instead of reflecting natural harmony, it emanates dark visions and corrupting power, revealing that a sinister presence has begun invading the Dream.",al={"what is nightmare shard","glowing shard lore","emerald dream shard"},sp=1},{q="Who is Falla Sagewind?",a="Falla Sagewind is a tauren druid of nature's lore who inspects strange relics found across the wilds. Upon realizing the true, terrifying origin of the glowing shard, she refers travelers to higher druidic authorities in Darnassus.",al={"falla sagewind","who is falla"}},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is an elder druid trainer of the Cenarion Circle stationed at the Cenarion Enclave in Darnassus. He acts as an experienced mentor and investigates serious spiritual threats affecting nature and the Emerald Dream.",al={"mathrengyl bearwalker","bearwalker darnassus","who is mathrengyl"}},{q="Why is Mathrengyl so secretive about the shard?",a="The Emerald Dream is revered as the pristine, inviolable realm of nature guided by the Green Dragonflight and the sleeping druids. Evidence that this realm is suffering from nightmarish corruption represents a profound spiritual crisis, one the Cenarion Circle is reluctant to expose to the public.",al={"why secret","what does mathrengyl hide","why won't mathrengyl talk"},sp=1},{q="Where does this quest chain begin?",a="The storyline begins with 'The Glowing Shard', an item found on Mutanus the Devourer at the culmination of the Wailing Caverns. That shard is brought to scholars who eventually trace its ominous origins toward Darnassus or Thunder Bluff.",al={"in nightmares prereq","where did this start","how to get in nightmares"}},{q="Do Horde players have an equivalent quest?",a="Yes. While Alliance heroes report to Mathrengyl Bearwalker in Darnassus, Horde champions deliver their findings to Hamuul Runetotem on the Elder Rise in Thunder Bluff, discovering the same unsettling news about the Emerald Dream.",al={"horde version","is there a horde in nightmares","in nightmares horde"}}},ang={["class:Druid"]="For druids, this quest reveals that the sacred Emerald Dream is not the untouched sanctuary they were taught to commune with, hinting at profound internal danger.",["faction:Alliance"]="Alliance adventurers carrying this relic into the heart of Darnassus offer the night elf leadership an early glimpse of the corruption spreading beneath the world's surface.",["race:NightElf"]="Night elves venerate the slumbering realm where Malfurion Stormrage resides; discovering a waking nightmare inside its essence strikes at the core of their spiritual heritage."},kw={"cenarion circle","cenarion enclave","darnassus","emerald dream","falla sagewind","glowing shard","in nightmares","mathrengyl bearwalker","nightmare shard"},rel={"quest:6981","npc:mathrengyl-bearwalker","npc:falla-sagewind","topic:cenarion-circle","topic:emerald-dream","zone:darnassus","topic:druid","quest:3369"},m={start="Falla Sagewind",["end"]="Mathrengyl Bearwalker",level="25",faction="Alliance",id=3370},src={"In Nightmares (Alliance)"}}
E["quest:5061"] = {t="quest",n="Aquatic Form",z="darnassus",s="Aquatic Form is the culminating rite of passage for Alliance druids learning to attune their spirits to the deep waters. Having gathered the fractured halves of the Pendant of the Sea Lion across Kalimdor and forged them in Moonglade, initiates return to Darnassus to unlock their new shapeshifting aspect.",h="Aquatic Form is the culminating rite of passage for Alliance druids learning to attune their spirits to the...",sec={{t="A Sacred Bond with the Depths",b="For an initiate of the Cenarion Circle, shapeshifting is not mere spellcraft—it is an act of spiritual communion with the wild aspects of Azeroth. After proving their resilience in dark coastal depths and enduring the trials set before them in Moonglade, young night elf druids receive the assembled Pendant of the Sea Lion from Dendrite Starblaze. Carrying this sacred token back to Teldrassil serves as living proof that the initiate respects the natural laws governing air, water, and breath.",sp=0},{t="Return to Darnassus",b="In the boughs of the Cenarion Enclave, the elder druid trainer Mathrengyl Bearwalker awaits the aspirant's return. The trials undertaken along the coasts of Darkshore and Westfall require profound endurance and attunement. By presenting the completed pendant, the initiate demonstrates to Bearwalker that their mind and body are prepared to shed their mortal skin and embrace the swift, breathing aspect of the sea lion.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest is the final step in an Alliance druid's training to learn Aquatic Form. By presenting the restored Pendant of the Sea Lion to Mathrengyl Bearwalker in Darnassus, the druid earns the right to be taught the aquatic shapeshifting aspect.",al={"why do this quest","aquatic form purpose","what does this quest give"}},{q="Who sends you back to Darnassus?",a="Dendrite Starblaze, an elder of the Cenarion Circle residing in the sacred haven of Moonglade, sends you back to Teldrassil after you successfully complete the Trial of the Sea Lion.",al={"who gives this quest","quest giver","dendrite starblaze"}},{q="Who completes your training in Darnassus?",a="Mathrengyl Bearwalker, the druid trainer located in the Cenarion Enclave within Darnassus, receives your pendant and bestows the training for your aquatic aspect.",al={"quest hand in","who turns in aquatic form","mathrengyl bearwalker"}},{q="What is the Pendant of the Sea Lion?",a="The Pendant of the Sea Lion is a sacred talisman created by combining two trial pendants recovered from watery depths along Kalimdor's shores. It serves as tangible proof that a druid has mastered the endurance and patience required of sea creatures.",al={"what is the pendant","pendant of the sea lion lore"}},{q="Do Horde druids do this exact quest?",a="No. While Tauren druids also undergo trials in Moonglade to earn their aquatic aspect, their journey directs them back to Turak Runetotem on the mesas of Thunder Bluff rather than to Darnassus.",al={"can tauren do this","is this quest alliance only","horde version"}},{q="Where in Darnassus is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker resides in the Cenarion Enclave, a lush sanctuary nestled in the northwestern district of Darnassus atop the boughs of Teldrassil.",al={"where is mathrengyl","darnassus druid trainer location"}}},ang={["class:Druid"]="This quest marks an essential milestone in your communion with nature, granting you the ability to move swiftly underwater and breathe beneath the surface indefinitely.",["race:NightElf"]="For night elf initiates, returning from the timeless woods of Moonglade to the youthful crown of Teldrassil affirms their duty to protect Azeroth's wilderness in an era of shifting balance.",["faction:Alliance"]="Completing your druidic trials provides the Alliance with scouts capable of effortlessly traversing lakes, rivers, and coastal shores."},kw={"aquatic form","cenarion enclave","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","sea lion"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","topic:druid","zone:darnassus","quest:5921","quest:31"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="16",faction="Alliance",id=5061},src={"Aquatic Form (Alliance)"}}
E["quest:5627"] = {t="quest",n="Stars of Elune",z="darnassus",s="Stars of Elune marks a major milestone in a young night elf priest's communion with the Moon Goddess. Upon proving their dedication to their people, acolytes are invited to the Temple of the Moon in Darnassus to learn sacred arts unique to the Sisterhood of Elune.",h="Stars of Elune marks a major milestone in a young night elf priest's communion with the Moon Goddess.",sec={{t="A Rite of Devotion",b="Night elf priests do not draw their holy power from the broad philosophical tenets of the Light, as humans and dwarves do, but directly from their goddess, Elune. When an acolyte shows steadfast dedication while serving the realm, the Sisterhood in Darnassus recognizes that devotion. Summoned to the Temple of the Moon, the priest is deemed worthy of deeper communion and offered insight into sacred spells passed down through thousands of years of worship.",sp=0},{t="Gifts of the Moon Goddess",b="Upon answering the call of Priestess Alathea, an initiate receives direct instruction in holy mysteries unique to their heritage, such as Starshards. These spells channel the radiant, celestial wrath and grace of the White Lady. Receiving this instruction signifies that an acolyte has graduated beyond basic training and is prepared to venture beyond the protective canopy of Teldrassil in Elune's name.",sp=0}},faq={{q="What is the purpose of this quest?",a="Stars of Elune represents an initiate's formal recognition by the Sisterhood of Elune. Upon completion, Priestess Alathea instructs the young priest in racial spells specific to night elves, such as Starshards, marking their growth as a chosen vessel of the Moon Goddess.",al={"stars of elune quest","what do i get","why do this quest"}},{q="Who offers Stars of Elune?",a="The quest is completed by Priestess Alathea, an ordained leader of the Sisterhood of Elune stationed within the grand Temple of the Moon in Darnassus.",al={"who gives stars of elune","quest giver stars of elune","where is alathea"}},{q="Why is this quest restricted to night elves?",a="The rites taught during this quest belong specifically to the Sisterhood of Elune, the ancient priesthood governing night elf faith. Unlike other Alliance priesthoods that study the universal Holy Light, kaldorei priests derive their distinct magic directly from communion with Elune.",al={"can humans do this","is this night elf only","who can do stars of elune"}},{q="Where does this quest lead within the priest storyline?",a="This quest immediately follows 'Returning Home,' which directs an aspiring priest who has been helping across Teldrassil back to the capital city to seek further instruction at the Temple of the Moon.",al={"what comes before stars of elune","stars of elune prereq","returning home quest"}},{q="What kind of magic does Elune bestow on her priests?",a="Priests devoted to Elune weave moonlight, starlight, and shadow. Unique rituals like Starshards allow kaldorei worshippers to bring down incandescent celestial fire upon enemies, blending divine judgment with astral wrath.",al={"elune spells","night elf priest magic","starshards lore"}},{q="Where in Darnassus does this take place?",a="It takes place inside the Temple of the Moon, the gleaming marble sanctuary that towers over the southern quarter of Darnassus and serves as the religious heart of the kaldorei nation.",al={"stars of elune location","where is priestess alathea","temple of the moon location"}}},ang={["class:Priest"]="This rite marks the divergence between kaldorei priests and those of other races, unlocking the astral spells granted solely by the Moon Goddess.",["race:NightElf"]="For the kaldorei, serving Elune is inseparable from civic and cultural life; answering the Sisterhood's summons represents coming of age in service to Teldrassil.",["faction:Alliance"]="While human and dwarven priests preach devotion to the Holy Light, the night elves' devotion to Elune brings ancient, distinct celestial magic into the Alliance's ranks."},kw={"darnassus","priestess alathea","returning home","sisterhood of elune","stars of elune","starshards","temple of the moon"},rel={"npc:priestess-alathea","topic:elune","quest:5628"},m={start="Priestess Alathea",level="10",faction="Alliance",id=5627},src={"Stars of Elune"}}
E["quest:5628"] = {t="quest",n="Returning Home",z="darnassus",s="\"Returning Home\" is a summons sent to young night elf priests who have wandered as far as the human lands of Elwynn Forest. Priestess Josetta in Goldshire relays an urgent message from Darnassus, bidding the novice return to the Temple of the Moon to further their spiritual training under Priestess Alathea.",h="\"Returning Home\" is a summons sent to young night elf priests who have wandered as far as the human lands of...",sec={{t="A Word in Goldshire",b="Night elves are an unusual sight in Elwynn Forest, and a fledgling acolyte wandering among human settlements catches immediate attention. When such a priest arrives in Goldshire, Priestess Josetta greets them with both warmth and news. A Sister of Elune has traveled across continents seeking the young devotee, bearing an urgent command from the Temple of the Moon: it is time to return to Kalimdor and advance their calling.",sp=0},{t="The Call of the Temple",b="At the heart of Darnassus stands the Temple of the Moon, the epicenter of night elven faith and leadership. Priestess Alathea and High Priestess Tyrande Whisperwind oversee the instruction of the Sisterhood, keeping close watch over their disciples even when curiosity carries them overseas. Upon returning, initiates are welcomed back with motherly concern and immediately set onto deeper studies regarding the celestial mysteries of the Moon Goddess.",sp=0}},faq={{q="Why is a night elf priest being summoned from human lands?",a="Young night elf priests who journey to the Eastern Kingdoms are still bound to their sacred order in Teldrassil. Priestess Alathea tracks their progress and calls them back to the Temple of the Moon once they are ready to learn higher-order rites of Elune.",al={"why am i called back","why returning home","priest quest goldshire"}},{q="Who is Priestess Josetta?",a="Priestess Josetta is the human priest trainer stationed at the Lion's Pride Inn in Goldshire. She serves the Holy Light but respects visiting kaldorei acolytes, acting as a liaison when emissaries from Darnassus come searching for their wayward kin.",al={"who gives returning home","goldshire priest trainer","priestess josetta"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a senior Sister of Elune who trains acolytes within the Temple of the Moon in Darnassus. Working closely with High Priestess Tyrande Whisperwind, she monitors the growth and spiritual dedication of novice night elf priests.",al={"who is alathea","temple priest trainer","priestess alathea"}},{q="What happens after returning to Darnassus?",a="Once you report back to Priestess Alathea at the Temple of the Moon, she welcomes you safely home and introduces your next spiritual task: the quest 'Stars of Elune,' which delves deeper into the sacred power granted by the goddess.",al={"what comes next","next quest after returning home","followup quest"}},{q="How does this differ from the normal training path?",a="This quest is an alternate breadcrumb specifically designed for night elf priests who chose to level in human lands such as Elwynn Forest rather than staying in Teldrassil. It ensures they are redirected back to their racial trainers in Darnassus to unlock their race-specific priestly abilities.",al={"do all priests do this","is this quest mandatory","elwynn priest quest"}},{q="How did the messenger find an acolyte all the way in Elwynn Forest?",a="A priestess from the Sisterhood traveled all the way from Darnassus to the Eastern Kingdoms, leaving word with Alliance trainers like Priestess Josetta in Goldshire to watch for the traveling novice and direct them back home.",al={"how did they know i was here","who tracked me to goldshire"}}},ang={["class:Priest"]="Every priest order has roots in deep tradition; for kaldorei acolytes, true advancement in the lunar rites can only be sanctioned by the senior priestesses at the Temple of the Moon.",["race:NightElf"]="Wandering far across the sea to the lands of the young races is an ambitious path, but the call of Teldrassil and the blessings of Elune always draw kaldorei back to their sacred sanctuaries.",["faction:Alliance"]="The shared hospitality between the Church of the Holy Light in Elwynn and the Sisterhood of Elune in Darnassus demonstrates the growing cooperative bonds uniting the Alliance races."},kw={"darnassus","elune","goldshire","priestess alathea","priestess josetta","returning home","stars of elune","temple of the moon"},rel={"quest:5627","npc:priestess-alathea","npc:priestess-josetta","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:2519"},m={start="Priestess Josetta",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5628},src={"Returning Home (Elwynn Forest)"}}
E["quest:5629"] = {t="quest",n="Returning Home",z="darnassus",s="Returning Home marks a rite of passage for young night elf priests serving across Teldrassil. After proving themselves in the wilds, novitiates are summoned to the majestic Temple of the Moon in Darnassus to present themselves before Priestess Alathea and High Priestess Tyrande Whisperwind.",h="Returning Home marks a rite of passage for young night elf priests serving across Teldrassil.",sec={{t="A Summons from Darnassus",b="Priests who spend their early days tending to the wounded and cleansing corruptions around Dolanaar quickly attract the attention of the Sisterhood of Elune. Trainer Laurna Morninglight intercepts promising initiates, explaining that Priestess Alathea has sent word asking for an audience. While aiding the local settlements is essential, every devotee must cultivate their communion with the Moon Mother and answer the higher calling of the faith.",sp=0},{t="Within the Temple of the Moon",b="The path leads beyond the boughs of Teldrassil into the grand heart of Darnassus: the Temple of the Moon. Rising above the city under the gentle glow of Elune's grace, the sanctuary acts as both the supreme house of worship and the spiritual capital of the kaldorei. To be invited back into these halls means one is no longer treated merely as a fledging student, but as an initiate recognized directly by the leadership of the priesthood.",sp=0},{t="The Favor of Tyrande and Alathea",b="When travelers step before Priestess Alathea, the greeting is warm and maternal. Alathea shares the leadership's watchful pride, noting that both she and High Priestess Tyrande Whisperwind rejoice whenever initiates venture into the uncertain outside world and return unharmed. This homecoming signals the start of deeper sacred trials under Alathea's direct mentorship.",sp=0}},faq={{q="Who offers the quest Returning Home?",a="Laurna Morninglight, the priest trainer stationed in Dolanaar within Teldrassil, gives the quest once a young night elf priest reaches sufficient training and experience.",al={"who gives returning home","returning home quest giver","laurna morninglight quest"}},{q="Where is Priestess Alathea located?",a="Priestess Alathea resides within the Temple of the Moon in Darnassus, situated toward the center of the night elven capital city on Teldrassil.",al={"where is alathea","priestess alathea location","temple of the moon priestess"}},{q="Why does Priestess Alathea want to see me?",a="The elders and leadership of the Sisterhood of Elune have noted your dedicated service in the wilderness of Teldrassil. Alathea believes you are ready for advanced instruction and greater spiritual tasks.",al={"why summoned to darnassus","why go to temple of the moon"}},{q="Can any class take this quest?",a="No. Returning Home is specifically tailored for night elf priests as part of their early class development and sacred initiation into the Sisterhood's higher duties.",al={"is returning home for all classes","can druids do returning home","priest only quest"}},{q="What quest follows Returning Home?",a="Upon reporting to Priestess Alathea and concluding this errand, she entrusts you with the follow-up task titled Stars of Elune.",al={"what comes after returning home","returning home followup","next quest"}},{q="What is the Temple of the Moon's significance to night elves?",a="The Temple of the Moon is the primary center of worship for the goddess Elune and serves as the governing house where High Priestess Tyrande Whisperwind guides both the Sisterhood and the kaldorei nation.",al={"temple of the moon lore","darnassus moon temple"}}},ang={["class:Priest"]="This summons reflects a priest's transition from an ordinary forest acolyte into a formal servant of the Sisterhood of Elune answering directly to Darnassus.",["race:NightElf"]="For kaldorei, answering a call to the Temple of the Moon represents communion with their cultural roots and the watchful eyes of High Priestess Tyrande Whisperwind."},kw={"darnassus","dolanaar","elune","laurna morninglight","priestess alathea","returning home","sisterhood of elune","teldrassil","temple of the moon","tyrande"},rel={"npc:laurna-morninglight","npc:priestess-alathea","subzone:temple-of-the-moon","zone:darnassus","quest:5627","topic:elune","quest:2519","quest:92472"},m={start="Laurna Morninglight",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5629},src={"Returning Home (Teldrassil)"}}
E["quest:5630"] = {t="quest",n="Returning Home",z="darnassus",s="Returning Home is a summons for wandering night elf priests operating far from Kalimdor in the snowy crags of Dun Morogh. Directed by the dwarven priest trainer Maxan Anvol, the novice is instructed to return to the Temple of the Moon in Darnassus to report to Priestess Alathea.",h="Returning Home is a summons for wandering night elf priests operating far from Kalimdor in the snowy crags of...",sec={{t="A Summons Across the Sea",b="Night elves who choose to begin their adventures alongside their dwarven allies face the bitter biting cold of Dun Morogh, a far cry from the serene forests of Teldrassil. In Kharanos, the dwarven priest trainer Maxan Anvol takes note of the elf's fortitude before passing along an urgent message: a priestess of Elune passed through seeking them out, carrying orders from Darnassus that require their immediate return.",sp=0},{t="The Temple of the Moon",b="The journey demands a trek back to the sacred boughs of Teldrassil, leading directly to the Temple of the Moon. There, Priestess Alathea welcomes the traveler back into the fold of the Sisterhood of Elune. Relieved to see another devotee return unscathed from foreign lands, Alathea swiftly prepares the priest for their next rites of devotion, beginning with the Stars of Elune.",sp=0}},faq={{q="Who sends me on this quest?",a="Maxan Anvol, the dwarven priest trainer stationed in Kharanos within Dun Morogh, delivers the message to you. He notes that another night elf priestess had recently passed through seeking you out.",al={"quest giver","who starts returning home","maxan anvol"}},{q="Where do I need to go to complete it?",a="You must travel back to Darnassus on the island of Teldrassil in northern Kalimdor. Priestess Alathea awaits you inside the Temple of the Moon.",al={"turn in location","where is priestess alathea","where do i go"}},{q="Why is the Temple of the Moon calling me back?",a="Priestess Alathea and High Priestess Tyrande Whisperwind monitor the development of young initiates. Alathea wishes to verify your safety, hear of your travels under Elune's grace, and initiate your next stage of spiritual training through the Stars of Elune.",al={"why returning home","priest summons reason"}},{q="What happens after speaking with Priestess Alathea?",a="Once you report your return, Priestess Alathea offers the quest Stars of Elune, continuing your foundational rites as a priest of the Kaldorei.",al={"next quest","what comes next"}},{q="Why would a night elf be in Dun Morogh at level 10?",a="Night elf adventurers often journey to the Eastern Kingdoms by boat from Darkshore to Menethil Harbor to explore the lands of the Alliance or adventure alongside dwarf and gnome comrades.",al={"why dun morogh","night elf in ironforge"}},{q="Is this quest available to other races?",a="No, this quest is specifically intended for night elf priests who are training abroad in dwarven lands, directing them back to their cultural and spiritual home in Darnassus.",al={"can dwarves do returning home","who can take this quest"}}},ang={["class:Priest"]="This rite of passage connects wandering acolytes back to the leadership of the Sisterhood of Elune, ensuring that devotion to the Moon Goddess remains steadfast even while traveling across distant lands.",["race:NightElf"]="For a Kaldorei braving the frigid winds of Dun Morogh, the summons offers a welcome return to the familiar sanctuaries and ancestral forests of Teldrassil."},kw={"darnassus","dun morogh","kharanos","maxan anvol","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon"},rel={"npc:maxan-anvol","npc:priestess-alathea","quest:5627","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:5628","quest:2519"},m={start="Maxan Anvol",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5630},src={"Returning Home (Dun Morogh)"}}
E["quest:5631"] = {t="quest",n="Returning Home",z="darnassus",s="Returning Home is an Alliance priest quest that summons promising night elf acolytes who have been traveling abroad back to Teldrassil. Guided by Brother Joshua in human lands, the young priest is recalled to the Temple of the Moon in Darnassus by Priestess Alathea for advanced guidance in the mysteries of Elune.",h="Returning Home is an Alliance priest quest that summons promising night elf acolytes who have been traveling...",sec={{t="A Summons Across Seas",b="While night elf priests occasionally travel to human domains like Stormwind to share spiritual fellowship with the Church of the Holy Light, their deepest ties remain bound to the Sisterhood of Elune. When Brother Joshua informs an acolyte that a night elf emissary has come searching for them, it signals that their early wanderings are done. Their home temple requires their presence for deeper training under the guidance of High Priestess Tyrande Whisperwind's inner circle.",sp=0},{t="The Temple of the Moon",b="Returning across the seas to Darnassus brings the traveler directly to the sanctum of the Temple of the Moon. Priestess Alathea greets the returning acolyte with warmth, celebrating their safe passage through a troubled world. The safe return of their young disciples is a source of joy for both Alathea and Tyrande, but it is also the prologue to more demanding spiritual trials.",sp=0}},faq={{q="Why is Brother Joshua giving instructions to a night elf priest?",a="Brother Joshua serves the Church of the Holy Light in human lands, where young Alliance priests often train alongside one another. A sister of Elune visited his halls specifically to deliver a message recalling you to Darnassus, prompting Joshua to pass along the summons.",al={"why brother joshua","brother joshua night elf","who sends me home"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a senior member of the Sisterhood of Elune stationed within the Temple of the Moon in Darnassus. Working closely with High Priestess Tyrande Whisperwind, she oversees the training and advancement of promising night elf priests.",al={"priestess alathea","alathea darnassus","who is alathea"}},{q="What happens after reaching the Temple of the Moon?",a="Upon reporting your safe arrival to Priestess Alathea, she welcomes you home and initiates you into your next rite of passage, beginning the quest Stars of Elune to deepen your communion with the Moon Goddess.",al={"quest after returning home","what is next","stars of elune quest"}},{q="Can any Alliance race do this quest?",a="This particular summons is meant for night elf priests who have strayed far from Kalimdor during their early training. It ensures they return to their ancestral home to study racial priesthood traditions under the Sisterhood of Elune.",al={"is this night elf only","can humans do returning home","who can pick up returning home"}},{q="Where is the Temple of the Moon located?",a="The Temple of the Moon stands in the southern district of Darnassus atop the boughs of Teldrassil. It serves as both the spiritual heart of night elf culture and the seat of power for High Priestess Tyrande Whisperwind.",al={"temple of the moon location","where is the temple","where is alathea"}},{q="Why does Alathea mention Tyrande Whisperwind?",a="Tyrande Whisperwind is the High Priestess of Elune and the spiritual leader of the night elves. Senior priestesses like Alathea act on her behalf, ensuring that all novices who represent their faith abroad are tracked and instructed according to Tyrande's standards.",al={"why tyrande mentioned","tyrande whisperwind priestess","alathea and tyrande"}}},ang={["class:Priest"]="This quest bridges the fellowship between the Church of the Holy Light and the Sisterhood of Elune, marking the moment a young acolyte returns to their people to master unique Kaldorei rites.",["race:NightElf"]="For night elf priests who walked among humans or dwarves across the sea, this pilgrimage marks a sacred homecoming to the sanctuaries of Teldrassil.",["faction:Alliance"]="The seamless cooperation between Brother Joshua in the Eastern Kingdoms and the priestesses in Darnassus reflects the spiritual diplomacy keeping the Alliance unified."},kw={"brother joshua","darnassus","priest","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon","tyrande"},rel={"quest:5627","npc:priestess-alathea","npc:brother-joshua","subzone:temple-of-the-moon","zone:darnassus","topic:elune","topic:light","quest:2519"},m={start="Brother Joshua",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5631},src={"Returning Home (Brother Joshua)"}}
E["quest:5632"] = {t="quest",n="Returning Home",z="darnassus",s="Returning Home is a summons sent to promising night elf priests serving outside the capital. Priestess Alathea calls initiates back to the Temple of the Moon in Darnassus to recognize their growth in the Sisterhood of Elune and bestow advanced guidance.",h="Returning Home is a summons sent to promising night elf priests serving outside the capital.",sec={{t="A Messenger from the Sisterhood",b="As nascent priests journey abroad in the service of their people, their spiritual growth does not go unnoticed. While visiting Nara Meideros in Stormwind's Park, a messenger from the Sisterhood of Elune arrives bearing urgent word: the order's leaders require the initiate's presence in Darnassus. It serves as both an evaluation and a rite of recognition, marking the transition from a fledgling novitiate into an active servant of the Mother Moon.",sp=0},{t="Audience at the Temple of the Moon",b="The summons directs the traveler straight to Priestess Alathea within Darnassus's crowning sanctuary, the Temple of the Moon. Overseen by High Priestess Tyrande Whisperwind, the Sisterhood keeps close watch over its dispersed members. Returning safely to the temple grounds honors the community and the goddess, demonstrating that Elune's grace has guided and preserved the priest through early trials in the wild.",sp=0}},faq={{q="Why is the priestess summoning me back to Darnassus?",a="Priestess Alathea and the Sisterhood of Elune track the spiritual development of their disciples. You are recalled to the Temple of the Moon because of your rapid progress in the order's ways, leading directly into deeper training and a sacred blessing.",al={"why returning home","reason for summons","why visit alathea"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a high-ranking mentor within the Sisterhood of Elune stationed at the Temple of the Moon. Working directly under High Priestess Tyrande Whisperwind, she trains promising night elf priests and initiates them into sacred rites.",al={"who is alathea","alathea lore","priestess alathea identity"}},{q="Where does this summons lead next?",a="Reporting to Priestess Alathea leads immediately into the trial known as Stars of Elune, an ancient priest quest where you learn to channel the celestial power of the goddess in defense of your people.",al={"what quest is after returning home","next step in returning home","stars of elune lead in"}},{q="Who sends the message through Nara Meideros?",a="A messenger dispatched directly from the Sisterhood of Elune passed word to Nara Meideros. The order keeps lines of communication open with priestesses stationed abroad, such as Nara in Stormwind's Park, to monitor their initiates.",al={"who sent nara","messenger of the sisterhood"}},{q="Do other races or classes receive this summons?",a="No. This quest is tied specifically to the night elf priesthood and the Sisterhood of Elune. Initiates of other races and faiths look to their own distinct spiritual mentors and holy orders for advancement.",al={"can non night elves do this","is this priest only"}},{q="Why does Alathea mention Tyrande Whisperwind?",a="Tyrande Whisperwind is the High Priestess of Elune and the supreme leader of both the Sisterhood and the night elf government. Alathea works directly beneath her within the Temple of the Moon, ensuring Tyrande's will and spiritual guidance reach every initiate.",al={"tyrande connection","tyrande alathea relation"}}},ang={["class:Priest"]="This summons marks an essential milestone in your priesthood, rewarding your early service with direct communion and further discipline under the Sisterhood of Elune.",["race:NightElf"]="For the kaldorei, returning safely to the Temple of the Moon is a profound homecoming, reinforcing the enduring cultural and spiritual leadership of Elune's clergy.",["faction:Alliance"]="The Sisterhood of Elune forms the spiritual heart of the night elves within the Alliance, preparing adept healers and divine warriors to face threats across Kalimdor."},kw={"darnassus","nara meideros","priest quest","priestess alathea","returning home","sisterhood of elune","stars of elune","temple of the moon","tyrande whisperwind"},rel={"quest:5627","npc:priestess-alathea","npc:nara-meideros","subzone:temple-of-the-moon","zone:darnassus","topic:elune","quest:2519","quest:5628"},m={start="Nara Meideros",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5632},src={"Returning Home (Nara Meideros)"}}
E["quest:5633"] = {t="quest",n="Returning Home",z="darnassus",s="Returning Home is a summons for night elf priests traveling abroad in Ironforge to return to the Temple of the Moon in Darnassus. An emissary of the Sisterhood sought out wandering acolytes, directing them back to Priestess Alathea for urgent training and spiritual duties.",h="Returning Home is a summons for night elf priests traveling abroad in Ironforge to return to the Temple of...",sec={{t="Summoned from the Mountain City",b="Even while wandering far from Teldrassil in the bustling subterranean halls of Ironforge, night elf priests remain bound to the Sisterhood of Elune. Braenna Flintcrag, a dwarven priest trainer in the Mystic Ward, passes along a message left by a visiting night elf priestess. The messenger came seeking young disciples abroad, carrying word that their mentors require their presence immediately back in the capital.",sp=0},{t="The Temple of the Moon",b="Upon arriving at the Temple of the Moon in Darnassus, returning acolytes report directly to Priestess Alathea. Welcoming her student back under the watchful gaze of High Priestess Tyrande Whisperwind, Alathea expresses relief at their safe journey across the seas. The urgent summons serves as the threshold to deeper devotion, opening the way for sacred duties such as the Stars of Elune.",sp=0}},faq={{q="Who starts this quest?",a="The quest is given by Braenna Flintcrag, the dwarf priest trainer found in the Mystic Ward of Ironforge.",al={"who gives returning home","quest giver returning home","braenna flintcrag location"}},{q="Who do I report to in Darnassus?",a="You must speak with Priestess Alathea, who resides inside the Temple of the Moon in Darnassus.",al={"where to turn in returning home","priestess alathea location","turn in returning home"}},{q="Why is the Sisterhood calling priests back?",a="The Sisterhood of Elune keeps close watch on its initiates. Once an acolyte has proven their capabilities abroad, the leadership in Darnassus recalls them to undertake advanced training and sacred rites like the Stars of Elune.",al={"why returning home","why go back to darnassus"}},{q="Is this quest available to other classes?",a="No, this quest is specifically intended for night elf priests who have journeyed to Dun Morogh and Ironforge early in their adventures.",al={"can warriors do returning home","priest only quest"}},{q="What happens after turning in this quest?",a="Priestess Alathea welcomes you back to Darnassus and offers the follow-up quest Stars of Elune, which delves deeper into the goddess's teachings.",al={"returning home next quest","followup to returning home"}},{q="How does Braenna know to look for you?",a="A priestess sent directly from the Temple of the Moon passed through Ironforge looking for acolytes, leaving explicit instructions with local trainers like Braenna to redirect any wandering night elves home.",al={"why does braenna know me","ironforge priestess message"}}},ang={["class:Priest"]="This quest bridges your early travels among Alliance allies back to the core spiritual home of the night elf priesthood at the Temple of the Moon.",["race:NightElf"]="Leaving Kalimdor for the Eastern Kingdoms is a rare journey for a young kaldorei, but the guidance of Elune and Tyrande's priesthood reaches across the Great Sea.",["faction:Alliance"]="Cooperation between dwarven clerics in Ironforge and the Sisterhood of Elune in Darnassus shows how Alliance factions coordinate to support wandering adventurers."},kw={"braenna flintcrag","darnassus","priest quest","priestess alathea","returning home","stars of elune","temple of the moon"},rel={"npc:priestess-alathea","npc:braenna-flintcrag","subzone:temple-of-the-moon","quest:5627","quest:5628","zone:darnassus","topic:elune","quest:2519"},m={start="Braenna Flintcrag",["end"]="Priestess Alathea",level="10",faction="Alliance",id=5633},src={"Returning Home (Ironforge)"}}
E["quest:5640"] = {t="quest",n="Desperate Prayer",z="darnassus",s="Desperate Prayer is a quest given to young human and dwarven priests visiting Darnassus, directing them back to their own spiritual traditions in Stormwind. Priestess Alathea recognizes that while night elves draw strength from Elune, followers of the Holy Light must seek out mentors of their own faith. Completing this journey returns the acolyte to High Priestess Laurena in the Cathedral of Light.",h="Desperate Prayer is a quest given to young human and dwarven priests visiting Darnassus, directing them back...",sec={{t="Two Paths of Faith",b="Priests walking the paths of the Alliance draw upon fundamentally different sacred sources. Within Darnassus, the Priesthood of Elune tends to the moon goddess, channeling her gentle radiance and celestial wrath. When human and dwarven acolytes travel beneath Teldrassil's boughs, mentors like Priestess Alathea politely recognize the divide: while she honors Elune and respects the Holy Light, she cannot instruct another race in the deeper prayers tied to an entirely different devotion.",sp=0},{t="Return to the Cathedral",b="To master abilities born of absolute faith—such as calling forth emergency divine intervention in one's darkest hour—initiates of the Holy Light are told to journey back home. High Priestess Laurena presides over training within the soaring marble arches of Stormwind's Cathedral of Light, ready to guide returning priests into the deeper rites of their calling.",sp=0}},faq={{q="Why does a Darnassus priest send me to Stormwind?",a="Priestess Alathea teaches the ways of the moon goddess Elune. Because humans and dwarves draw their faith and miracles from the Holy Light, Alathea politely directs them to mentors of their own tradition, such as High Priestess Laurena in Stormwind.",al={"why go to stormwind","why alathea sends me away","darnassus to stormwind priest quest"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a night elf priestess stationed at the Temple of the Moon in Darnassus. She mentors aspiring followers of Elune and offers respectful guidance to foreign priests visiting the world tree.",al={"alathea lore","who is alathea"}},{q="Who is High Priestess Laurena?",a="High Priestess Laurena is a human spiritual leader stationed inside the Cathedral of Light in Stormwind. She serves as an instructor for promising servants of the Holy Light, helping them master advanced prayers and solemn responsibilities.",al={"who is laurena","high priestess laurena stormwind"}},{q="What is Desperate Prayer in the lore?",a="Desperate Prayer represents an instantaneous call for divine aid when a priest is near death or in mortal peril. It is a signature invocation granted to faithful servants of the Holy Light who need immediate restoration.",al={"what is desperate prayer","desperate prayer ability lore"}},{q="Can night elves teach the Holy Light?",a="No. The night elves revere Elune almost exclusively and channel her lunar power. While they treat the Holy Light with diplomatic respect, they do not preach it or teach its specific prayers, leaving that to the human and dwarven priesthoods.",al={"do night elves know the light","elune vs holy light"}},{q="Where can I find High Priestess Laurena?",a="High Priestess Laurena resides in the Cathedral Square of Stormwind City, standing inside the Cathedral of Light among fellow clergy and paladins of the Silver Hand.",al={"laurena location","where is laurena"}}},ang={["class:Priest"]="This quest highlights how holy magic in the Alliance is split between the worship of Elune and devotion to the Holy Light, directing young acolytes back to their proper mentors.",["race:Human"]="Human priests far from home are reminded that their true spiritual home and training await within the Cathedral of Light in Stormwind.",["race:Dwarf"]="Dwarven priests who revere the Holy Light share close ties with Stormwind's cathedral and learn their high-tier invocations alongside their human brethren.",["race:NightElf"]="Night elf sisters of Elune acknowledge the power of foreign faiths with polite deference, but maintain strict devotion to the Mother Moon alone."},kw={"alathea","cathedral of light","darnassus","desperate prayer","elune","holy light","laurena","stormwind"},rel={"npc:priestess-alathea","npc:high-priestess-laurena","topic:light","topic:elune","zone:darnassus","topic:stormwind-kingdom"},m={start="Priestess Alathea",["end"]="High Priestess Laurena",level="10",faction="Alliance",id=5640},src={"Desperate Prayer (Darnassus)"}}
E["quest:5672"] = {t="quest",n="Elune's Grace",z="darnassus",s="Elune's Grace is a rite of recognition offered to devout night elf priests in Darnassus. Upon proving their faith and discipline through their early journeys, priests are called before Priestess Alathea to receive deeper instruction in the divine mysteries of the Moon Goddess.",h="Elune's Grace is a rite of recognition offered to devout night elf priests in Darnassus.",sec={{t="A Sacred Calling",b="Within the Temple of the Moon in Darnassus, the Sisterhood of Elune guides young acolytes from their first prayers to mastery of lunar magic. Night elves do not look upon the Holy Light in the same manner as humans or dwarves; their faith is inextricably tied to the Mother Moon, Elune. When a novice priest reaches a significant milestone in their devotion, senior mentors take notice, marking the disciple as ready to shoulder greater divine power.",sp=0},{t="Blessings of the Moon Goddess",b="Priestess Alathea extends this summons on behalf of the Sisterhood. She acknowledges that the acolyte's dedication has elevated them beyond the common flock, granting them access to traditions preserved across millennia. Accepting the rite seals the priest's bond to Elune, unlocking specific protective wards and lunar invocations unique to the kaldorei faith.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest represents a spiritual benchmark for night elf priests. It summons an acolyte back to Darnassus so Priestess Alathea can acknowledge their growth and initiate them into higher racial teachings granted by the Sisterhood of Elune.",al={"why do elunes grace","what does elunes grace do","purpose of quest"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a respected trainer of the Sisterhood of Elune based in Darnassus. She watches over developing kaldorei priests, helping them deepen their communion with the Moon Goddess.",al={"alathea role","who gives quest","who is alathea"}},{q="Why is this gift specific to night elves?",a="Unlike human or dwarven priests who draw upon the Holy Light, night elf priests venerate Elune directly. The sisterhood's invocations—such as Elune's Grace—reflect the lunar protection and defensive enchantments cultivated by the kaldorei over thousands of years.",al={"why only night elves","racial ability lore","elune priest difference"}},{q="Where does this ceremony take place?",a="The summons is answered in Darnassus, centered within the Temple of the Moon where the city's priesthood gathers and teaches.",al={"where is alathea","quest location","darnassus temple"}},{q="Do other Alliance priests receive a similar calling?",a="Yes. Each culture approaches the priesthood differently: humans and dwarves study the tenets of the Holy Light under their own mentors in Stormwind and Ironforge, earning racial disciplines distinct from the moon magic practiced by the night elves.",al={"do humans get this","dwarf priest equivalent","other races"}},{q="What state of devotion is Alathea referring to?",a="Alathea refers to the spiritual fortitude and maturity gained through trials in the wider world. Survival, discipline, and steadfast adherence to Elune's virtues prove that an acolyte can channel more potent lunar blessings safely.",al={"attained a state","alathea dialogue","what devotion"}}},ang={["class:Priest"]="This rite marks the divergence between kaldorei faith and the Light-based doctrines of human and dwarven clergies, grounding the priest's craft firmly in Elune's protective embrace.",["race:NightElf"]="For the kaldorei, Elune's Grace represents unbroken continuity with ancient traditions preserved within the Sisterhood of Elune."},kw={"alathea","darnassus","elune","elune's grace","priest quest","priestess alathea","sisterhood of elune","temple of the moon"},rel={"npc:priestess-alathea","topic:elune","zone:darnassus","topic:night-elf"},m={start="Priestess Alathea",level="20",faction="Alliance",id=5672},src={"Elune's Grace (Darnassus)"}}
E["quest:5674"] = {t="quest",n="Elune's Grace",z="darnassus",s="Elune's Grace is a rite of advancement for developing night elf priests, marking their readiness to wield divine talents unique to their people. Guided from local outposts like Dolanaar back to the sacred Temple of the Moon in Darnassus, candidates present themselves before Priestess Alathea to prove their devotion.",h="Elune's Grace is a rite of advancement for developing night elf priests, marking their readiness to wield...",sec={{t="A Sacred Milestone",b="Within the Sisterhood of Elune, a priest's journey involves more than simply mastering standard prayers of mending and smiting. As acolytes grow in experience, they reach a threshold where they are deemed ready to receive blessings granted exclusively to the kaldorei. Local mentors such as Laurna Morninglight in Dolanaar lack the authority to bestow these deeper arts, directing promising disciples back to the cultural and spiritual heart of their order.",sp=0},{t="Audience at the Temple",b="The quest directs initiates across Teldrassil to the grand Temple of the Moon in Darnassus. There, beneath the gaze of the high priesthood, Priestess Alathea evaluates whether the petitioner is truly prepared to bear the goddess's defensive mantle. Learning Elune's Grace symbolizes reaching true maturity within the priesthood, bridging the gap between raw potential and formal service to the goddess.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest sends night elf priests who have gained enough practical experience back to Darnassus. It serves as a rite of passage, directing them to Priestess Alathea at the Temple of the Moon to be tested and taught the defensive art known as Elune's Grace.",al={"what does this quest do","elunes grace quest purpose","why visit alathea"}},{q="Who is Priestess Alathea?",a="Priestess Alathea is a high-ranking priest trainer residing within the Temple of the Moon in Darnassus. She oversees the formal training and advancement of night elf acolytes, ensuring they possess the spiritual focus required to handle advanced racial prayers.",al={"priestess alathea lore","who is alathea","alathea darnassus"}},{q="Why can't local mentors teach this ability?",a="Outpost trainers like Laurna Morninglight guide novices through foundational teachings, but the sisterhood reserves sacred, kaldorei-specific blessings for formal conferral. Acolytes must present themselves at the order's central seat of devotion in Darnassus to undergo evaluation before learning these deeper gifts.",al={"why not train in dolanaar","why go to darnassus"}},{q="What does Elune's Grace actually represent in kaldorei faith?",a="Elune's Grace represents the direct protective guardianship of the Moon Goddess. Woven through prayer, it diminishes the impact of incoming attacks, reflecting Elune's shielding presence over her faithful champions when danger draws close.",al={"what is elunes grace","elunes grace lore"}},{q="Can priests of other races receive this blessing?",a="No. The art of Elune's Grace is tied strictly to the ancestral faith and worship of the kaldorei. Only night elf priests who commune directly with the Moon Goddess are instructed in its invocation.",al={"can humans learn elunes grace","is elunes grace night elf only"}},{q="Where does this journey begin and end?",a="The summons is delivered by mentor Laurna Morninglight in the settlement of Dolanaar on Teldrassil, sending the acolyte west to the Temple of the Moon nestled in Darnassus.",al={"quest start and end","where to go"}}},ang={["class:Priest"]="This rite marks a defining transition for night elf priests, grounding their identity in the distinct celestial magic of the Sisterhood of Elune rather than universal holy practices.",["race:NightElf"]="The pilgrimage to the Temple of the Moon reinforces the central role Elune's worship plays in kaldorei society, summoning distant acolytes home to the heart of Darnassus."},kw={"darnassus","dolanaar","elune's grace","laurna morninglight","priestess alathea","sisterhood of elune","teldrassil","temple of the moon"},rel={"npc:priestess-alathea","npc:laurna-morninglight","subzone:temple-of-the-moon","quest:5672","quest:2519","topic:elune","topic:night-elf","zone:darnassus"},m={start="Laurna Morninglight",["end"]="Priestess Alathea",level="20",faction="Alliance",id=5674},src={"Elune's Grace (Dolanaar)"}}
E["quest:5678"] = {t="quest",n="Arcane Feedback",z="darnassus",s="\"Arcane Feedback\" is an Alliance priest quest that directs human priests training in Darnassus back home to Stormwind. Sent by Priestess Alathea at the Temple of the Moon, the journey highlights the deep cultural rift regarding magic between the night elves and the Eastern Kingdoms. Upon returning to the Cathedral of Light, High Priestess Laurena prepares the acolyte for deeper theological instruction.",h="\"Arcane Feedback\" is an Alliance priest quest that directs human priests training in Darnassus back home to...",sec={{t="A Reluctant Summons",b="Priestess Alathea oversees visiting priests within the tranquil halls of the Temple of the Moon in Darnassus. While she recognizes the formal alliance between the kaldorei and the humans of Stormwind, she harbors deep misgivings about human magical and spiritual practices. Night elf society views arcane power as inherently volatile and dangerous, shaped by ten millennia of grief following the War of the Ancients. Even divine rites from humanity that blur the lines between radiant faith and arcane mechanics make night elf clergy distinctly uneasy.",sp=0},{t="Return to the Cathedral",b="Despite her hesitation, Alathea honors the bond between the Alliance races and releases the visiting acolyte to answer a recall from the Cathedral of Light. High Priestess Laurena has sent couriers across the seas to gather growing human priests for advanced training. Stepping back into Stormwind, the acolyte leaves behind the moonlit groves of Elune to embrace the grand stone sanctuaries and golden radiance of the Holy Light.",sp=0}},faq={{q="Why does Priestess Alathea want me to leave Darnassus?",a="Priestess Alathea is acting on summons sent by your superiors in Stormwind, but she is also uncomfortable with human theological practices. She openly admits her deep-seated distrust of arcane magic, whether divinely influenced or not, making her eager to send human acolytes back to their own grand cathedrals.",al={"why alathea sends me away","why return to stormwind","alathea arcane feedback"}},{q="Why do night elves distrust human priestly magic?",a="Night elf culture is fundamentally defined by the catastrophic Sundering, which was caused by reckless arcane spellcraft ten thousand years ago. Kaldorei worship centers on Elune, and their priestesses view any tradition that borders on or incorporates arcane manipulation with profound suspicion, even if practiced by allies in the Holy Light.",al={"why night elves hate arcane","night elf arcane distrust","elune vs holy light"}},{q="Who is High Priestess Laurena?",a="High Priestess Laurena is a prominent spiritual leader within the Cathedral of Light in Stormwind City. She oversees the training and advancement of emerging human priests, guiding their understanding of the Holy Light as their power grows.",al={"who is laurena","high priestess laurena stormwind"}},{q="What does this quest lead into?",a="Reporting to High Priestess Laurena marks your transition into higher-level human priestly instruction in Stormwind, unlocking the discipline and blessings unique to human adherents of the Holy Light.",al={"what comes after arcane feedback","arcane feedback reward lore"}}},ang={["class:Priest"]="This pilgrimage marks a crucial threshold in your spiritual path, serving as a reminder of the sharp philosophical divide between Elune's sisterhood and the dogmas of the Holy Light.",["race:Human"]="Returning to Stormwind brings you home to the heart of the Church of the Holy Light, leaving behind the cloistered and skeptical kaldorei priesthood.",["race:NightElf"]="Priestess Alathea's candid wariness illustrates the ever-present kaldorei fear that arcane tampering by the younger mortal races could lead to renewed disaster."},kw={"arcane feedback","cathedral of light","darnassus","high priestess laurena","holy light","priest quest","priestess alathea","stormwind"},rel={"npc:priestess-alathea","npc:high-priestess-laurena","subzone:cathedral-of-light","topic:stormwind-kingdom","topic:light"},m={start="Priestess Alathea",["end"]="High Priestess Laurena",level="20",faction="Alliance",id=5678},src={"Arcane Feedback (Darnassus)"}}
E["quest:5921"] = {t="quest",n="Moonglade",z="darnassus",s="Moonglade is an introductory rite of passage for young night elf druids learning to commune with the sacred lands of Kalimdor. Guided by Mathrengyl Bearwalker in Darnassus, novices learn the spell to magically transport themselves across the world into Moonglade to meet Dendrite Starblaze in Nighthaven. This marks the beginning of their spiritual journey toward mastering the strength of the bear form.",h="Moonglade is an introductory rite of passage for young night elf druids learning to commune with the sacred...",sec={{t="A Sacred Refuge",b="Moonglade stands apart from the rest of Azeroth as an ancient sanctuary dedicated to the teachings of Cenarius. Under the watchful stewardship of Keeper Remulos, its tranquil groves provide peace and deep communion with nature. For a young druid, learning to project one's spirit across the land into Moonglade via the teleportation spell is a critical step, granting constant access to the heart of druidic wisdom regardless of mortal distances.",sp=0},{t="Politics of the Circle",b="While Moonglade is open to all who walk the path of the wild, it is not free of tension. A growing rift divides Arch Druid Fandral Staghelm in Darnassus and Keeper Remulos in Moonglade over the stewardship of nature and the creation of Teldrassil. Despite these philosophical fractures within the Cenarion Circle, young acolytes are still welcomed unconditionally into the haven of Nighthaven to pursue their sacred studies.",sp=0},{t="The Path of the Bear",b="Arriving in Nighthaven brings the novice before Dendrite Starblaze, an elder tasked with guiding fledglings along the ways of the Claw. Before any initiate can claim the mantle of the bear, they must be immersed in its perspective: endurance, fury, and unyielding defense of the wild. Starblaze receives each new student with reverent deference to Father Cenarius, commencing the trials of the Great Bear Spirit.",sp=0}},faq={{q="Why do druids learn to teleport to Moonglade?",a="Teleporting to Moonglade connects a druid directly to the heart of their order. Because training, communion with spirits, and high-level council take place in Nighthaven, having an instantaneous spiritual conduit ensures every practitioner can return to study and replenish their spiritual energies.",al={"why teleport moonglade","teleport moonglade purpose","why go to moonglade"}},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid stationed on the upper floor of a major lodge in Nighthaven. He oversees initiates arriving in Moonglade, initiating their trials to master animal perspectives—starting with the primal spirit of the bear.",al={"dendrite starblaze role","who is dendrite","dendrite starblaze"}},{q="What tensions exist between Fandral Staghelm and Keeper Remulos?",a="Arch Druid Fandral Staghelm led the planting of Teldrassil without the blessing of the Dragon Aspects, pursuing a more aggressive, nationalistic posture for the night elves. Keeper Remulos and traditionalists in Moonglade remain dedicated to the ancient, neutral ways of Cenarius, creating ideological friction within the Cenarion Circle.",al={"staghelm remulos tension","fandral vs remulos","circle division"}},{q="Can Horde druids visit Moonglade as well?",a="Yes. Moonglade is a neutral haven protected by Keeper Remulos and the Cenarion Circle. Both night elf and tauren druids are welcome in Nighthaven to study the wild ways together, setting aside factional hostility while under the peace of Cenarius.",al={"horde moonglade","are tauren allowed in moonglade","is moonglade neutral"}},{q="What happens after reaching Dendrite Starblaze?",a="Once you report to Dendrite Starblaze, he guides you into the ritual trial of the Great Bear Spirit. This spiritual confrontation tests your resolve and understanding before you are permitted to harness the raw power of the bear.",al={"after moonglade quest","next step bear form","bear quest next"}},{q="Where in Nighthaven is Dendrite located?",a="Dendrite Starblaze is located inside the main night elf lodge near the center of Nighthaven, standing watch on the second floor balcony overlooking the village.",al={"find dendrite starblaze","dendrite starblaze location","where is dendrite"}}},ang={["class:Druid"]="This journey represents your awakening to global druidic heritage, giving you an eternal lifeline to the tranquil heart of the Cenarion Circle.",["race:NightElf"]="Leaving Teldrassil's boughs for ancient Moonglade connects young kaldorei directly with the ancestral homeland preserved before the Great Sundering.",["faction:Alliance"]="While Darnassus champions the Alliance, stepping into Moonglade reminds night elf druids of an older, higher calling that transcends worldly factions."},kw={"bear","cenarion","dendrite","mathrengyl","moonglade","nighthaven","remulos","starblaze","teleport"},rel={"npc:dendrite-starblaze","subzone:nighthaven","npc:remulos","topic:cenarion-circle","topic:druid","topic:cenarius"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="10",faction="Alliance",id=5921},src={"Moonglade (Alliance)"}}
E["quest:5923"] = {t="quest",n="Heeding the Call",z="darnassus",s="Heeding the Call marks the moment an apprentice night elf druid catches the attention of the Cenarion Circle's senior leadership. Summoned to Darnassus to meet Mathrengyl Bearwalker, the young initiate begins the sacred path toward mastering their first animal aspect, the bear.",h="Heeding the Call marks the moment an apprentice night elf druid catches the attention of the Cenarion...",sec={{t="A Summons from the Enclave",b="Novice druids honing their craft across Teldrassil—or studying abroad in far-off realms like Stormwind—eventually receive a personal summons. Instructors such as Kal in Dolanaar, Denatharion in Shadowglen, or Theridran across the Great Sea carry word that Mathrengyl Bearwalker wishes to oversee their training personally. As the direct assistant to Arch Druid Fandral Staghelm, Mathrengyl is one of the most respected and knowledgeable mentors among the night elves, and his attention is an unmistakable sign that an apprentice is ready for genuine trials.",sp=0},{t="The Path of the Bear",b="Reaching Mathrengyl on the upper level of Fandral Staghelm's towering residence in the Cenarion Enclave opens the door to deeper mysteries. To serve nature properly, a druid must learn to embody its living creatures rather than merely observing them. Mathrengyl welcomes candidates with the news that their first great undertaking will be embracing the strength, endurance, and spirit of the bear—a journey that will take them far beyond Teldrassil to sacred ancestral grounds.",sp=0}},faq={{q="Who sends me on this quest?",a="You can receive this summons from several druid trainers once you have reached sufficient experience: Kal in Dolanaar, Denatharion in Shadowglen, or Theridran in the Park district of Stormwind City.",al={"quest giver","who starts this","where do i get this quest"}},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a senior night elf druid and the direct assistant to Arch Druid Fandral Staghelm. He resides in the Cenarion Enclave of Darnassus and serves as a premier instructor for initiates seeking to master animal forms.",al={"mathrengyl","who is mathrengyl","bearwalker"}},{q="Where can I find Mathrengyl Bearwalker in Darnassus?",a="He is located in the Cenarion Enclave, in the northwest quarter of Darnassus. You will find him waiting on the second floor of the large living tree that serves as Arch Druid Fandral Staghelm's sanctuary.",al={"mathrengyl location","where is mathrengyl","cenarion enclave location"}},{q="What training does this quest lead to?",a="Reporting to Mathrengyl begins the sacred trial of the Bear Form. He will direct you across Kalimdor to the sacred haven of Moonglade to learn the strengths of body and heart required to commune with the Great Bear Spirit.",al={"what comes next","what do i get","next quest"}},{q="Why can I get this quest in Stormwind?",a="Night elf emissaries and druids, such as Theridran, maintain a sanctuary in the Park of Stormwind to assist Alliance allies. If a young druid is adventuring across the sea in Elwynn Forest, Theridran can relay the summons back home to Teldrassil.",al={"stormwind quest","theridran","can i get this in stormwind"}},{q="Why is the bear form the first animal aspect taught?",a="Druids hold that nature requires both guardians and caretakers. The bear represents raw resilience, physical power, and the courage to shield the balance from harm, making it the foundational aspect for surviving dangerous wilderness trials.",al={"why bear form","druid bear lore"}}},ang={["class:Druid"]="This quest represents your formal transition from a mere novice weaving root and wrath spells into a true shapeshifter learning the spirits of Kalimdor.",["race:NightElf"]="Heeding the summons calls you into the heart of Darnassus's Cenarion Enclave, honoring millennia of Kaldorei tradition under the watchful eye of Fandral Staghelm's circle.",["faction:Alliance"]="The ability to pick up this quest from Theridran in Stormwind shows the growing coordination between the kaldorei of Teldrassil and their eastern human allies."},kw={"bear form","cenarion enclave","darnassus","denatharion","druid quest","fandral staghelm","heeding the call","kal","mathrengyl bearwalker","theridran"},rel={"npc:mathrengyl-bearwalker","subzone:cenarion-enclave","zone:darnassus","topic:druid","npc:fandral-staghelm","subzone:dolanaar","zone:elwynn","topic:cenarius"},m={start="DenatharionKalTheridran",["end"]="Mathrengyl Bearwalker",level="10",faction="Alliance",id=5923},src={"Heeding the Call (Alliance)"}}
E["quest:5931"] = {t="quest",n="Back to Darnassus",z="darnassus",s="This quest marks the return of a novice night elf druid from the sacred groves of Moonglade to Darnassus. Having communed with the Great Bear Spirit, the initiate reports back to Mathrengyl Bearwalker in the Cenarion Enclave to begin practical shapeshifting trials.",h="This quest marks the return of a novice night elf druid from the sacred groves of Moonglade to Darnassus.",sec={{t="A Journey Between Sanctuaries",b="After communing with the Great Bear Spirit in Moonglade, a young druid must bridge the divide between timeless nature sanctuaries and the unsettled world. Dendrite Starblaze sends the initiate back from Nighthaven to Darnassus, entrusting the next phase of training to the local mentors watching over Teldrassil.",sp=0},{t="The Path of the Claw",b="Mathrengyl Bearwalker awaits in the Cenarion Enclave, guarding nature even in places where the balance falters. Receiving the blessing of the Great Bear Spirit is merely the first step; Mathrengyl prepares the initiate to anchor that fierce ancestral wisdom into physical form through demanding trials of body and heart.",sp=0}},faq={{q="Why do I need to return to Darnassus?",a="Moonglade provides the spiritual communion with the Great Bear Spirit, but your direct mentor, Mathrengyl Bearwalker, resides in the Cenarion Enclave of Darnassus. He guides the practical tests required to master your newly granted power.",al={"why return to darnassus","why leave moonglade","where does dendrite send me"}},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a seasoned night elf druid trainer stationed in Darnassus's Cenarion Enclave. He specializes in guiding young initiates through the Way of the Claw and mastering bear form.",al={"who is mathrengyl","mathrengyl bearwalker lore","bearwalker"}},{q="How do I get back to Darnassus from Moonglade?",a="The hippogryph master Silva Fil'naveth, located in southwestern Nighthaven, provides initiates with direct flights back across the sea to Darnassus.",al={"how to leave nighthaven","moonglade flight back","silva fil'naveth"}},{q="What happens after I speak to Mathrengyl?",a="Mathrengyl will assign your first true test of purpose, tasking you to face Lunaclaw at the Moonkin Stone east of Auberdine in Darkshore to prove your body and heart are ready to wield the bear form.",al={"next quest after back to darnassus","what comes next"}},{q="What is the Path of the Claw?",a="The Path of the Claw is the druidic tradition focused on channeling the ferocity, resilience, and strength of the bear, embodied through communion with ancient primal spirits.",al={"path of the claw","druid claw lore"}},{q="Why does Dendrite mention balance faltering near Darnassus?",a="Teldrassil is young and unblessed by the Dragon Aspects, leaving its boughs vulnerable to strange corruptions, furbolg madness, and encroaching darkness that druids in the Cenarion Enclave actively combat.",al={"balance faltered darnassus","teldrassil corrupted"}}},ang={["class:Druid"]="This journey represents a crucial rite of passage for young druids, marking the transition from theoretical spiritual communion to physical shapeshifting.",["race:NightElf"]="Traveling between the ancient sanctuary of Moonglade and the newly planted World Tree of Teldrassil reflects the balance between millenia of kaldorei heritage and their present duties."},kw={"bear spirit","bearwalker","cenarion enclave","darnassus","dendrite","mathrengyl","moonglade","shapeshifting","starblaze"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","subzone:nighthaven","zone:darnassus","topic:druid"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="10",faction="Alliance",id=5931},src={"Back to Darnassus"}}
E["quest:6001"] = {t="quest",n="Body and Heart",z="darnassus",s="Body and Heart is the culminating trial in a young night elf druid's initiation into the path of the claw. Instructed by Mathrengyl Bearwalker in Darnassus, an initiate must travel into the darkshore wilderness, summon the moonkin guardian Lunaclaw, and prove they possess both inner resilience and martial strength before claiming the form of the bear.",h="Body and Heart is the culminating trial in a young night elf druid's initiation into the path of the claw.",sec={{t="The Trial of Lunaclaw",b="Night elf druid initiates are directed by Mathrengyl Bearwalker in Darnassus to venture east of the coastal settlement of Auberdine. There, tucked inside a natural cavern inhabited by wild moonkin, sits an ancient Moonkin Stone. By anointing this sacred monolith with Cenarion Moondust, the initiate rouses Lunaclaw, the ancient defender of the stone, who will challenge any claimant wishing to inherit the sacred strength of the claw.",sp=0},{t="Strength of Body and Heart",b="Taking on the mantle of the bear requires far more than brute force. While the Great Bear Spirit imparts the foundational teachings of nature's ferocity, the trial against Lunaclaw tests whether an initiate possesses the fortitude of heart necessary to tame and harness that primal power. By overcoming the guardian in combat and heeding the spirit's lingering wisdom, the druid proves ready to wield the bear form without losing themselves to beastly instinct.",sp=1}},faq={{q="Who is Lunaclaw?",a="Lunaclaw is a fierce moonkin spirit guardian dwelling in a cavern directly east of Auberdine in Darkshore. It defends the sacred Moonkin Stone and answers the call of initiates who sprinkle Cenarion Moondust upon the relic.",al={"what is lunaclaw","lunaclaw lore","moonkin boss auberdine"}},{q="What is the purpose of this trial?",a="This rite of passage is the final test for a night elf initiate seeking to join the ranks of the Druids of the Claw. Conquering Lunaclaw demonstrates that the initiate possesses the balance of physical resilience and mental composure required to take on the spirit and shape of the bear.",al={"why do body and heart","what does this quest do","bear form quest lore"}},{q="Who gives this quest?",a="Mathrengyl Bearwalker, an elder druid trainer located in the Cenarion Enclave within Darnassus, tasks initiates with this trial once they have commune with the Great Bear Spirit.",al={"quest giver body and heart","who gives bear form quest"}},{q="What is Cenarion Moondust?",a="Cenarion Moondust is a consecrated ritual powder given to initiates by their elders. When cast upon the Moonkin Stone, its magical properties awaken Lunaclaw and initiate the ritual combat.",al={"what is moondust","cenarion moondust lore"}},{q="Where does this trial take place?",a="The trial takes place in a cavern east of Auberdine in Darkshore, where wild moonkin nest around an ancient carved Moonkin Stone.",al={"where is moonkin stone","moonkin cave auberdine"}},{q="What happens after Lunaclaw is defeated?",a="Upon defeating the creature, the Spirit of Lunaclaw manifests above its physical shell to bestow its blessing and acknowledge the druid's dual strength of heart and body before they return to Darnassus.",al={"what happens after killing lunaclaw","spirit of lunaclaw"},sp=1}},ang={["class:Druid"]="This rite represents the defining threshold of early druidic training, transforming a novice spellcaster into a shapeshifting protector capable of assuming the mighty bear form.",["race:NightElf"]="For the night elves, communing with ancient beast spirits and honoring sacred stones in Darkshore renews ties to Cenarion customs established millennia ago."},kw={"auberdine","bear form","body and heart","cenarion moondust","druid of the claw","lunaclaw","mathrengyl bearwalker","moonkin stone"},rel={"npc:mathrengyl-bearwalker","quest:5931","quest:2561","subzone:auberdine","zone:darnassus","topic:druid"},m={start="Mathrengyl Bearwalker",level="10",faction="Alliance",id=6001},src={"Body and Heart (Alliance)"}}
E["quest:6121"] = {t="quest",n="Lessons Anew",z="darnassus",s="\"Lessons Anew\" is an initiation quest given to developing Alliance druids by Mathrengyl Bearwalker in Darnassus. It directs initiates to travel to the sacred haven of Moonglade to meet with Dendrite Starblaze and begin their training in the art of purging venom and toxins.",h="\"Lessons Anew\" is an initiation quest given to developing Alliance druids by Mathrengyl Bearwalker in...",sec={{t="A Gift from Cenarius",b="Druids hold a sacred connection to the living world, inherited through the teachings and blessings of the demigod Cenarius. Among these boons is the power to cleanse foul venoms through simple incantation. However, such potent gifts are never bestowed lightly upon initiates. To truly respect the miraculous ease of their magical arts, young druids must first understand the painstaking mundane toil required to fight toxins without nature's direct intervention.",sp=0},{t="Summons to Nighthaven",b="Mathrengyl Bearwalker, the druid trainer residing in the Cenarion Enclave of Darnassus, instructs his student to bypass local practice and journey directly to Moonglade. There in the quiet village of Nighthaven, Dendrite Starblaze coordinates the Cenarion Circle's broader efforts and stands ready to assign the novitiate an urgent, practical task.",sp=0},{t="A Real-World Crisis",b="Upon arriving in Nighthaven, initiates learn that their trial will not be an orchestrated test or a scripted ritual. The settlement of Auberdine on the Darkshore coast is facing a severe rash of animal poisonings that the locals are powerless to arrest. Dendrite Starblaze tasks the novitiate with investigating and aiding Darkshore, thrusting them directly into a real crisis where lives hang in the balance.",sp=1}},faq={{q="Who offers the quest Lessons Anew?",a="The quest is offered by Mathrengyl Bearwalker, the night elf druid trainer located in the Cenarion Enclave in Darnassus.",al={"who gives lessons anew","lessons anew quest giver","mathrengyl bearwalker quest"}},{q="Where do I need to go to complete this quest?",a="You must travel to the sacred druidic realm of Moonglade and report to Dendrite Starblaze, who is located in the peaceful settlement of Nighthaven.",al={"where do i go","where is dendrite starblaze","lessons anew turn in"}},{q="Why must druids learn to cure poisons like a layman first?",a="Druidic mentors believe that receiving Cenarius's miraculous gift of curing venom with a mere incantation can breed complacency. By making initiates study and solve venom crises through herbal and mundane methods first, they ensure the druid truly respects the burden and suffering poison causes.",al={"why layman","why cure poison without magic","cenarius poison lesson"}},{q="What problem is taking place in Auberdine?",a="Auberdine is suffering from an outbreak of severe animal poisonings along the coast of Darkshore. The local night elves have been unable to cure the affliction, prompting them to send a plea for help to the Cenarion Circle in Moonglade.",al={"auberdine poison problem","what is happening in auberdine","darkshore animal poisonings"}},{q="What ability does this quest chain eventually grant?",a="This quest begins the 'Power over Poison' chain, which teaches druids the essential spell Cure Poison, enabling them to magically cleanse toxins from allies.",al={"what reward do i get","cure poison quest","power over poison chain"}},{q="Is this quest available to Horde druids?",a="No. 'Lessons Anew' is specifically the Alliance version of the quest starting in Darnassus. Tauren druids receive a parallel quest starting in Thunder Bluff that also directs them to Moonglade to learn the art of curing poison.",al={"horde lessons anew","can tauren do this","tauren lessons anew"}}},ang={["class:Druid"]="This rite of passage marks your transition from basic shapeshifting and survival into true custodianship of the wilds, teaching you to lift lethal blights and venoms from nature.",["race:NightElf"]="Given by Darnassus's Cenarion Enclave, this quest connects the young kaldorei directly to the deeper ancestral responsibilities of Moonglade and Darkshore.",["faction:Alliance"]="The crisis threatening Auberdine highlights how essential druidic aid is to securing the fragile northern Alliance settlements in Darkshore."},kw={"auberdine","cenarius","cure poison","dendrite starblaze","lessons anew","mathrengyl bearwalker","moonglade","nighthaven","power over poison"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","quest:6125","subzone:nighthaven","subzone:auberdine","topic:cenarius","topic:druid","quest:5921"},m={start="Mathrengyl Bearwalker",["end"]="Dendrite Starblaze",level="14",faction="Alliance",id=6121},src={"Lessons Anew (Alliance)"}}
E["quest:6125"] = {t="quest",n="Power over Poison",z="darnassus",s="Power over Poison marks the culmination of a young druid's trial to master venomous afflictions. Having learned to brew an herbal remedy by hand in Darkshore, the initiate returns to Darnassus to receive the Cenarion Circle's magical blessing to cleanse toxins at will.",h="Power over Poison marks the culmination of a young druid's trial to master venomous afflictions.",sec={{t="The Student's Humility",b="Before granting a druid the innate magical ability to purge toxins, the Cenarion Circle demands that initiates understand the suffering of common folk. In Darkshore, Alanndarian Nightsong tasks young practitioners with gathering Earthroot and Lunar Fungus manually, brewing a physical salve to heal stricken wildlife. This lesson ensures that when a druid channels nature's power to cure poison, they do so with deep empathy for those who must fight venom without spiritual intervention.",sp=0},{t="Return to the Enclave",b="Once the physical cure has proven effective in Auberdine, Starblaze sends the druid back across the sea to Darnassus. Within the boughs of the Cenarion Enclave, Mathrengyl Bearwalker awaits their return. Pleased with the initiate's grace under pressure, Mathrengyl formally bestows the art of natural cleansing, granting permanent mastery over venoms. Yet the trial also brings troubling news: the presence of virulent poisons in the wilds around Auberdine points to an unnatural blight disturbing the land's delicate balance.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest concludes the druid trial for curing poisons. After successfully preparing a physical salving mixture for Dendrite Starblaze in Moonglade and Darkshore, the student returns to Mathrengyl Bearwalker in Darnassus to learn the innate magical spell Cure Poison.",al={"why do power over poison","power over poison objective","cure poison quest"}},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid stationed at the sacred haven of Nighthaven in Moonglade. He guides initiates through their spiritual trials, testing their patience and dedication to nature before sending them back to their home trainers.",al={"dendrite starblaze role","who gives power over poison"}},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a master druid trainer residing in the Cenarion Enclave in Darnassus. He oversees the development of night elf druids within the boughs of Teldrassil, teaching forms, restorative arts, and the solemn duties of the Cenarion Circle.",al={"mathrengyl bearwalker lore","bearwalker darnassus"}},{q="Why was the druid required to make a cure by hand first?",a="Dendrite Starblaze teaches that a druid must understand the physical toll of poison and the labor required to treat it without magic. By gathering mundane ingredients and aiding the sick manually, the initiate learns humility and appreciation for the natural gifts they are about to receive.",al={"why make herbal cure","lesson of power over poison"}},{q="What concerns Mathrengyl about the situation in Auberdine?",a="Mathrengyl notes that the sudden introduction of lethal toxins in the Darkshore wilds around Auberdine is unnatural. Disruptions to native wildlife and flora threaten the ecological balance, suggesting a corrupting influence at work along the misty coast.",al={"auberdine poison lore","mathrengyl concern"}}},ang={["class:Druid"]="This rite of passage bridges humble herbalism with sacred restorative magic, marking the moment a druid gains direct power to neutralize venom with nature's grace.",["race:NightElf"]="Undertaken in the Cenarion Enclave of Darnassus, this trial reflects the Kaldorei reverence for balance and the solemn stewardship of their ancient forests."},kw={"auberdine","cenarion enclave","cure poison","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","power over poison"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","zone:darnassus","topic:druid","subzone:auberdine"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="14",faction="Alliance",id=6125},src={"Power over Poison (Alliance)"}}
E["quest:6344"] = {t="quest",n="Nessa Shadowsong",z="darnassus",s="Nessa Shadowsong is an introductory courier quest offered by Mydrannul in Darnassus. It guides fledgling adventurers down from the World Tree to Rut'theran Village to meet the fishing merchant Nessa Shadowsong. This task serves as the initial step connecting the canopy capital to the shores and harbors below.",h="Nessa Shadowsong is an introductory courier quest offered by Mydrannul in Darnassus.",sec={{t="A Errand Beyond the Canopy",b="Within Darnassus, Mydrannul watches over travelers looking for work and purpose. When fishing merchant Nessa Shadowsong needs a package delivered across the sea to Darkshore, Mydrannul directs able couriers toward the coast. While many young night elves spend their early journeys entirely within the boughs of Teldrassil, this simple request encourages them to look outward to the mainland.",sp=0},{t="Descending to the Docks",b="Reaching Rut'theran Village requires stepping through the glowing roots of the city's western portal near the Temple Gardens. The gateway descends through the World Tree to its ocean-level roots, where fishing docks and hippogryph perches connect Teldrassil to the rest of Kalimdor. There, Nessa Shadowsong tends to her trade, preparing shipments meant for the port settlement of Auberdine.",sp=0}},faq={{q="Who starts this quest?",a="The quest is offered by Mydrannul, located within Darnassus near the tradesmen and craftsmen areas.",al={"quest giver","where to get nessa shadowsong quest","mydrannul location"}},{q="How do I get to Rut'theran Village?",a="Head west of the Temple Gardens in Darnassus. Step through the large, glowing tree portal to be transported instantly down to Rut'theran Village at the base of Teldrassil.",al={"how to reach ruttheran","rut'theran portal","exit darnassus"}},{q="Who is Nessa Shadowsong?",a="Nessa Shadowsong is an elven fishing supplier stationed at the docks of Rut'theran Village. She oversees goods and parcels moving between Teldrassil and the mainland of Darkshore.",al={"nessa shadowsong role","what does nessa do","nessa shadowsong npc"}},{q="Where does this quest chain lead?",a="Speaking with Nessa immediately leads into 'The Bounty of Teldrassil', which introduces adventurers to the flight master and provides their first flight across the water to Auberdine.",al={"what comes after nessa shadowsong","next quest in chain","teldrassil flight chain"}},{q="Is Nessa related to Maiev Shadowsong?",a="While they share the surname Shadowsong, there is no recorded personal connection between Nessa, a humble dockside fishing merchant, and the legendary warden Maiev Shadowsong.",al={"nessa maiev relation","shadowsong family","is nessa related to maiev"}},{q="Why is this errand important for young adventurers?",a="It acts as the primary navigational breadcrumb teaching new heroes how to exit the crown of Teldrassil, discover the docks below, and learn to use hippogryph flight paths to reach mainland Kalimdor.",al={"why do this quest","significance of quest"}}},ang={["race:NightElf"]="For night elf adventurers, this journey marks the traditional departure from the tranquil heights of Darnassus to the bustling coastal routes that link their new home with the ancient shores of Darkshore.",["faction:Alliance"]="This errand introduces the critical logistics network tying the isolated island of Teldrassil to the rest of the Alliance territories on Kalimdor."},kw={"auberdine","courier","darkshore","darnassus","mydrannul","nessa shadowsong","portal","rut'theran village","temple gardens"},rel={"quest:6341","quest:6342","quest:6343","subzone:rut-theran-village","zone:darnassus","subzone:temple-gardens","npc:mydrannul","zone:darkshore"},m={start="Mydrannul",["end"]="Nessa Shadowsong",level="10",faction="Alliance",id=6344},src={"Nessa Shadowsong (quest)"}}
E["quest:730"] = {t="quest",n="Trouble in Darkshore?",z="darnassus",s="Trouble in Darkshore? is an introductory Alliance quest offered by Chief Archaeologist Greywhisker in Darnassus. Concerned after weeks of silence from an excavation team sent across the sea, he asks travelers to journey to Auberdine to investigate their disappearance. It bridges the dwarven scholarly expedition with the wild, shadowy coast of Darkshore.",h="Trouble in Darkshore?",sec={{t="A Silent Expedition",b="In the grand night elven capital of Darnassus, dwarven researchers from Ironforge pursue the ancient mysteries of Kalimdor. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to unearth artifacts of antiquity. When weeks go by without a single missive or progress report, Greywhisker grows anxious, fearing that his field crew has encountered perils they were ill-equipped to survive alone.",sp=0},{t="Threats Unburied",b="Greywhisker laments that many in the Alliance dismiss dwarven archaeology as little more than an eccentric hobby. However, findings in Khaz Modan have convinced his colleagues that an ancient, terrifying force threatens Azeroth spanning from Lordaeron to Kalimdor. Digging into Darkshore's ruins is not merely an academic endeavor—it is an effort to understand historic cataclysms and the deep-seated menaces buried beneath ancient soil.",sp=0},{t="Contact at Auberdine",b="Upon sailing across the channel from Teldrassil to the coastal haven of Auberdine, travelers find Archaeologist Hollee waiting in town. Relieved that the Chief Archaeologist sent assistance, Hollee reveals that the expedition is indeed in dire straits, having run into trouble farther down the coast while searching for ancient relics.",sp=1}},faq={{q="Who starts the quest Trouble in Darkshore?",a="Chief Archaeologist Greywhisker offers the quest in the night elven capital of Darnassus, seeking brave adventurers willing to check on his missing crew.",al={"who gives trouble in darkshore","quest giver trouble in darkshore","where to get trouble in darkshore"}},{q="Where do I need to go to complete this quest?",a="You need to travel from Darnassus across the sea to the port town of Auberdine in Darkshore, where you will find Archaeologist Hollee.",al={"where do i go","turn in location","who do i turn this in to"}},{q="Why are dwarven archaeologists in Darnassus and Darkshore?",a="Following recent discoveries in Khaz Modan, dwarven researchers began investigating ancient sites across Kalimdor to uncover clues about ancient forces threatening Azeroth.",al={"why are dwarves in darnassus","dwarves in darkshore","dwarven archaeology kalimdor"}},{q="What happens after finding Archaeologist Hollee?",a="Speaking with Archaeologist Hollee in Auberdine leads directly into 'The Absent Minded Prospector', asking you to venture into Darkshore's wilderness to locate Prospector Remtravel.",al={"what comes next","follow up quest","next quest"}},{q="Why hasn't the excavation crew reported back?",a="The team encountered unexpected dangers and setbacks out in the field in Darkshore, leaving individual members separated and cut off from communicating with Darnassus.",al={"what happened to the dig","why did they disappear","crew missing"}},{q="What looming threat is Greywhisker referring to?",a="Greywhisker references discoveries unearthed in Khaz Modan that suggest an ancient, pervasive danger slumbering deep within Azeroth's historic ruins.",al={"what ancient threat","greywhisker warning","khaz modan threat"}}},ang={["race:Dwarf"]="For dwarves, this quest touches on the Explorer's League tradition of digging into titan lore and ancient history across new continents.",["race:NightElf"]="Night elves may view the arrival of pickaxe-wielding dwarven excavators in their ancestral coastal ruins with cautious amusement or quiet concern.",["faction:Alliance"]="This task demonstrates the growing cooperation between Ironforge and Darnassus, linking travelers between Teldrassil and mainland Kalimdor."},kw={"archaeologist","auberdine","darkshore","darnassus","explorers league","greywhisker","hollee","trouble in darkshore"},rel={"npc:chief-archaeologist-greywhisker","npc:archaeologist-hollee","quest:729","zone:darkshore","subzone:auberdine","topic:alliance","topic:lordaeron"},m={start="Chief Archaeologist Greywhisker",["end"]="Archaeologist Hollee",level="14",faction="Alliance",id=730},src={"Trouble in Darkshore?"}}
E["quest:7671"] = {t="quest",n="Frostsaber Replacement",z="darnassus",s="Frostsaber Replacement is a quiet exchange overseen by Lelanai in the leafy enclave of Darnassus. It allows riders who once commanded the older breeds of night elf mounts, such as the Ancient Frostsaber, to trade in their reins for newer breeds raised in the boughs of Teldrassil. While a simple administrative arrangement, it reflects the ongoing shifts in how the night elves equip and supply Alliance travelers.",h="Frostsaber Replacement is a quiet exchange overseen by Lelanai in the leafy enclave of Darnassus.",sec={{t="A Change of Mounts",b="In the Enclave of the Night Elves within Darnassus, trainers and breeders oversee the fierce great cats that serve as mounts for the kaldorei. Over recent years, older lineages of frostsaber mounts—such as the ancient, unarmored breeds—have grown increasingly scarce, replaced by newly trained lines bred for endurance and war across Kalimdor. Handlers like Lelanai facilitate exchanges for riders holding older reins wishing to update their stable companion.",sp=0},{t="The Breeders of Darnassus",b="Lelanai tends to the night elves' mounts near the Cenarion Enclave, providing the iconic frostsaber cats to trusted champions of the Alliance. When older tack and lineages are returned to her, they are retired gracefully or re-fitted to match the standard harnesses utilized by the Sentinels and allied forces.",sp=0}},faq={{q="What is Frostsaber Replacement?",a="It is an exchange offered by Lelanai in Darnassus, allowing an adventurer possessing an older breed of frostsaber, specifically the Ancient Frostsaber, to trade their reins for an updated mount.",al={"what is this quest","frostsaber replacement quest","exchange mount"}},{q="Who is Lelanai?",a="Lelanai is the night elf sabercat handler stationed at the Cenarion Enclave in Darnassus. She sells night elf racial mounts and handles trades for adventurers seeking to acquire or change their frostsaber mounts.",al={"lelanai","lelanai darnassus","who is the cat vendor"}},{q="Where does this trade take place?",a="This exchange occurs in Darnassus, located high within the crown of the great tree Teldrassil, near the trainer platforms of the Cenarion Enclave.",al={"where do i go","quest location","where is lelanai"}},{q="Why were older frostsaber mounts replaced?",a="As kaldorei breeders standardized gear and war harnesses for the Alliance, older variants—like the swift, unarmored ancient frostsaber breeds—were phased out in favor of newer stock, prompting handlers like Lelanai to exchange older bridles for active riders.",al={"why change cats","why replace frostsaber","ancient frostsaber trade"}},{q="Can members of other Alliance races do this exchange?",a="Any Alliance champion who earned the trust of Darnassus and secured an older Ancient Frostsaber mount can present their reins to Lelanai for the exchange.",al={"can humans do this","is it night elf only","alliance mounts"}},{q="Do you lose your original cat when you complete this?",a="Yes. Surrendering the reins of the Ancient Frostsaber to Lelanai permanently exchanges it for a modern breed, meaning the older lineage cannot be reclaimed once turned in.",al={"keep ancient mount","do i lose my mount","lose frostsaber"}}},ang={["race:NightElf"]="The great cats of Teldrassil and Winterspring are revered kin and steadfast companions to the kaldorei, nurtured under the watchful guidance of caretakers like Lelanai.",["faction:Alliance"]="Allied champions of the Alliance who demonstrate sufficient standing with Darnassus are welcomed to bond with and ride these sacred frostsaber breeds."},kw={"ancient frostsaber","cenarion enclave","darnassus","frostsaber replacement","lelanai","night elf mount","reins","teldrassil"},rel={"npc:lelanai"},m={start="Lelanai",level="1",faction="Alliance",id=7671},src={"Frostsaber Replacement"}}
E["quest:7672"] = {t="quest",n="Nightsaber Replacement",z="darnassus",s="Nightsaber Replacement is an exchange offered by Lelanai, the saber handler in Darnassus. It allows riders who hold the reins of an older or unarmored nightsaber mount to trade them in. This simple service ensures that night elf cavaliers and their allies maintain their bond with these fierce predators of Teldrassil.",h="Nightsaber Replacement is an exchange offered by Lelanai, the saber handler in Darnassus.",sec={{t="The Saber Handlers of Darnassus",b="Within the serene groves of Darnassus, Lelanai tends to the pride of the night elves: the fierce, predatory sabers native to Kalimdor. Night elves have fought alongside these massive cats for millennia, relying on their speed, keen night vision, and silent tread in the deep shadows of the forest. Caring for and outfitting these majestic beasts is an honored task among the Sentinels and their allies, ensuring every mount is fit for the trials of the wilds.",sp=0},{t="Trading the Reins",b="The exchange represented by this quest allows a rider in possession of an older pair of nightsaber reins to surrender them to Lelanai in return for a replacement. Whether due to changes in stable outfitting or replacing an older breed of mount, the saber handler assists riders in swapping their mounts to maintain proper care and readiness across the Alliance vanguard.",sp=0}},faq={{q="What is the purpose of Nightsaber Replacement?",a="This exchange allows players to trade in an older version of their Nightsaber mount reins with Lelanai in Darnassus to receive a replacement mount.",al={"what does nightsaber replacement do","why replace nightsaber","nightsaber exchange purpose"}},{q="Who offers this exchange?",a="Lelanai, the night elf saber trainer and vendor stationed in Darnassus, oversees the breeding, training, and exchange of nightsaber mounts.",al={"who gives nightsaber replacement","lelanai quest","who is lelanai"}},{q="Where is Lelanai located?",a="Lelanai can be found in the Cenarion Enclave in Darnassus, tending to the stable of prowling nightsabers beneath the boughs of Teldrassil.",al={"where is lelanai","lelanai location","saber vendor darnassus"}},{q="Why do night elves ride sabers?",a="Nightsabers are indigenous predators of northern Kalimdor. Renowned for their ferocity, agility, and keen nocturnal senses, they have served as loyal companions and war mounts for the Sentinels across thousands of years.",al={"night elf mounts lore","why sabers","nightsaber lore"}},{q="Can members of other Alliance races ride nightsabers?",a="Yes, but non-night elf members of the Alliance must earn deep trust and exalted reputation with Darnassus before Lelanai and the night elves will permit them to purchase or train to ride a nightsaber.",al={"can humans ride nightsabers","cross faction mounts","can dwarves ride cats"}},{q="Do you need special training to ride a nightsaber?",a="Yes. Handling a fierce nightsaber requires specific tiger riding training, which is taught by the saber trainers in Darnassus.",al={"riding skill for nightsaber","tiger riding training"}}},ang={["race:NightElf"]="Nightsabers are cultural symbols and combat partners for the kaldorei, nurtured from cubs to carry Sentinels through Ashenvale and Teldrassil.",["faction:Alliance"]="The Alliance relies heavily on the swift scouting and shock cavalry provided by night elf saber riders in the untamed wilderness of Kalimdor."},kw={"darnassus","exchange","lelanai","mount","nightsaber","reins","saber"},rel={"npc:lelanai"},m={start="Lelanai",level="1",faction="Alliance",id=7672},src={"Nightsaber Replacement"}}
E["quest:8718"] = {t="quest",n="Bladeswift the Elder",z="darnassus",s="Elder Bladeswift is an ancestral spirit honored during the Lunar Festival within the night elven capital of Darnassus. Located in the Cenarion Enclave, this ancient figure offers travelers wisdom drawn from the starry heavens above. Seeking his blessing connects adventurers directly to the revered traditions of the Cenarion Circle and the night elven people.",h="Elder Bladeswift is an ancestral spirit honored during the Lunar Festival within the night elven capital of...",sec={{t="A Spirit of the Boughs",b="During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth to share their wisdom and bestow blessings upon travelers. Bladeswift the Elder stands amidst the serene boughs of the Cenarion Enclave in Darnassus. Unlike modern residents preoccupied with the trials of the present, this spectral forebear looks upward to the cosmos, contemplating the mysteries woven into the night sky.",sp=0},{t="Starlight and Ancient Truths",b="Night elven culture has long revered the celestial bodies as reflections of Elune and the deeper secrets of existence. Bladeswift reminds those who approach him that the countless stars hold answers to worldly struggles, urging the wise and fortunate to gaze upward. By acknowledging his presence, adventurers receive a Coin of Ancestry and take part in a timeless ceremony bridging the mortal realm with the spirits of the past.",sp=0}},faq={{q="Who is Elder Bladeswift?",a="Elder Bladeswift is an ancestral night elf spirit honored during the seasonal Lunar Festival. He appears in Darnassus to offer philosophical guidance and blessings to travelers seeking to honor their forebears.",al={"who is bladeswift","elder bladeswift lore","bladeswift identity"}},{q="Where can Elder Bladeswift be found?",a="He can be found standing in the Cenarion Enclave within the night elf capital of Darnassus, overlooking the tranquil ponds and wooden walkways of the tree city.",al={"bladeswift location","where is elder bladeswift","bladeswift darnassus"}},{q="What is the purpose of seeking out the elders?",a="Visiting the elders is a core tradition of the Lunar Festival. By paying respects to these ancient spirits across the world, adventurers celebrate the wisdom of the past, earning Coins of Ancestry and seasonal goodwill.",al={"why find elders","lunar festival elders purpose","visiting elders"}},{q="What does Bladeswift teach those who speak with him?",a="Bladeswift encourages seekers to look to the heavens. He suggests that the countless stars hold profound truths and answers to earthly mysteries for those patient and wise enough to observe them.",al={"bladeswift message","what does bladeswift say"}},{q="Can members of the Horde visit Elder Bladeswift?",a="While Bladeswift resides deep inside Darnassus—an Alliance capital guarded by vigilant Sentinels—the seasonal spirit himself welcomes any respectful traveler, though Horde visitors must brave hostile guards to reach him.",al={"can horde talk to bladeswift","horde bladeswift elder","bladeswift alliance only"}},{q="Why is an elder present on Teldrassil if it is a new World Tree?",a="Although Teldrassil was grown only recently following the Third War, the spirits of the Kaldorei ancestors are drawn to the living heart of their people, appearing near their kin to observe the festival.",al={"why is bladeswift in darnassus","teldrassil elder lore"}}},ang={["race:NightElf"]="Standing before Elder Bladeswift in Darnassus is a direct communion with your people's celestial heritage and devotion to the heavens.",["class:Druid"]="As stewards of nature aligned with the Cenarion Circle, druids carry a deep cultural and spiritual duty to honor ancient spirits like Bladeswift.",["faction:Alliance"]="Situated safely inside Darnassus, Elder Bladeswift offers Alliance heroes an easy and peaceful pilgrimage during the Lunar Festival."},kw={"ancestors","bladeswift","coin of ancestry","craftsmen's terrace","darnassus","elder bladeswift","lunar festival","teldrassil"},m={id=8718},src={"Bladeswift the Elder"}}
E["quest:922"] = {t="quest",n="Rellian Greenspyre",z="darnassus",s="This errand sends you from Denalan's lakeside retreat in Teldrassil into the capital city of Darnassus. Handing over a timberling seed to the druid Rellian Greenspyre reveals disturbing news about the spreading corruption in the boughs of the World Tree.",h="This errand sends you from Denalan's lakeside retreat in Teldrassil into the capital city of Darnassus.",sec={{t="A Courier to the Capital",b="Denalan has spent considerable effort cultivating and understanding the flora and elemental life around Lake Al'Ameth. Having collected seeds from the local timberlings, he dispatches you into Darnassus to present a sample to his colleague, Rellian Greenspyre. Rellian, a fellow druid who walks the tranquil terraces of the Cenarion Enclave, previously voiced curiosity about Denalan's research and hopes to raise a timberling of his own.",sp=0},{t="Tainted Growth",b="Upon receiving the seed, Rellian brings grim tidings instead of scholarly optimism. His recent investigations have confirmed that the timberlings across Teldrassil are falling victim to an aggressive, pervasive corruption. Worse still, seeds harvested from tainted specimens already carry their parents' blight. Rellian admits that cleansing them lies beyond his personal prowess, suggesting that only Denalan's deep affinity for living things offers any lingering hope of restoring balance.",sp=1}},faq={{q="Who is Rellian Greenspyre?",a="Rellian Greenspyre is a night elf druid who can be found wandering the pathways of the Cenarion Enclave in Darnassus. He maintains close scholarly ties with Denalan, sharing an interest in the ecology and elemental spirits of Teldrassil.",al={"rellian greenspyre lore","who is rellian","rellian greenspyre location"}},{q="Why does Denalan send a timberling seed to Rellian?",a="Denalan gathered timberling seeds at Lake Al'Ameth with your assistance. Remembering that Rellian had expressed interest in timberling biology and possessed theories of his own, Denalan offers a seed so Rellian can attempt to grow one in the capital.",al={"why send timberling seed","denalan's errand"}},{q="What problem does Rellian discover?",a="Rellian discovers that an unnatural corruption has infected the timberlings. Consequently, the seeds harvested from them are already warped by their parents' blight, making it impossible to cultivate healthy sprouts without first discovering a cure.",al={"what is wrong with the timberling seed","timberling corruption"}},{q="Where does this task lead next?",a="Rellian cannot cure the corrupted seeds himself, so he directs your attention toward investigating the mossy tumors afflicting the timberlings, hoping Denalan can synthesize a remedy from further specimens.",al={"what comes after rellian greenspyre","next quest after rellian"},sp=1},{q="Where can Rellian Greenspyre be found?",a="Rellian walks the open pathways through the Cenarion Enclave, situated in the northwestern corner of Darnassus.",al={"where is rellian","rellian map location"}},{q="Why can't Rellian cleanse the seeds himself?",a="The deep-rooted nature of the corruption exceeds Rellian's specific talents. He defers to Denalan's extraordinary skill with botany and cultivating living things, deeming his friend the best hope for curing future generations of timberlings.",al={"why cant rellian cure them","rellian druid powers"}}},ang={["class:Druid"]="For Cenarion initiates, this errand highlights how deeply an unforeseen malaise has penetrated Teldrassil's newly sprouted ecosystem, underscoring the urgent need to preserve native elemental life.",["race:NightElf"]="The timberlings were meant to flourish alongside Teldrassil's growth, making Rellian's discovery of hereditary corruption a worrying sign for the new homeland of the kaldorei."},kw={"cenarion enclave","corruption","darnassus","denalan","rellian greenspyre","teldrassil","timberling seed"},rel={"npc:denalan","quest:923","zone:darnassus","topic:druid"},m={start="Denalan",["end"]="Rellian Greenspyre",level="7",faction="Alliance",id=922},src={"Rellian Greenspyre (Classic)"}}
E["quest:923"] = {t="quest",n="Tumors",z="darnassus",s="Assisting the Cenarion Circle in Darnassus, this task sends adventurers to cull the afflicted timberlings around Wellspring Lake in northern Teldrassil. By collecting mossy tumors from these twisted nature spirits, druids hope to study the spreading poison and safely incinerate the corrupting growths.",h="Assisting the Cenarion Circle in Darnassus, this task sends adventurers to cull the afflicted timberlings...",sec={{t="Blight upon the Timberlings",b="Teldrassil was raised to be a sanctuary of harmony, but a strange affliction has begun twisting its native flora and fauna. Timberlings—typically placid, bark-skinned nature spirits—have grown hostile and erratic. Upon their living wood, grotesque mossy tumors have sprouted, pulsing with a foul, unnatural poison. While Cenarion scholars like Denalan and Rellian Greenspyre search for the root cause of this sickness, those creatures already lost to the malevolence must be culled to protect the rest of the boughs.",sp=0},{t="Containment at Wellspring Lake",b="Wellspring Lake in northern Teldrassil has become a focal point for the outbreak. The timberlings wandering its shores are among the most heavily tainted on the entire world tree. Rellian Greenspyre charges travelers with cutting down these corrupted guardians and excising their growths. By bringing the tumors directly to the druids in Darnassus to be safely burned, the night elves hope to stem the spread of the contagion before the waters of the lake poison the rest of the boughs.",sp=0}},faq={{q="Why are the timberlings growing tumors?",a="A mysterious sickness has taken root in Teldrassil's wild spirits. The mossy tumors are outward physical symptoms of a toxic taint coursing through their bodies, twisting their natural protective instincts into blind aggression.",al={"what is wrong with timberlings","timberling disease","why timberlings sick"}},{q="Who is Rellian Greenspyre?",a="Rellian Greenspyre is a night elf researcher affiliated with the Cenarion Circle, stationed in Darnassus. He works closely with other botanists like Denalan to study the strange corruptions plaguing Teldrassil's ecosystem.",al={"rellian greenspyre lore","who is greenspyre","rellian greenspyre"}},{q="Why must the tumors be burned?",a="The tumors contain a potent, contagious poison. If left to rot in the wilderness or seep into the soil, the corruption could spread further into Teldrassil's roots. Rellian incinerates them to permanently neutralize the blight.",al={"burn tumors","why burn the tumors","destroying mossy tumors"}},{q="Where is Wellspring Lake?",a="Wellspring Lake lies in the northern reaches of Teldrassil, fed by the bough's pristine waterways. The timberlings surrounding its shores are noticeably more diseased than those found elsewhere.",al={"wellspring lake location","where to find timberlings","where are mossy tumors"}},{q="Can the timberlings be cured instead of killed?",a="The Cenarion Circle is actively searching for a cure or origin for the blight, but the timberlings wandering Wellspring Lake are deemed already beyond help. Until the source is identified, putting down the most aggressive spirits is the only way to safeguard the forest.",al={"can timberlings be saved","curing timberlings"}},{q="What happens after bringing the tumors to Darnassus?",a="After Rellian secures and destroys the tumors, he directs adventurers back to the field botanist Denalan near Lake Al'Ameth to continue investigating the corruption spreading through Teldrassil's flora.",al={"after tumors quest","what next tumors"}}},ang={["class:Druid"]="For druids of the Cenarion Circle, destroying corrupted nature spirits is a tragic but necessary duty to protect Teldrassil's fragile balance from total collapse.",["race:NightElf"]="The rapid appearance of disease on the newly grown World Tree is an alarming sign to the Kaldorei, challenging Fandral Staghelm's promise of an untouched haven.",["profession:Herbalism"]="Herbalists and botanists are unsettled to see living wood and moss warp into venomous, malignant tumors rather than healthy foliage."},kw={"cenarion circle","corruption","darnassus","denalan","mossy tumor","rellian greenspyre","teldrassil","timberling","tumors","wellspring lake"},rel={"quest:922","quest:2498","subzone:wellspring-lake","zone:darnassus","quest:940"},m={start="Rellian Greenspyre",level="9",faction="Alliance",id=923},src={"Tumors"}}
E["quest:9262"] = {t="quest",n="Investigate the Scourge of Darnassus",z="darnassus",s="Investigate the Scourge of Darnassus is an emergency mission issued by Lieutenant Beitha on behalf of the Argent Dawn. As the Lich King's airborne necropolises loom overhead, Alliance defenders are tasked with destroying encroaching undead and deciphering the dark runic circles appearing outside the city gates.",h="Investigate the Scourge of Darnassus is an emergency mission issued by Lieutenant Beitha on behalf of the...",sec={{t="A Plague on the World Tree",b="The Scourge invasion has reached the sheltered boughs of Teldrassil. Floating necropolises appear in the sky, vomiting forth ghouls, skeletons, and necromantic horrors right outside Darnassus. Lieutenant Beitha of the Argent Dawn has stepped forward to coordinate the capital's defense, enlisting willing volunteers to blunt the vanguard and gather intelligence before the undead can overwhelm the night elven homeland.",sp=0},{t="Whispers in the Runes",b="Beyond simply slaying the undead and collecting their dim necrotic stones, scouts are directed to inspect strange, glowing runic formations pulsing on the ground near the invasion encampments. Stepping close to these circles exposes defenders to unsettling supernatural whispers, revealing that the runes serve as unnatural communication relays transmitting commands from the necropolis overhead and the dark masters of the Scourge.",sp=1}},faq={{q="Who is Lieutenant Beitha?",a="Lieutenant Beitha is an officer representing the Argent Dawn stationed at Darnassus. She organizes local resistance against the Scourge invasion, distributing tasks to curb undead numbers and study their necromantic apparatus.",al={"who gives investigate the scourge of darnassus","beitha quest giver","lieutenant beitha lore"}},{q="Why is the Scourge attacking Darnassus?",a="Under the orders of the Lich King, the Scourge has dispatched necropolises worldwide to sow terror and destroy major mortal population centers. Even the secluded haven of Teldrassil is not exempt from the undead assault.",al={"why are undead in darnassus","teldrassil invasion","lich king attacking night elves"}},{q="What are the glowing runic circles outside the city?",a="The runic circles are magical conduits linked to the hovering necropolises. Closer inspection reveals sinister voices speaking through them, confirming that the Scourge uses these markings to coordinate their forces and relay necromantic directives.",al={"scourge runes darnassus","runic circles outside darnassus","what are the invasion runes"}},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones are crystallized conduits of dark magic carried by Scourge foot soldiers. They serve both as fuel for necromantic abilities and as tangible proof of slain undead for the Argent Dawn.",al={"necrotic stones","what do necrotic stones do","dim necrotic stone lore"}},{q="Who is funding or leading the response in Darnassus?",a="The defense against this invasion is spearheaded locally by the Argent Dawn, an independent order devoted to battling the Scourge across Azeroth, cooperating directly with the Alliance sentinels guarding Darnassus.",al={"who leads defense of darnassus","argent dawn darnassus"}},{q="Can listening to the runic circles harm you?",a="The runes pulse with unnatural mental energy and dark whispers capable of fraying mortal minds. Lieutenant Beitha notes with relief whenever an investigator returns with their sanity intact after contacting the runes.",al={"runic circles whispers","runic circle voices danger"}}},ang={["race:NightElf"]="For the Kaldorei, the presence of rotting necropolises and defiling undead so close to Teldrassil's holy ground is a grotesque violation that must be purged immediately.",["faction:Alliance"]="The defense of Darnassus demonstrates the Alliance's commitment to standing united against the global threat posed by the Lich King's invasion force.",["class:Priest"]="Priests face the chilling test of examining corrupted necromantic runes, using their mental discipline and faith to resist the madness whispering through the Scourge's dark network.",["class:Druid"]="The spread of necromancy and decaying flesh on Teldrassil's soil represents an unnatural blight that every protector of the wild is sworn to eradicate."},kw={"argent dawn","beitha","darnassus","lich king","necropolis","necrotic stone","runic circle","scourge","teldrassil","undead"},rel={"npc:lieutenant-beitha","zone:darnassus","topic:argent-dawn","topic:scourge","topic:lich-king"},m={start="Lieutenant Beitha",level="10",faction="Alliance",id=9262},src={"Investigate the Scourge of Darnassus"}}
E["quest:952"] = {t="quest",n="Grove of the Ancients",z="darnassus",s="Grove of the Ancients is an Alliance delivery quest that directs adventurers out of Darnassus and across the sea to Darkshore. Tasked by Arch Druid Fandral Staghelm, the courier carries correspondence to Onu, a venerable Ancient of Lore residing south of Auberdine.",h="Grove of the Ancients is an Alliance delivery quest that directs adventurers out of Darnassus and across the...",sec={{t="Leaving the Boughs",b="Having assisted with matters concerning the Oracle Glade atop Teldrassil, adventurers find themselves brusquely summoned into further service by Arch Druid Fandral Staghelm. Not one to waste idle hands, Staghelm tasks the messenger with carrying an urgent dispatch across the sea to the ancient forests of Darkshore, instructing them to book flight aboard a hippogryph from the city.",sp=0},{t="A Contrast in Patience",b="Upon reaching Darkshore and traveling south of Auberdine to the Grove of the Ancients, the messenger delivers the missive to Onu. The towering Ancient of Lore accepts the correspondence with quiet reflection, subtly noting Staghelm's relentless impatience. To Onu and the ancient keepers of the forest, all things unfold in their proper time—a calm, enduring wisdom that Shan'do Malfurion Stormrage embodied, but which Staghelm distinctly lacks.",sp=0}},faq={{q="Who starts the quest Grove of the Ancients?",a="Arch Druid Fandral Staghelm provides the quest from the Cenarion Enclave in Darnassus after you complete his prior errand regarding the Oracle Glade.",al={"quest giver grove of the ancients","who gives grove of ancients","fandral staghelm quest"}},{q="Where is the Grove of the Ancients located?",a="The Grove of the Ancients lies on the mainland in Darkshore, situated directly south of the coastal port of Auberdine.",al={"grove of the ancients location","where is grove of ancients","onu location"}},{q="Who is Onu?",a="Onu is a wise and venerable Ancient of Lore resting in Darkshore. As a protector and chronicler of natural wisdom, he receives correspondence from the druidic leadership in Darnassus.",al={"who is onu","onu darkshore","ancient of lore onu"}},{q="How do you reach Darkshore from Teldrassil?",a="Travelers typically take the flight path aboard a hippogryph from Darnassus down through Rut'theran Village and across the water to the port settlement of Auberdine in Darkshore.",al={"how to get to darkshore","travel to auberdine","hippogryph to darkshore"}},{q="Why does Onu mention Shan'do Stormrage?",a="Upon receiving the missive, Onu remarks on Arch Druid Staghelm's restless haste. He reflects that the forest moves at its own pace, a timeless patience that Shan'do Malfurion Stormrage understood and respected.",al={"onu malfurion comment","shan'do stormrage reference","why mention shando"}},{q="What quests come before this one?",a="This quest is the final step in a short three-part sequence that begins with The Enchanted Glade, followed by Teldrassil, before sending you outward to Darkshore.",al={"prerequisites grove of the ancients","grove of the ancients chain","quests before onu"}}},ang={["race:NightElf"]="This task marks the natural transition from the sheltered cradle of Teldrassil to the wider wilds of mainland Kalimdor, highlighting the philosophical contrast between Fandral Staghelm and the teachings of Malfurion Stormrage.",["class:Druid"]="Delivering missives between the Arch Druid in Darnassus and Onu exposes young druids to the differing temperaments among their Cenarion Circle elders, contrasting Staghelm's drive with the quiet patience of an Ancient of Lore.",["faction:Alliance"]="For Alliance champions completing their business in Darnassus, this delivery provides an early incentive to secure hippogryph routes and explore the coastal territory of Darkshore."},kw={"ancient of lore","auberdine","cenarion circle","darkshore","darnassus","fandral staghelm","grove of the ancients","onu","oracle glade"},rel={"quest:940","quest:937","zone:darkshore","subzone:auberdine","topic:druid","subzone:oracle-glade","topic:shan-do"},m={start="Arch Druid Fandral Staghelm",["end"]="Onu",level="11",faction="Alliance",id=952},src={"Grove of the Ancients (quest)"}}
E["subzone:cenarion-enclave"] = {t="subzone",n="Cenarion Enclave",z="darnassus",s="The Cenarion Enclave is the verdant northwestern district of Darnassus, serving as the central gathering place and seat of power for the Cenarion Circle in the capital. While Archdruid Malfurion Stormrage lies slumbering within the Emerald Dream, Archdruid Fandral Staghelm leads the night elven druids from the great hollows and living boughs of this grove.",h="The Cenarion Enclave is the verdant northwestern district of Darnassus, serving as the central gathering...",sec={{t="Heart of the Circle",b="Occupying a high terrace above the Temple Gardens, the Cenarion Enclave is shaped from ancient oaks and ashes marked with runic bark. Convocations of the Cenarion Circle gather within structures molded directly from living wood and stone. With Malfurion Stormrage absent in the Emerald Dream, Archdruid Fandral Staghelm oversees affairs here, pushing his ambitious vision for Teldrassil despite lingering political friction with High Priestess Tyrande Whisperwind. Beyond the druids who meditate among its streams, the enclave also hosts the capital's elven hunters and the stables where skilled riders learn to tame Darnassian nightsabers.",sp=0},{t="Shadows in the Boughs",b="Though renowned as a tranquil sanctuary of nature, the enclave harbors more covert activities. Beneath the hollowed roots of the westernmost bough lies a subterranean refuge used by Darnassus's clandestine rogues, who conduct their quiet business shielded by the rustling canopy above. Druidic elders tolerate this presence, provided the balance of the grove is not disturbed.",sp=0}},faq={{q="Who leads the Cenarion Enclave?",a="Archdruid Fandral Staghelm currently leads the grove and the night elven druids residing in Darnassus. Malfurion Stormrage, the supreme leader of the Cenarion Circle, remains trapped in a deep, unexplained slumber within the Emerald Dream, leaving Staghelm as the de facto authority.",al={"who is in charge here","cenarion enclave leader","fandral staghelm"}},{q="What classes train here?",a="The enclave is the primary home of the capital's druid trainers, who instruct novices among the living trees. Eastern boughs house the city's hunter trainers, while the root warrens beneath the western bough shelter a quiet den of rogue trainers.",al={"trainers in cenarion enclave","druid trainer darnassus","hunter trainer darnassus"}},{q="Where can I buy a nightsaber mount?",a="Riding trainers and breeders tending to Darnassus's prized saber cats are stationed at the base of the eastern tree near the grove's entrance, providing both riding training and nightsaber mounts to eligible Alliance travelers.",al={"nightsaber trainer","night elf mount trainer","darnassus riding trainer"}},{q="What is the Cenarion Circle's stance toward the Alliance?",a="While this district lies within an Alliance capital and is led by the staunchly nationalist Fandral Staghelm, the Cenarion Circle as a broader organization remains dedicated to safeguarding the natural order rather than fighting factional wars. However, the presence of Staghelm makes this particular enclave strongly aligned with night elven regional interests.",al={"is cenarion circle alliance","are druids alliance only"}}},ang={["class:Druid"]="For night elf druids, the Cenarion Enclave is the civil center of your order on Teldrassil, offering training and guidance under the stern direction of Archdruid Fandral Staghelm.",["class:Hunter"]="Hunters gather in the enclave's eastern boughs to hone their marksmanship and wilderness lore alongside beastmasters who rear the capital's nightsabers."},kw={"cenarion circle","cenarion enclave","darnassus","druid","fandral staghelm","nightsaber","teldrassil"},rel={"npc:fandral-staghelm","zone:darnassus","topic:druid","topic:emerald-dream","npc:malfurion-stormrage","npc:tyrande-whisperwind","subzone:temple-gardens","quest:929"},src={"Cenarion Enclave"}}
E["subzone:craftsmen-s-terrace"] = {t="subzone",n="Craftsmen's Terrace",z="darnassus",s="The Craftsmen's Terrace is the bustling artisan district situated in the northern reaches of Darnassus. It serves as the primary trade and manufacturing hub for the night elf capital, housing workshops, profession trainers, and a lively inn. The district also hosts external representatives, including an embassy for the neutral Argent Dawn.",h="The Craftsmen's Terrace is the bustling artisan district situated in the northern reaches of Darnassus.",sec={{t="The Artisan Heart of Darnassus",b="Spanning the northern edge of the canopy city, the Craftsmen's Terrace gathers the diverse trades that keep Darnassus running. Woodworkers, leathercrafters, alchemists, and other artisans operate their shops here, integrating classic night elven methods with practical craft. The district also provides essential community amenities, including an inn, a guild master, and guild petition vendors. Bridges connect the terrace directly to the Cenarion Enclave to the west and the Warrior's Terrace to the south.",sp=0},{t="Outside Ties and Forgotten Lore",b="Despite the kaldorei's historic isolation, the Craftsmen's Terrace is home to foreign connections, most notably an embassy established by the Argent Dawn to coordinate with northern allies against the Scourge. Visitors browsing the district's various workshops might also stumble across scattered scholarly volumes, ranging from historical accounts of the War of the Ancients to chronicles detailing the Second War and esoteric treatises on the Old Gods.",sp=0}},faq={{q="What services are found in the Craftsmen's Terrace?",a="The district houses most of the city's trade profession trainers, craft supply merchants, an inn, and guild registry services. It serves as the commercial center for travelers looking to learn or practice practical skills in Darnassus.",al={"craftsmen services","what is in craftsmens terrace","darnassus trainers"}},{q="Why is the Argent Dawn present in the Craftsmen's Terrace?",a="The Argent Dawn maintains an embassy in the district to liaise with the night elves and recruit aid against the Scourge. Their presence offers a diplomatic bridge between the Alliance forces in the west and the war-torn lands of Lordaeron.",al={"argent dawn darnassus","argent dawn embassy","why argent dawn here"}},{q="How do you reach the Craftsmen's Terrace?",a="The terrace occupies the northern section of Darnassus. You can reach it via bridges leading north from the Warrior's Terrace or east from the Cenarion Enclave.",al={"how to get to craftsmen terrace","craftsmen terrace location","finding craftsmen terrace"}},{q="What notable books can be found around the workshops?",a="Scholarly volumes rest throughout the workshops, including histories of the War of the Ancients, the aftermath of the Second War, and a study on the Old Gods housed within the Argent Dawn's quarters.",al={"craftsmen terrace books","lore books darnassus","books in craftsmens terrace"}}},ang={["race:NightElf"]="For the kaldorei, the terrace is proof of their society's self-reliance on Teldrassil, blending ancient craftsmanship with the day-to-day needs of their new capital.",["faction:Alliance"]="Alliance visitors find the terrace to be one of Darnassus's most welcoming quarters, offering familiar trade supplies, guild administration, and lodging alongside foreign representatives."},kw={"argent dawn","artisans","craftsmen's terrace","craftsmens terrace","darnassus","teldrassil","trainers"},rel={"zone:darnassus","subzone:cenarion-enclave","subzone:warrior-s-terrace","topic:argent-dawn","topic:night-elf","topic:war-of-the-ancients","topic:old-god","topic:second-war"},src={"Craftsmen's Terrace"}}
E["subzone:howling-oak"] = {t="subzone",n="Howling Oak",z="darnassus",s="In the current era of 25 ADP, the Howling Oak does not exist within the night elven capital of Darnassus. While Darnassus flourishes atop Teldrassil as a haven for the kaldorei, Gilneas remains entirely sealed behind the Greymane Wall. Any rumors among travelers regarding a Gilnean settlement or a great worgen oak in northern Darnassus refer to events yet to pass.",h="In the current era of 25 ADP, the Howling Oak does not exist within the night elven capital of Darnassus.",sec={{t="A Sealed Fate",b="Presently in Darnassus, the northern reaches of the city do not house any tree known as the Howling Oak. The human kingdom of Gilneas lies far across the Great Sea, utterly locked away from the world behind the massive stone ramparts of the Greymane Wall. King Genn Greymane and his subjects turned their backs on the Alliance after the Second War, cutting off all diplomatic contact. The night elves of Teldrassil manage their grove, temples, and boughs without any Gilnean presence, focused instead on purifying their fledgling World Tree from corruption.",sp=0},{t="Darnassus in the Present Era",b="Visitors traveling between the Cenarion Enclave and the Craftsmen's Terrace will find only the pristine, tranquil forest and classic kaldorei architecture native to Teldrassil. Neither Gilnean refugees nor their druidic traditions have reached the shores of Kalimdor. Druidism in Darnassus remains the strict domain of the Cenarion Circle, who tend to nature under the watchful eyes of Archdruid Fandral Staghelm and High Priestess Tyrande Whisperwind.",sp=0}},faq={{q="Where is the Howling Oak located?",a="You will not find the Howling Oak in Darnassus today. In 25 ADP, the northern canopy connecting the Craftsmen's Terrace and the Cenarion Enclave is unoccupied by foreign trees, as Gilneas remains sealed behind its southern wall across the sea.",al={"howling oak location","where howling oak","find howling oak darnassus"}},{q="Are there Gilnean refugees in Darnassus?",a="No. The kingdom of Gilneas is fully isolated from the world behind the Greymane Wall, and no refugees or worgen inhabit the night elven capital in this era.",al={"gilneans in darnassus","worgen in darnassus","gilneas refugees"}},{q="What stands in this part of Darnassus right now?",a="The pathways in northern Darnassus connect the crafts and trade districts directly to the Cenarion Enclave, lined with native Teldrassil woodlands, quiet waters, and kaldorei structures rather than any foreign oak.",al={"what is at howling oak","north darnassus area"}}},ang={["race:NightElf"]="Your capital of Darnassus remains an untainted sanctuary for the kaldorei, free from foreign refugees or the mysterious worgen curse.",["class:Druid"]="All druidic instruction in Darnassus is conducted through the Cenarion Circle at the Cenarion Enclave, following ancient kaldorei traditions."},kw={"cenarion enclave","craftsmen's terrace","darnassus","gilneas","howling oak","teldrassil","worgen"},rel={"zone:darnassus","subzone:cenarion-enclave","subzone:craftsmen-s-terrace","quest:940","npc:tyrande-whisperwind","topic:worgen","topic:night-elf","topic:druid"},src={"Howling Oak"}}
E["subzone:temple-gardens"] = {t="subzone",n="Temple Gardens",z="darnassus",s="The Temple Gardens form the tranquil, water-filled heart of Darnassus, surrounding small islets just north of the Temple of the Moon. Decorated with bridges and pristine flora, the district hosts the city bank and the mystical tree portal leading to the base of Teldrassil.",h="The Temple Gardens form the tranquil, water-filled heart of Darnassus, surrounding small islets just north of...",sec={{t="Heart of the Elven Capital",b="Spanning the waters at the center of Darnassus, the Temple Gardens serve as the crossroads of the night elven capital. Wooden bridges connect its landscaped islets to the Cenarion Enclave in the north, the bustling terraces to the east, and the grand sanctuary of the Temple of the Moon to the south. The night elves carefully shape the district's flowing waters and lush foliage, creating a serene atmosphere that offers rest to travelers and priestesses alike.",sp=0},{t="Gateway to Teldrassil",b="Beyond housing the city's central vault and bank on its main island, the Temple Gardens hold critical importance for travelers entering or leaving the World Tree. On the western bank of the gardens stands a massive, glowing pink tree portal. This magical archway provides instantaneous passage down through the boughs to Rut'theran Village at Teldrassil's base, connecting the isolated boughs to the coastal docks and flight paths.",sp=0}},faq={{q="What is the glowing pink portal in the gardens?",a="The glowing tree portal on the western edge of the gardens is the primary transport between the crown of Teldrassil and its base. Stepping through it instantly transports travelers to Rut'theran Village, where ships and hippogryphs connect the night elves to darkshore and the wider world.",al={"tree portal darnassus","pink tree portal","teleporter darnassus"}},{q="Where is the Darnassus bank located?",a="The city's main bank is situated right in the Temple Gardens, housed in an open elven pavilion on the district's largest central island.",al={"darnassus bank location","where is bank","banker darnassus"}},{q="Why are they called the Temple Gardens?",a="The district takes its name from the magnificent Temple of the Moon, which sits directly adjacent to the gardens along their southern border.",al={"temple gardens name origin","why temple gardens"}},{q="Which districts connect to the Temple Gardens?",a="Bridges branch out across the water from the gardens to nearly every quarter: the Cenarion Enclave to the north, the Craftsmen's, Warrior's, and Tradesmen's Terraces to the east, and the Temple of the Moon to the south.",al={"where do temple gardens lead","bridges from temple gardens"}}},ang={["race:NightElf"]="The gardens represent the harmonious blend of wilderness and civic architecture that defines Darnassian culture, offering peace for reflection amidst administrative daily life.",["faction:Alliance"]="Any visitor sailing in through the docks must step through the Rut'theran portal into these tranquil waters to access the rest of the city."},kw={"bank","darnassus","portal","rut'theran","teldrassil","temple gardens","temple of the moon"},rel={"zone:darnassus","subzone:temple-of-the-moon","subzone:rut-theran-village","subzone:cenarion-enclave","subzone:tradesmen-s-terrace","quest:940","quest:2519"},src={"Temple Gardens"}}
E["subzone:temple-of-the-moon"] = {t="subzone",n="Temple of the Moon",z="darnassus",s="The Temple of the Moon stands in Darnassus as the spiritual heart of the night elven people and the seat of government on Teldrassil. Presided over by High Priestess Tyrande Whisperwind, the sanctuary serves as the headquarters for the Sisterhood of Elune. Its towering marble tiers house a sacred moonwell whose blessed waters bring healing and communion with the Moon Goddess.",h="The Temple of the Moon stands in Darnassus as the spiritual heart of the night elven people and the seat of...",sec={{t="Sanctuary of the Moon Goddess",b="Erected shortly after the Third War when the night elves settled Teldrassil, the Temple of the Moon is among the largest stone structures constructed by modern kaldorei hands. Much of its marble was quarried from the Kalimdor mainland and transported across the sea through magical means. At the center of its interior lies an expansive moonwell overseen by the statue of Haidene, where consecrated waters radiate quiet power. Beyond serving as a place of worship and quiet reflection for pilgrims, the temple functions as the political apex of Darnassus, housing High Priestess Tyrande Whisperwind as she guides her people through the dawn of a uncertain new age.",sp=0},{t="The Sisterhood's Bastion",b="Within the temple's quiet terraces, the priestesses of the Sisterhood of Elune carry out the goddess's will both spiritually and tactically. From here, emissaries and dispatched sisters are sent outward across northern Kalimdor to investigate threats or offer aid to local sentinels, such as Priestess Gwennyth Bly'Leggonde's inquiries along the Darkshore coastline. Novices and veteran priestesses alike gather beneath the starry vaulted ceiling to train in divine spellwork, tend to the wounded, and guard the sanctum from outside corruption.",sp=0}},faq={{q="Who leads the Temple of the Moon?",a="High Priestess Tyrande Whisperwind presides over the temple. As the leader of the Sisterhood of Elune and de facto head of the kaldorei government, she holds court on the upper tiers, guiding both the spiritual and military affairs of Darnassus.",al={"temple of the moon leader","who is in the temple","tyrande location"}},{q="How was the temple built on Teldrassil?",a="While Teldrassil was grown from boughs across the ocean, the temple itself is one of the few large stone edifices in Darnassus. Its marble and masonry were quarried from the mainland of Kalimdor and moved to the world tree's summit using magical transportation.",al={"how was temple of the moon built","stone temple darnassus origins"}},{q="What is the pool in the center of the temple?",a="The central pool is a sacred moonwell watched over by the statue of Haidene. Its waters are deeply consecrated and revered as the direct blessing of Elune, utilized by the Sisterhood for cleansing rites, meditation, and powerful restorative magic.",al={"temple moonwell","water in temple of the moon"}},{q="What services can players find here?",a="The temple acts as the primary hub for Priest training in Darnassus. Adventurers also arrive here to report to High Priestess Tyrande Whisperwind and receive guidance or assignments dispatched by the Sisterhood of Elune.",al={"what is in temple of elune","temple trainers darnassus"}}},ang={["class:Priest"]="For Alliance priests—especially night elves—the temple represents the supreme font of Elune's divine mandate and the home of their highest trainers.",["race:NightElf"]="The temple stands as the cultural, spiritual, and civic core of modern kaldorei life, uniting the Sisterhood of Elune and the governance of Teldrassil under one roof."},kw={"darnassus","haidene","moonwell","sisterhood of elune","teldrassil","temple of elune","temple of the moon","tyrande whisperwind"},rel={"zone:darnassus","npc:tyrande-whisperwind","topic:elune","quest:2519","quest:3524","npc:gwennyth-bly-leggonde","npc:malfurion-stormrage","topic:third-war"},src={"Temple of the Moon"}}
E["subzone:tradesmen-s-terrace"] = {t="subzone",n="Tradesmen's Terrace",z="darnassus",s="Tradesmen's Terrace is the bustling commercial heart of Darnassus, situated along the city's southern flank. It brings together craftspeople, merchants, and the local auction house beneath the sweeping wooden architecture of the night elf capital. The terrace serves as the primary trade link connecting artisans with adventurers journeying across Teldrassil and beyond.",h="Tradesmen's Terrace is the bustling commercial heart of Darnassus, situated along the city's southern flank.",sec={{t="The Commercial Hub of Darnassus",b="Occupying the southern stretch of Darnassus, Tradesmen's Terrace houses the capital's mercantile life. While much of the city is devoted to quiet contemplation, wilderness sanctuaries, and spiritual duties, this terrace brings together shopkeepers, tradespeople, and merchants serving both local kaldorei and travelers from the wider Alliance. It contains Darnassus's central auction house, general provisions, and crafting supply stores, making it the essential staging ground for journeys into the wilds. Broad footpaths connect it northward directly to the Warrior's Terrace and westward toward the serene waters of the Temple Gardens and the grand Temple of the Moon.",sp=0},{t="Artisans and Traders",b="Kaldorei crafts prioritize harmony with nature, and the shops here reflect that delicate balance. Even amidst everyday commerce, the terrace operates without the roaring furnaces or smog seen in dwarven or human workshops, favoring quiet stone, curated timber, and woven goods. For visiting adventurers seeking trade contracts, repairs, or materials gathered from Teldrassil's dense boughs, the terrace stands as the principal center of business in northern Kalimdor.",sp=0}},faq={{q="What is Tradesmen's Terrace?",a="Tradesmen's Terrace is the southern marketplace district of Darnassus. It serves as the commercial center for the night elven capital, containing most of the city's merchants, artisans, and its central auction house.",al={"what is this place","tradesmens terrace info","tradesmen terrace darnassus"}},{q="Where is the auction house in Darnassus?",a="The Darnassus auction house is located right here in Tradesmen's Terrace. It provides travelers, traders, and locals access to citywide and Alliance commerce.",al={"darnassus auction house","ah location darnassus","where is ah"}},{q="How do I reach the other districts from here?",a="Paths from Tradesmen's Terrace lead north into the Warrior's Terrace and west toward the Temple Gardens and the towering Temple of the Moon.",al={"exits from tradesmens terrace","where does this terrace lead","how to leave tradesmens terrace"}},{q="What kinds of vendors are found in this district?",a="The terrace hosts a broad variety of general merchants, trade supply vendors, and craftspeople catering to everyday needs, repairs, and goods produced across Teldrassil.",al={"vendors tradesmens terrace","what can i buy here","tradesmen shops"}}},ang={["race:NightElf"]="For the night elves, Tradesmen's Terrace is a rare center of dense urban commerce, adapted to preserve the peaceful canopy of Darnassus without the disruptive industry of other races.",["faction:Alliance"]="The terrace offers Alliance travelers coming through Rut'theran Village access to banking, auctioneers, and essential trade supplies before heading deeper into Kalimdor."},kw={"auction house","darnassus","kaldorei","merchants","shops","teldrassil","tradesmen's terrace","vendors"},rel={"zone:darnassus","subzone:warrior-s-terrace","subzone:temple-gardens","subzone:temple-of-the-moon","topic:night-elf","quest:940"},src={"Tradesmen's Terrace"}}
E["subzone:warrior-s-terrace"] = {t="subzone",n="Warrior's Terrace",z="darnassus",s="The Warrior's Terrace is the eastern district of Darnassus, acting as both a martial training hub and the capital's fortified gateway. Overlooking the road into greater Teldrassil, it houses the city's battlemasters, warrior trainers, and Sentinel patrols.",h="The Warrior's Terrace is the eastern district of Darnassus, acting as both a martial training hub and the...",sec={{t="Shield of Darnassus",b="Positioned at the eastern threshold of Darnassus, the Warrior's Terrace—sometimes referred to as the Hall of Justice—stands as the primary defensive bulwark against incursions from the Teldrassil wilds. Heavily armed Sentinels mounted on nightsabers guard its high arched gates, maintaining a vigilant watch over incoming travelers. Within its open-air plazas, aspiring combatants drill alongside seasoned veterans on extensive dueling grounds and target ranges. The district also serves practical military needs, hosting weapon smiths, armorers, and the battlemasters coordinating night elf forces across the wider world.",sp=0}},faq={{q="What is the purpose of the Warrior's Terrace?",a="The Warrior's Terrace functions as the military heart of Darnassus and its main defensive gateway. It houses the city's martial trainers, battlemasters, dueling grounds, and target ranges, while stationed Sentinels guard the eastern gate leading into the broader boughs of Teldrassil.",al={"what is warrior's terrace","warriors terrace purpose","why warriors terrace"}},{q="Where does the road through the eastern gate lead?",a="The grand gates on the eastern edge of the terrace lead directly out of Darnassus and onto the forest paths of greater Teldrassil, connecting the isolated capital to settlement hubs like Dolanaar and Rut'theran Village below.",al={"where does gate go","warriors terrace gate","east gate darnassus"}},{q="Who guards the district?",a="The district and its perimeter gates are guarded primarily by the Sentinels, the elite night elven standing army. Many patrol the terraces and gateways while mounted atop armored nightsabers.",al={"who protects warriors terrace","sentinels at warriors terrace","darnassus guards"}},{q="Which other districts connect to the Warrior's Terrace?",a="Bridges and walkways link the Warrior's Terrace directly to the Craftsmen's Terrace to the north, the Tradesmen's Terrace to the south, and the lush Temple Gardens toward the center of the city to the west.",al={"connections warriors terrace","how to get to warriors terrace","what connects to warriors terrace"}}},ang={["class:Warrior"]="For warriors training in the night elf capital, this district is your base of operations, providing access to martial instructors, dueling areas, and battlemasters.",["profession:Blacksmithing"]="The terrace hosts the city's blacksmithing trainers and forge facilities, catering to armor and weapon craft alongside the garrison."},kw={"battlemasters","darnassus","dueling grounds","east gate","hall of justice","sentinels","teldrassil","warrior's terrace"},rel={"zone:darnassus","quest:940","subzone:craftsmen-s-terrace","subzone:tradesmen-s-terrace","subzone:temple-gardens","topic:sentinels","topic:night-elf"},src={"Warrior's Terrace"}}
E["zone:darnassus"] = {t="city",n="Darnassus",z="darnassus",s="Darnassus is the serene, open-air capital city of the night elves, built amidst the branches of the newly planted World Tree, Teldrassil. Governed by High Priestess Tyrande Whisperwind alongside the druids of the Cenarion Enclave, it serves as a tranquil sanctuary for an ancient people adapting to mortality. Sheltered across vast terraces surrounding a crystalline lake, it stands as the heart of night elf society and their bridge to the Alliance.",h="Darnassus is the serene, open-air capital city of the night elves, built amidst the branches of the newly...",sec={{t="A Crown High in the Branches",b="Unlike the dense masonry of Stormwind or the carved stone tunnels of Ironforge, Darnassus is broad, quiet, and intimately open to the wilderness. Formed upon the upper canopy of Teldrassil off northern Kalimdor's coast, the capital's graceful wooden structures and winding pathways encircle a tranquil central lake. Elegant bridges connect terraces dedicated to tradesmen, craftsmen, sentinels, and druids, creating an atmosphere that balances civic governance with profound reverence for nature.",sp=0},{t="Refuge of a Mortal People",b="Darnassus is remarkably young for a civilization thousands of years old. Following the Third War and the sacrifice of Nordrassil at Mount Hyjal, the kaldorei suddenly faced the perils of aging and sickness. Seeking a renewal of their lost vitality, Archdruid Fandral Staghelm and his followers planted Teldrassil in defiance of missing Archdruid Malfurion Stormrage's warnings. Darnassus was founded among its immense boughs as an asylum and monument to their survival, though shadows of malaise already whisper among its roots.",sp=0},{t="A Divided Hearth",b="Though peaceful on its surface, Darnassus balances on a delicate political divide. From the towering colonnades of the Temple of the Moon, High Priestess Tyrande Whisperwind guides the spiritual life and military defense of her people through the vigilant Sentinels. Across the waterways in the Cenarion Enclave, Archdruid Fandral Staghelm commands the druids in Malfurion's continuing absence. While both leaders present a united front to their newfound Alliance partners, friction between the priestesses and the druidic circle lingers throughout the city.",sp=0}},faq={{q="How do you travel to Darnassus from the mainland?",a="Because Teldrassil is an island isolated off Kalimdor's northwest coast, travelers must reach Rut'theran Village at the foot of the tree by boat or flight. From the village docks, a glowing magical transport tentacle takes travelers directly up into the city boughs.",al={"how to get to darnassus","travel to darnassus","darnassus entrance"}},{q="Who rules Darnassus?",a="High Priestess Tyrande Whisperwind rules Darnassus and the kaldorei from the grand Temple of the Moon. Archdruid Fandral Staghelm leads the druids of the Cenarion Circle from the Cenarion Enclave, acting as the de facto druidic authority while Malfurion Stormrage remains lost in the Emerald Dream.",al={"darnassus leader","who is in charge","ruler of darnassus"}},{q="Why was the city founded so recently?",a="Darnassus was founded shortly after the Third War. When the night elves sacrificed their immortality to defeat Archimonde at Mount Hyjal, Fandral Staghelm pushed to grow the new World Tree, Teldrassil, to reclaim their former state. Darnassus was carved into the boughs as their new refuge.",al={"why is darnassus new","when was darnassus built","darnassus history"}},{q="Where is Archdruid Malfurion Stormrage?",a="Malfurion Stormrage is missing, his spirit trapped within the Emerald Dream. In his absence, Archdruid Fandral Staghelm governs the druids of Teldrassil, while Tyrande Whisperwind continually seeks a way to awaken and recover her beloved mate.",al={"where is malfurion","is malfurion in darnassus","malfurion location"}},{q="Where are the profession trainers and shops located?",a="The city is divided into specialized terraces. The Craftsmen's Terrace hosts gathering and tailoring disciplines along with an inn, while the Tradesmen's Terrace houses trade stalls and the Auction House. Blacksmithing and martial trainers reside on the Warrior's Terrace, and the city bank rests upon the central island of the Temple Gardens.",al={"darnassus professions","auction house darnassus","darnassus bank"}},{q="Why did the night elves join the Alliance?",a="After the devastation of the Third War, the night elves faced mounting pressure from the Horde, particularly orcish logging expeditions into Ashenvale. Recognizing the need for allies against these incursions and other rising threats across Kalimdor, Darnassus opened diplomatic ties and joined the Grand Alliance.",al={"why are night elves alliance","night elf alliance ties","alliance darnassus"}}},ang={["race:NightElf"]="As the heart of your sovereign civilization, Darnassus is your sanctuary as you navigate the unprecedented trials of mortal existence.",["class:Druid"]="The Cenarion Enclave serves as the nexus of druidic training in Teldrassil, overseen by the demanding and uncompromising Archdruid Fandral Staghelm.",["class:Priest"]="The grand Temple of the Moon is the holy center of the Sisters of Elune, presided over by High Priestess Tyrande Whisperwind herself.",["faction:Alliance"]="Darnassus acts as the westernmost stronghold of the Alliance, providing critical naval and strategic shelter on the continent of Kalimdor."},kw={"cenarion enclave","darnassus","fandral","night elf capital","rut'theran","staghelm","teldrassil","temple of the moon","tyrande","whisperwind"},rel={"subzone:temple-of-the-moon","subzone:cenarion-enclave","subzone:rut-theran-village","npc:tyrande-whisperwind","npc:fandral-staghelm","topic:night-elf","quest:940","zone:ashenvale"},src={"Darnassus"}}
